COLLDATA("sh13064","ur",[[1,"سیدنا ابوسعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ:\nمیں نبی  صلی اللہ علیہ وسلم  کی خدمت میں حاضر ہوا، آپ کو بخار تھا، میں نے چادر کے اوپر اپنا ہاتھ رکھا تو بخار کی حرارت محسو س کی۔ میں نے عرض کیا: اے اللہ کے رسول! آپ کو تو شدید بخار ہے۔فرمایا: ہم انبیاء کی جماعت ہیں، ہمیں تکلیف بھی دو گناہوتی ہے، اجر بھی دو گنا ملتا ہے۔میں نے عرض کیا: اے اللہ کے رسول! لوگوں میں سب سے سخت آزمائش کن کی ہوتی ہے؟ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: انبیاء کی۔ میں نے پوچھا: پھر کن کی؟ آپ  صلی اللہ علیہ وسلم  نے فرمایا: پھر نیک لوگوں کی، کسی شخص کوفقرمیں اس طرح آزمایا جاتا ہے کہ اس کے پاس صرف ایک چادر ہوتی ہے جسے وہ اوڑھتا اور لباس کے طور پر پہنتا ہے اور کسی شخص کو جوؤں سے اس طرح آزمایا جاتا ہے کہ جوئیں اسے ہلاک کر دیتی ہیں، لیکن انہیں اس آزمائش سے گزرنا کچھ دِیے جانے سے اچھا لگتا ہے۔","صحیح",{"k":"مسند أحمد (۳؍۹۴)، سنن ابن ماجہ (۴۰۲۴)، مسند أبی یعلی الموصلی (۱۰۴۵)، المستدرک للحاکم (۱؍۹۹)، المعجم الکبیر للطبرانی (۳؍۳۷۲)، مسند عبد بن حمید (۹۶۰)۔","f":"کسی مرض، تکلیف، مصیبت یا کسی بھی طرح کی آزمائش آن پڑنے پر انسان کو کسی بھی طرح کا شکوہ یا ناشکری قطعاً اپنی زبان پر نہیں لانا چاہیے بلکہ اسے اللہ تعالی کے ساتھ خاص تعلق کی علامت سمجھتے ہوئے پریشانی کی اس حالت میں بھی خوش ہو جانا چاہیے اور بہ خوشی اللہ تعالی کے اس فیصلے کو قبول کرنا چاہیے۔ جب بندہ اللہ کے امتحان میں کامیاب ہو جاتا ہے تو پھر اللہ بھی اس کا دست و بازو بن جاتا ہے اور تمام تر مصائب و مشکلات سے اسے کافی ہو جاتا ہے۔"}],[2,"وھب بن منبہ رحمہ اللہ فرماتے ہیں:\nاللہ تعالی نے آزمائشوں کو پیدا ہی انبیاء کے لیے کیا ہے اور انہیں صبر سے بھی نوازا ہے۔ ایک نبی تو اُون کا کپڑا لیا کرتے اور اسی کو جبہ اور زِرہ بنا کر پہن لیتے۔ ایک نبی کے سر سے جوئیں گرتی رہتی تھیں۔ پھر جب ان پر فراخی کے دِن آتے تھے تو (اللہ تعالی سے) اس خدشے کی وجہ سے ہی دعا فرماتے کہ کہیں وہ ان پر (کوئی چیز نہ مانگنے کی وجہ سے) ناراض نہ ہو۔","حسن",{"k":"الزھد لأحمد بن حنبل، ص: ۳۷۴۔"}],[3,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں:\nمیں نے رسول اللہ  صلی اللہ علیہ وسلم  کی تکلیف سے زیادہ سخت تکلیف کسی کی نہیں دیکھی۔\nمحمد بن خالد السُلمی اپنے دادا، جو کہ صحابئ رسول تھے، سے بیان کرتے ہیں کہ:\nوہ اپنے (مسلمان) بھائیوں میں سے ایک آدمی سے ملنے کے لیے روانہ ہوئے اور اس کے پاس پہنچنے سے پہلے ہی انہیں معلوم ہوا کہ وہ بیمار ہے۔ چنانچہ جب وہ اس کے پاس آئے تو کہا: میں تمہارے کے پاس ملنے، عیادت کرنے اور خوشخبری سنانے آیا ہوں۔ اس نے کہا: آپ نے یہ تمام کام کیسے جمع کر لیے؟ تو انہوں نے کہا: میں جب (گھر سے) نکلا تو تم سے ملنے کا ارادہ تھا، پھر مجھے تمہارے بیمار ہونے کا پتا چلا؛ تو یہ عیادت بن گئی، اور میں تمہیں ایک چیز کی بشارت سناتا ہوں جو میں نے رسول اللہ  صلی اللہ علیہ وسلم  سے سنی ہے۔ آپ  صلی اللہ علیہ وسلم  نے فرمایا: جب بندے کے لیے اللہ تعالی کی طرف سے کوئی مقام و مرتبہ مقدر ہو چکا ہو اور وہ اپنے اعمال کی بناء پر اس تک نہ پہنچ سکتا ہو، تو اللہ تعالی اسے جسمانی طور پر، یا اس کی اولاد و مال کے سلسلے میں آزماتا ہے، پھر اسے صبر کی توفیق بھی مرحمت فرماتا ہے، یہاں تک کہ اسے اس مقام و مرتبے تک پہنچا دیتا ہے جو اس کے لیے اللہ کی طرف سے مقدر ہو چکا ہوتا ہے۔","حسن لغیرہ",{"k":"صحیح بخاری (۵۶۴۷)، صحیح مسلم (۲۵۷۲)۔\nمسند أحمد (۵؍۲۷۲)، سنن أبی داود (۳۰۹۰)، السنن الکبرٰی للبیھقی (۳؍۳۷۴)، شعب الإیمان للبیھقی (۱۲؍۲۷۴)، مجمع الزوائد للھیثمی (۲؍۲۹۲)۔"}],[4,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ:\nمیں نے کسی پر اس سے سخت تکلیف نہیں دیکھی جو تکلیف رسول اللہ  صلی اللہ علیہ وسلم  پر آئی تھی۔","صحیح",{"k":"تاریخ بغداد للخطیب (۴؍۷۶)۔"}],[5,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\nرسول اللہ  صلی اللہ علیہ وسلم  جب بیمار ہوتے تو آپ کی طبیعت بہت گراں ہو جایا کرتی تھی، یہاں تک کہ بسااوقات تو آپ پندرہ پندرہ دِن تک سوتے ہی نہیں تھے۔ آپ صلی اللہ علیہ وسلم  کو کمر کی تکلیف ہوا کرتی تھی۔ (ایک روز) ہم نے عرض کیا: اے اللہ کے رسول! اگر آپ اللہ تعالی سے دعا فرمائیں تو وہ آپ کی یہ تکلیف ختم کر دے گا۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: یقینا ہم انبیاء کی جماعت کو اس لیے سخت تکلیف میں مبتلا کیا جاتا ہے تاکہ ہمارے خطاؤں کا کفارہ ہو جائے۔","رجالہ ثقات",{"k":"مسند أبی یعلی الموصلی (۴۷۶۹)۔"}],[6,"سیدنا عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ:\nمیں رسول اللہ  صلی اللہ علیہ وسلم  کی خدمت میں حاضر ہوا تو آپ کو بہت تیز بخار تھا۔ میں نے آپ کو اپنا ہاتھ لگایا تو عرض کیا: اے اللہ کے رسول! آپ کو تو بہت ہی سخت بخار ہے۔ تو رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا: مجھے تم میں سے دو آدمیوں کے برابر بخار ہوتا ہے۔ میں نے عرض کیا: یہ اس لیے ہے تاکہ کیونکہ آپ کو اجر بھی دوہرا ملتا ہے؟ تو رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا: جی ہاں۔ پھر رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا: جب کوئی مسلمان کسی بھی مرض یا کسی اور تکلیف میں مبتلا ہوتا ہے تو اللہ تعالی اس کی وجہ سے اس کے گناہوں کو اس طرح جھاڑ دیتا ہے جس طرح درخت اپنے پتے جھاڑتا ہے۔","",{"k":"صحیح بخاری (۵۶۴۷)، صحیح مسلم (۲۵۷۱)۔"}],[7,"سیدنا عمر رضی اللہ عنہ بیان کرتے ہیں کہ:\nمیں نے اپنا ہاتھ نبی  صلی اللہ علیہ وسلم  پر رکھا اور عرض کیا: میرے ماں باپ آپ پر قربان ہوں! آپ کو کس قدر اجر ملے گا؟ آپ کو اس دِن بخار تھا۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: جس طرح ہمیں دوہرے اجر و ثواب سے نوازا جاتا ہے اسی طرح ہم پر آزمائشیں بھی دوگنا آتی ہیں۔","حسن",{"k":"تفرّد بہ المؤلف۔"}],[8,"سیدنا سعد رضی اللہ عنہ بیان کرتے ہیں کہ:\nمیں نے عرض کیا: اے اللہ کے رسول! لوگوں میں سخت ترین آزمائش کے شکار کون لوگ ہوتے ہیں؟ آپ  صلی اللہ علیہ وسلم  نے فرمایا: انبیاء، پھر جو ان کے بعد سب سے افضل ہیں، پھر جو ان کے بعد درجہ و مقام رکھتے ہیں۔ آدمی کو اس کے دِین کے حساب سے آزمایا جاتا ہے، اگر تو وہ اپنے دِین میں مضبوط ہو تو اس کی آزمائش بھی سخت کی جاتی ہے اور اگر وہ اپنے دِین میں نرم (یعنی سست) ہو تو اسے اسی حساب سے آزمایا جاتا ہے۔ بندے پر آزمائش و مصیبت آتی رہتی ہے، یہاں تک کہ اسے ایسا کر کے چھوڑتی ہے کہ وہ زمین پر چل پھر رہا ہوتا ہے اور اس پر کوئی گناہ (باقی) نہیں رہتا۔","حسن صحیح",{"k":"مسند أحمد (۱؍۱۷۲)، سنن الترمذی (۲۳۹۸)، سنن ابن ماجہ (۴۰۲۳)، سنن الدارمی (۲۷۸۳)، مسند الشاشی (۶۹)، مسند عبد بن حمید (۱۴۶)، صحیح ابن حبان (۲۹۰۱)، المستدرک للحاکم (۱؍۱۰۰)۔","f":"جو شخص جس قدر زیادہ دِیندار ہوتا ہے اللہ تعالی اس کی ثابت قدمی دیکھنے اور اسے بلند درجات پر فائز کرنے کے لیے اسے اسی قدر آزمائش سے گزارتا ہے۔نیک صاحبِ ایمان پر مشکلات کا آنا اس کے کمالِ ایمان اور اللہ تعالی کا محبوب و مقرب بندہ ہونے کی علامت ہوتی ہے۔ اسے ان مصائب سے گھبرانا بالکل نہیں چاہیے، بلکہ صبر کا مظاہرہ کرنا چاہیے تاکہ اللہ تعالی جہاں اس مصیبت اور آزمائش کے باعث اس کے گناہوں کا خاتمہ فرمائے وہاں اس کے صبر کے بہ دولت اس کے درجات کو بھی بلند فرما دے۔"}],[9,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\nنبی  صلی اللہ علیہ وسلم  سے سوال کیا گیا: لوگوں میں سب سے سخت آزمائش کن کی ہوتی ہے؟ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: انبیاء کی، پھر نیک لوگوں کی۔","إسنادہ لیس بالقوی",{"k":"کنز العمال فی سنن الأقوال والأفعال (۳؍۴۳۳)۔"}],[10,"ابوعبیدہ بن حذیفہ اپنی پھوپھی سے بیان کرتے ہیں کہ انہوں نے کہا:\nمیں کچھ عورتوں کے ہمراہ نبی  صلی اللہ علیہ وسلم  کی عیادت کے لیے حاضر ہوئی، تو وہاں ایک مشکیزہ لٹکا ہوا تھا جس سے پانی آپ پر ٹپک رہا تھا۔ ایسا آپ کے بخار کی شدت کے باعث کیا گیا تھا۔ ہم نے عرض کیا: آپ اللہ تعالی سے دعا کیجئے کہ وہ آپ کا بخار ختم فرما دے۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: یقینا لوگوں میں سب سے سخت آزمائش انبیاء کی ہوا کرتی ہے، پھر ان لوگوں کی جو ان کے قریب ہوتے ہیں، پھر ان کی جو ان سے قریب (درجے والے) ہوتے ہیں۔","حسن",{"k":"مسند أحمد (۶؍۳۶۹)، السنن الکبرٰی للنسائی (۷۴۸۲)، المعجم الکبیر للطبرانی (۲۴؍۲۴۴)، المستدرک للحاکم (۴؍۴۴۸)، مجمع الزوائد للھیثمی (۲؍۲۹۲)۔"}],[11,"ابوعبیدہ بن حذیفہ اپنی پھوپھی سے بیان کرتے ہیں کہ:\nنبی  صلی اللہ علیہ وسلم  کو بہت سخت بخار ہو گیا تو آپ  صلی اللہ علیہ وسلم  نے ایک مشکیزہ لانے کا حکم فرمایا، جسے ایک درخت پر لٹکا دِیا گیا، پھر آپ  صلی اللہ علیہ وسلم  اس کے نیچے لیٹ گئے اور آپ کے دِل پر پانی ٹپکنے لگا۔ پھر ہم آپ  صلی اللہ علیہ وسلم  کی خدمت میں حاضر ہوئیں تو ہم نے عرض کیا: آپ اللہ کے رسول ہیں اور آپ کو تو بہت سخت بخار ہوا پڑا ہے اور تکلیف بھی دے رہا ہے، لہٰذا آپ اللہ تعالی سے دعا فرمائیے کہ وہ بخار ختم کر دے۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: یقینا لوگوں میں سب سے سخت آزمائش انبیاء کی ہوا کرتی ہے، پھر ان لوگوں کی جو ان کے قریب ہوتے ہیں، پھر ان کی جو ان سے قریب (درجے والے) ہوتے ہیں۔","حسن",{"k":"مسند أحمد (۶؍۳۶۹)، السنن الکبرٰی للنسائی (۷۴۸۲)، المعجم الکبیر للطبرانی (۲۴؍۲۴۴)، المستدرک للحاکم (۴؍۴۴۸)، مجمع الزوائد للھیثمی (۲؍۲۹۲)۔"}],[12,"ایک صحابئ رسول رضی اللہ عنہ بیان کرتے ہیں کہ:\nہم نبی  صلی اللہ علیہ وسلم  کی خدمت میں حاضر ہوئے۔ آپ  صلی اللہ علیہ وسلم  کو بخار تھا۔ ہم نے عرض کیا: اَخ، اَخ (عرب یہ الفاظ تکلیف اور پریشانی کے موقع پر بولتے تھے)۔ اے اللہ کے رسول! ہمارے ماں باپ آپ پر قربان ہوں! آپ کو تو بہت سخت بخار ہے۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: یقینا ہم انبیاء کی جماعت پر آزمائشیں بھی بڑھ چڑھ کر آتی ہیں۔ ہم نے (تعجب سے) کہا: سبحان اللہ۔ آپ  صلی اللہ علیہ وسلم  نے فرمایا: کیا تمہیں تعجب ہوا ہے؟ یقینا لوگوں میں سب سے سخت آزمائش انبیاء پر اور (پھر) حسبِ درجہ نیک لوگوں پر آتی ہے۔ ہم نے (پھر تعجب سے) کہا: سبحان اللہ۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: کیا تمہیں (اس پر بھی) تعجب ہوا ہے؟ سنو! ایک نبی تو ضرورت پڑنے پر ایک ہی چادر اوڑھے رکھتے تھے اور اس کے علاوہ انہیں کچھ میسر نہیں تھا۔ ہم نے کہا: سبحان اللہ۔ آپ  صلی اللہ علیہ وسلم  نے فرمایا: کیا تمہیں اس پر بھی تعجب ہے؟ ایک نبی تو ایسے تھے کہ انہیں جوؤں نے ہی مار ڈالا تھا۔ ہم نے (انتہائی تعجب سے) کہا: سبحان اللہ۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: کیا تمہیں (اس پر بھی) تعجب ہوا ہے؟ وہ لوگ تو آزمائش پر اس طرح خوش ہوا کرتے تھے جس طرح تم آسودگی میں خوش رہتے ہو۔","حسن",{"k":"مسند أبی یعلی الموصلی (۱۰۴۵)، المعجم الکبیر للطبرانی (۳؍۳۷۲)، مسند عبد بن حمید (۹۶۰)۔","f":"گویا بندے کا ایمان کے اعتبار سے جس قدر درجہ بلند ہو گا اسی قدر اس کو آزمائش سے گزرنا پڑتا ہے۔ لہٰذا جس طرح آزمائش کا شکار ہونا کمالِ ایمان کی علامت ہے اسی طرح فراخی اور عیش و مستی میں رہنا اللہ کے مقربین میں شامل نہ ہونے کی نشانی ہے۔ لہٰذا مصائب و آلام سے محفوظ رہنے والے کو اللہ تعالی سے اپنے گناہوں کی معافی مانگنا چاہیے کہ کہیں اس کا پروردگار اس سے ناراض تو نہیں؟! جیسا کہ نبی مکرم  صلی اللہ علیہ وسلم  نے ایک بار ایک دیہاتی سے پوچھا تھا کہ کیا تمہیں کبھی اُمِ ملدم (جلد اور گوشت کے درمیان حرارت کی بیماری) اور صداع (سر کی تکلیف) ہوئی ہے؟ اس نے کہا: میں نے تو ایسا کبھی محسوس نہیں کیا۔ جب وہ واپس چلا گیا تو رسول اللہ صلی اللہ علیہ وسلم  نے صحابہ کو مخاطب کرتے ہوئے فرمایا: جس شخص کی کسی جہنمی کو دیکھنے کی چاہت ہو تو وہ اسے دیکھ لے۔ (مسند أحمد: ۸۳۹۵۔ الأدب المفرد: ۴۹۵۔ السنن الکبرٰی للنسائی: ۷۴۹۱۔ مسند البزار: ۷۷۸۔ صحیح ابن حبان: ۲۹۱۶) گویا نبی مکرم  صلی اللہ علیہ وسلم  نے اس کا بیماری سے محفوظ رہنا ناراضئ الٰہی کی علامت سمجھا، اسی لیے یہ ارشاد فرمایا۔ اس کا یہ مطلب ہر گز نہیں ہے کہ اللہ تعالی سے مصائب اور امراض کی دعا کرنی چاہیے، نہیں، بلکہ مقصود یہ ہے کہ عیش و مستی اور فراخی اور لااُبالی کی زندگی میں غرق رہنے کو عافیت سمجھنے کی بہ جائے اللہ تعالی سے اپنے گناہوں کی معافی مانگنی چاہیے۔"}],[13,"سیدنا ابوسعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ:\n(میں نے عرض کیا:) اے اللہ کے رسول! آپ کا خیال ہے کہ یہ جو ہمیں بیماریاں لگتی ہیں، کیا ان کی وجہ سے ہمیں کوئی صلہ بھی ملے گا؟ آپ  صلی اللہ علیہ وسلم  نے فرمایا: یہ گناہوں کا کفارہ بنتی ہیں۔ سیدنا اُبی بن کعب رضی اللہ عنہ نے عرض کیا: اے اللہ کے رسول! اگرچہ تھوڑی سی ہی تکلیف ہو؟ آپ  صلی اللہ علیہ وسلم  نے فرمایا: کانٹا چبھ جائے یا اس سے بھی کم کوئی تکلیف پہنچے (تو وہ بھی گناہوں کا کفارہ بن جاتی ہے)۔ راوی بیان کرتے ہیں کہ سیدنا اُبی رضی اللہ عنہ نے اپنے خلاف یہ دعا کی کہ مرتے دَم تک ان کا بخار نہ اُترے، البتہ وہ ان کے لیے حج و عمرہ کی ادائیگی، جہاد فی سبیل اللہ میں شرکت اور نماز باجماعت ادا کرنے میں رُکاوٹ نہ بنے۔ راوی کا بیان ہے کہ اس کے بعد جس بھی آدمی نے ان کے جسم کو ہاتھ لگایا؛ اس نے ان کے جسم میں حرارت محسوس کی، یہاں تک کہ وہ وفات پا گئے۔","صحیح",{"k":"مسند أحمد (۳؍۲۳)، السنن الکبرٰی للنسائی (۷۴۸۹)، مسند أبی یعلی الموصلی (۹۹۵)، صحیح ابن حبان (۲۹۲۸)، المستدرک للحاکم (۴؍۳۴۳)، مجمع الزوائد للھیثمی (۲؍۳۰۲)۔"}],[14,"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ:\nرسول اللہ  صلی اللہ علیہ وسلم  اُمِ سائب، یا اُمِ مسیب رضی اللہ عنہا کے پاس تشریف لائے تو وہ کپکپا رہی تھیں۔ آپ  صلی اللہ علیہ وسلم  نے استفسار فرمایا: تمہیں کیا ہوا ہے؟ کپکپا کیوں رہی ہو؟ انہوں نے کہا: بخار ہوا ہے، اللہ اس کو بے برکت کر دے۔ آپ  صلی اللہ علیہ وسلم  نے فرمایا: بخار کو برا بھلا مت کہو، کیونکہ یہ بنی آدم کے گناہوں کو اس طرح ختم کر دیتا ہے جس طرح آگ کی بھٹی لوہے کے میل کچیل کو ختم کر دیتی ہے۔","",{"k":"صحیح مسلم (۲۵۷۵)۔"}],[15,"سیدنا عقبہ بن عامر الجہنی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nدِن کا جو بھی عمل ہو اس پر مہر ثبت کر دی جاتی ہے، سو جب بندۂ مومن بیمار ہوتا ہے تو فرشتے کہتے ہیں: اے ہمارے پروردگار! تو نے اپنے فلاں بندے (کو بیمار کر کے اس کے عمل) کو روک دِیا ہے۔ تو رب تعالی فرماتا ہے: جب تک وہ صحت یاب یا فوت نہیں ہو جاتا تب تک اس کے معمول کے اعمال پر ہی مہر لگاتے رہو۔","صحیح",{"k":"مسند أحمد (۴؍۱۴۶)، المعجم الکبیر للطبرانی (۱۷؍۲۸۴)، المعجم الأوسط للطبرانی (۳۲۳۳)، المستدرک للحاکم (۴؍۳۴۴)، مجمع الزوائد للھیثمی (۲؍۳۰۳)۔"}],[16,"سیدنا ابوہریرہ رضی اللہ عنہ فرماتے ہیں:\nجب بندۂ مسلم بیمار ہوتا ہے تو دائیں فرشتے سے کہا جاتا ہے: میرے بندے کے وہ اعمال لکھتے رہو جو یہ (تندرستی میں) کیا کرتا تھا۔ اور بائیں فرشتے سے کہا جاتا ہے: میرے بندے کو تب تک معاف کیے رکھو جب تک وہ میری بندش میں قید ہے۔ سیدنا ابوہریرہ رضی اللہ عنہ کے پاس بیٹھے ایک آدمی نے کہا: کاش! میں بیمار ہو کر ہمیشہ صاحبِ فراش رہتا۔ تو سیدنا ابوہریرہ رضی اللہ عنہ نے فرمایا: اس بندے نے گناہوں کو ناپسند کیا ہے۔","رجالہ ثقات",{"k":"شعب الإیمان للبیھقی (۱۲؍۳۳۴)۔","f":"یعنی سیدنا ابوہریرہ رضی اللہ عنہ نے اس آدمی کے بیماری کی خواہش کرنے کو برا نہیں سمجھا بلکہ تعریف کے انداز میں فرمایا کہ اس نے بیماری کی خواہش اس وجہ سے کی ہے کہ یہ گناہوں سے نفرت کرتا ہے۔"}],[17,"عطاء بن یسار رحمہ اللہ سے مروی ہے کہ نبی  صلی اللہ علیہ وسلم  نے فرمایا:\nجب اللہ تعالی کسی بیماری کی وجہ سے بندے کو آزماتا ہے تو اللہ تعالی اس کی جانب دو فرشتے بھیجتا ہے اور فرماتا ہے: جا کر سنو کہ میرا بندہ اپنی عیادت کے لیے آنے والوں سے کیا کہتا ہے؟ اگر وہ اللہ کا شکر ادا کرے اور اچھے لفظوں میں اس کی ستائش بیان کرے تو اس کی طرف سے یہ عمل (مجھ تک) پہنچا دو۔ پھر اللہ تعالی فرماتا ہے: یقینا میرے بندے کے لیے یہ اجر میرے ذِمے ہے کہ اگر میں نے اسے فوت کر دیا تو اسے جنت میں داخل کروں گا اور اگر میں نے اسے (بستر مرض سے) اُٹھا لیا تو اسے بدلے میں ایسا گوشت عطا کروں گا جو اس کے گوشت سے بہتر ہو گا اور ایسا خون دوں گا جو اس کے خون سے بہتر ہو گا، اور اس کو مغفرت سے نواز دوں گا۔","حسن",{"k":"الموطأ (۲؍۹۴۰)، الزھد لھناد (۱؍۲۵۱)۔"}],[18,"ہلال بن یساف رحمہ اللہ بیان کرتے ہیں کہ:\nہم سیدنا عمار بن یاسر رضی اللہ عنہ کے پاس بیٹھے ہوئے تھے تو لوگوں نے تکالیف کا تذکرہ کر دیا، تو ایک دیہاتی نے کہا: میں تو کبھی بیمار نہیں ہوا۔ تو عمار رضی اللہ عنہ نے فرمایا: تو ہم میں سے نہیں ہے، یقینا جس مسلمان کو کسی آزمائش میں مبتلا کیا جاتا ہے تو اس کے گناہ اس سے اس طرح گرائے جاتے ہیں جس طرح درخت سے پتے گرتے ہیں اور کافر (یا فرمایا کہ) فاسق کو جب کسی آزمائش سے دوچار کیا جاتا ہے تو اس کی مثال اونٹ کی مانند ہوتی ہے کہ جسے کھلا چھوڑا جائے تو اسے معلوم نہیں ہوتا کہ اسے کیوں کھولا گیا ہے اور اگر اسے باندھ دِیا جائے تو اسے تب بھی معلوم نہیں ہوتا کہ اسے کیوں باندھا گیا ہے۔","رجالہ ثقات",{"k":"المصنف لابن أبی شیبۃ (۳؍۲۳۲)، الدر المنثور للسیوطی (۲؍۷۰۳)۔"}],[19,"ابومعمر اَزدی بیان کرتے ہیں کہ:\nجب ہم سیدنا ابن مسعود رضی اللہ عنہ سے کوئی ایسی بات سنتے جو ہمیں ناگوار گزرتی تو ہم خاموش رہتے، یہاں تک کہ وہ خود ہی ہمیں اس کی وضاحت فرما دیتے۔ ایک روز انہوں نے ہم سے فرمایا: سنو! یقینا بیماری کا اجر نہیں لکھا جاتا۔ اس بات نے ہمیں پریشان کر دیا اور ہم پر بہت گراں گزری۔ تو (پھر وضاحت کرتے ہوئے) انہوں نے فرمایا: لیکن اس کی وجہ سے گناہوں کا کفارہ ہو جاتا ہے۔ تو ہمیں اس بات نے خوش کر دیا اور ہمیں بہت اچھا لگا۔","حسن",{"k":"المعجم الکبیر للطبرانی (۹؍۹۴)، مجمع الزوائد للھیثمی (۲؍۳۰۱)۔"}],[20,"یزید بن میسرہ فرماتے ہیں کہ:\nیقینا بندہ جب اس حالت میں کسی مرض میں مبتلا ہوتا ہے کہ اللہ کے ہاں اس کی کوئی نیکی نہیں ہوتی اور اللہ تعالی کو اس کے گزشتہ گناہ بالکل پسند نہیں ہوتے۔ پھر اس کی آنکھ سے مکھی کے پر کے برابر (آنسو) نکل آتا ہے تو اللہ تعالی نے اگر اسے (بستر مرض سے) اُٹھانا ہو تو اُٹھا دیتا ہے یا اس کی جان قبض کرنی ہو تو اسے اسی حالت میں قبض کر لیتا ہے۔","حسن",{"k":"حلیۃ الأولیاء لأبی نعیم (۵؍۲۴۰)۔","f":"یعنی اللہ تعالی اس کے ایک آنسو کی اس قدر لاج رکھتا ہے اور قدر کرتا ہے کہ اسے یا تو شفایاب کر دیتا ہے، یا پھر اپنے پاس بلا لیتا ہے، یعنی اسے مزید آزمائش میں مبتلا نہیں کرتا۔"}],[21,"سیدنا ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\nرسول اللہ  صلی اللہ علیہ وسلم  ہمیں تمام تکالیف سے (افاقے) کے لئے یہ (دَم) سکھایا کرتے تھے:\nبِسْمِ اللّٰہِ الْکَبِیرِ أَعُوذُ بِاللّٰہِ الْعَظِیمِ مِنْ کُلِّ عِرْقٍ نَعَّارٍ وَمِنْ حَرِّ النَّارِ.\n‘‘اللہ کے نام سے جو بہت بڑا ہے، میں اس خون بہانے والی رگ سے اور جہنم کی آگ سے عظمت والے اللہ کی پناہ میں آتا ہوں۔’’","ضعیف",{"k":"مسند أحمد (۱؍۳۰۰)، سنن الترمذی (۲۰۷۵)، سنن ابن ماجہ (۳۵۲۶)، المعجم الکبیر للطبرانی (۱۱؍۲۲۴)، المستدرک للحاکم (۴؍۴۵۹)، مسند عبد بن حمید (۵۹۴)۔"}],[22,"ابوصالح اشعری رحمہ اللہ بیان کرتے ہیں کہ:\nسیدنا ابوہریرہ رضی اللہ عنہ نے ایک مریض کی عیادت کی تو اس سے کہا: یقینا رسول اللہ  صلی اللہ علیہ وسلم  کا فرمان ہے کہ اللہ تعالی فرماتا ہے: یہ (بخار) میری آگ ہے، جس کو میں دنیا میں ہی اپنے بندے پر مسلط کر دیتا ہوں، تاکہ اس کو آخرت کی آگ کا حصہ دنیا میں ہی مل جائے (اور وہ آخرت میں جہنم کی آگ سے محفوظ رہ سکے) ۔","صحیح",{"k":"سنن الترمذی (۲۰۸۸)، سنن ابن ماجہ (۳۴۷۰)، المستدرک للحاکم (۱؍۴۹۶)۔"}],[23,"ابوریحانہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nبخار جہنم کی تپش کی دھونکنی ہے اور یہ (جہنم کی) آگ سے مومن کا حصہ ہے۔","حسن",{"k":"شعب الإیمان للبیھقی (۷؍۱۶۱)، شرح مشکل الآثار للطحاوی (۵؍۴۶۹)، التاریخ الکبیر للبخاری (۷؍۶۳)، تاریخ دمشق لابن عساکر (۲۳؍۱۹۸)، مجمع الزوائد للھیثمی (۲؍۳۰۶)۔","f":"یعنی جسے دنیا میں بخار ہو گا اسے آخرت میں اس کے گناہوں پر ملنے والی سزا اتنی کم کر دی جائے گی۔"}],[24,"امام مجاہد رحمہ اللہ فرماتے ہیں:\nبخار ہر مومن کا (جہنم کی) آگ سے حصہ ہوتا ہے۔ پھر انہوں نے یہ آیت پڑھی: ﴿وَإِنْ مِنْکُمْ إِلَّا وَارِدُہَا کَانَ عَلٰی رَبِّکَ حَتْمًا مَقْضِیًّا﴾ ‘‘تم میں سے ہر کوئی وہاں ضرور وارد ہونے والا ہے، یہ تیرے پروردگار کے ذِمے قطعی اور فیصلہ شدہ اَمر ہے۔’’ (اور فرمایا:) دنیا میں بخار کا ہونا آخرت میں سزا پا لینے کے ہی مترادف ہے۔","ضعیف",{"k":"تفسیر ابن جریر الطبری (۱۶؍۱۱۱)۔"}],[25,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nمومن جب اپنی بیماری سے صحت مند و تندرست ہو جاتا ہے تو وہ (سفید ترین) رنگ اور صاف و شفاف ہونے میں آسمان سے گرنے والی برف کے مانند ہو جاتا ہے۔","ضعیف",{"k":"المعجم الأوسط للطبرانی (۵۱۶۶)، شعب الإیمان للبیھقی (۷؍۱۶۰)، تاریخ دمشق لابن عساکر (۱۱؍۳۸۷)، مجمع الزوائد للھیثمی (۲؍۳۰۳)۔","f":"یعنی جس طرح آسمان سے گرنے والی برف پر کسی قسم کا داغ و دھبہ نہیں ہوتا اور وہ بالکل سفید اور ہر قسم کی گندگی سے پاک اور صاف ہوتی ہے اسی طرح مومن بھی مرض کے بعد گناہوں سے پاک اور صاف ہو جاتا ہے اور اس پر برائی کا کوئی دھبہ اور گندگی باقی نہیں رہتی۔"}],[26,"سیدنا ابوامامہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی  صلی اللہ علیہ وسلم  نے فرمایا:\nجو شخص مرض کی وجہ سے (بستر مرض پر) گرا دِیا جاتا ہے، اسے اسی کے باعث (گناہوں سے) پاک حالت میں اُٹھایا جاتا ہے۔","رجالہ ثقات",{"k":"المعجم الکبیر للطبرانی (۸؍۹۷)، شعب الإیمان للبیھقی (۷؍۱۸۰)، الترغیب والترھیب للمنذری (۴؍۱۵۲)، مجمع الزوائد للھیثمی (۲؍۳۰۲)، تاریخ دمشق لابن عساکر (۲۰؍۷۶)۔"}],[27,"سیدنا ابوامامہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجب بندہ بیمار ہوتا ہے تو اللہ تعالی اپنے فرشتوں کووحی فرماتا ہے: اے میرے فرشتو! میں نے اپنے بندے کو اپنی ایک قید میں بند کر دِیا ہے، اگر میں اس کی جان قبض کروں گا تو اسے بخش دوں گا اور اگر میں اسے تندرست کروں گا تو تب بھی یہ مغفرت سے نوازا ہوا جسم ہو گا اور اس کا کوئی گناہ باقی نہیں رہے گا۔","ضعیف",{"k":"المعجم الکبیر للطبرانی (۸؍۱۶۷)، المستدرک للحاکم (۴؍۳۴۸)، مجمع الزوائد للھیثمی (۲؍۲۹۱)۔"}],[28,"سیدنا عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجب بندہ احسن انداز سے عبادت بجا لا رہا ہو، پھر وہ بیمار ہو جائے تو اس پر مقرر فرشتے سے کہا جاتا ہے: اس کے وہی اعمال لکھتے رہو جو یہ تندرستی کی حالت میں کرتا تھا، یہاں تک کہ میں اسے صحت یاب کر دوں یا اسے اپنے پاس بلا لوں۔","صحیح",{"k":"مسند أحمد (۲؍۲۰۳)۔"}],[29,"خیثمہ رحمہ اللہ سے مروی ہے کہ سیدنا عبداللہ بن عمرو رضی اللہ عنہ نے فرمایا:\nجب مسلمان کسی مرض میں مبتلا ہوتا ہے تو اللہ تعالیٰ ان دو فرشتوں سے فرماتا ہے جو اس کا عمل لکھتے ہیں کہ اس کے نامہ اعمال میں اسی کے مثل عمل لکھتے رہو جو یہ تندرستی کی حالت میں کرتا تھا، یہاں تک کہ میں اسے شفایاب کر دوں یا اپنے پاس بُلا لوں۔","حسن",{"k":"مسند أحمد (۲؍۲۰۳)، الترغیب والترھیب للمنذری (۴؍۱۴۷)، مجمع الزوائد للھیثمی (۲؍۳۰۳)۔"}],[30,"سیدنا ابوامامہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nیقینا اللہ تعالیٰ تمہیں آزمائش کے ذریعے جانچتا ہے، حالانکہ وہ اس کے متعلق بہ خوبی جانتا ہے، (وہ اسی طرح جانچ کرتا ہے) جس طرح تم اپنے سونے کو آگ پر جانچتے ہو۔ ان میں سے کچھ لوگ تو خالص سونے کی مانند نکل آتے ہیں، یہ وہ لوگ ہوتے ہیں جنہیں اللہ تعالیٰ نے گناہوں سے بچا لیا۔ کچھ لوگ اس سے کم تر سونے کی مانند نکلتے ہیں، یہ وہ لوگ ہوتے ہیں جو کسی شک میں مبتلا ہوتے ہیں اور کچھ لوگ تو کالے سونے کی مانند نکلتے ہیں، یہ وہ لوگ ہیں جو فتنے کا شکار ہوگئے۔","ضعیف",{"k":"المعجم الکبیر للطبرانی (۸؍۱۶۶)، شعب الإیمان للبیھقی (۷؍۱۸۱)، المستدرک للحاکم (۴؍۳۵۰)، الترغیب والترھیب للمنذری (۴؍۱۴۳)، مجمع الزوائد للھیثمی (۲؍۲۹۱)۔"}],[31,"امام حسن رحمہ اللہ مرفوعاً بیان کرتے ہیں (یعنی نبی  صلی اللہ علیہ وسلم  نے فرمایا:)\nیقینا اللہ تعالیٰ ایک رات کے بخار کے بدلے میں بندۂ مومن کے تمام گناہوں کا کفارہ کر دیتا ہے۔","ضعیف",{"k":"الترغیب والترھیب للمنذری (۴؍۲۹۹)۔"}],[32,"امام حسن رحمہ اللہ بیان کرتے ہیں کہ:\nصحابہ کرام رضی اللہ عنہم ایک رات کے بخار سے گزشتہ گناہوں کے کفارے کی اُمید رکھا کرتے تھے۔","حسن",{"k":"شعب الإیمان للبیھقی (۱۲؍۲۸۲)۔"}],[33,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ:\nرسول اللہ  صلی اللہ علیہ وسلم  ایک آدمی کے پاس تشریف لائے جو کہ بیمار تھا، تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: یہ دعا پڑھو:\nاَللّٰہُمَّ إِنِّی أَسْأَلُکَ تَعْجِیلَ عَافِیَتِکَ، أَوْ صَبْرَکَ عَلَی بَلَائِکَ، أَوْ خُرُوجًا مِنَ الدُّنْیَا إِلَی رَحْمَتِکَ\n‘‘اے اللہ! میں تجھ سے جلد شفایاب ہونے، یا تیری آزمائش پر صبر کرنے، یا دنیا سے تیری رحمت کی جانب روانہ ہونے کا سوال کرتا ہوں۔’’","ضعیف",{"k":"إحیاء علوم الدین للغزالی (۱؍۵۱۸)، الشھاب للقضاعی (۱۴۷۰)۔"}],[34,"سیدنا عبدالرحمان بن ازھر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nمومن کی مثال، جبکہ اس کو بخار یا تکلیف ہو جاتی ہے، اس لوہے کی سی ہے جو آگ میں داخل ہوتا ہے تو اس کا زنگ ختم ہو جاتا ہے اور اچھا اچھا حصہ باقی رہ جاتا ہے۔","صحیح",{"k":"المعجم الکبیر للطبرانی (۳؍۳۷۴)، المستدرک للحاکم (۱؍۱۴۵)، مجمع الزوائد للھیثمی (۲؍۳۰۲)۔"}],[35,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجب مومن بیمار ہوتا ہے تو یہ (بیماری) اس کو اس طرح خالص (یعنی گناہوں سے پاک) بنا دیتی ہے جس طرح آگ کی بھٹی لوہے کے میل کچیل کو نکال پھینکتی ہے۔","حسن",{"k":"المعجم الأوسط للطبرانی (۵۳۵۱)، مجمع الزوائد للھیثمی (۲؍۳۰۲)۔"}],[36,"سیدہ اُمِ سُلیم انصاریہ رضی اللہ عنہا بیان کرتی ہیں کہ:\nمیں بیمار ہو گئی تو رسول اللہ  صلی اللہ علیہ وسلم  نے میری عیادت کی اور فرمایا: اے اُمِ سُلیم! کیا تجھے آگ، لوہے اور لوہے کے زَنگ کا پتا ہے؟ انہوں نے عرض کیا: جی ہاں، اے اللہ کے رسول۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: تو پھر اے اُمِ سُلیم خوش ہو جا! کیونکہ یقینا اگر تو نے اس تکلیف سے نجات پا لی تو تُو اس طرح (گناہوں سے) پاک صاف ہو جائے گی جس طرح کہ لوہا آگ کے ذریعے اپنے زَنگ سے صاف و شفاف ہو جاتا ہے۔","",{"k":"تاریخ بغداد للخطیب (۳؍۴۱۱)۔"}],[37,"سیدہ فاطمہ الخزاعیہ رضی اللہ عنہا بیان کرتی ہیں کہ:\nرسول اللہ  صلی اللہ علیہ وسلم  نے ایک انصاری عورت کی عیادت کی تو استفسار فرمایا: آپ کی طبیعت کیسی ہے؟ اس نے کہا: اے اللہ کے رسول! خیریت سے ہوں، بس مجھے بخار ہو گیا ہے۔ تو رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا: صبر کرو، کیونکہ یہ انسان کے (گناہوں کی) گندگی کو اس طرح ختم کر دیتا ہے جس طرح آگ کی بھٹی لوہے کے میل کچیل کو ختم کر دیتی ہے۔","رجالہ ثقات",{"k":"المصنف لعبد الرزاق (۲۰۳۰۶)، المعجم الکبیر للطبرانی (۲۴؍۴۰۵)، مجمع الزوائد للھیثمی (۲؍۳۰۷)۔"}],[38,"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجب مومن بیمار ہوتا ہے تو یہ (بیماری) اسے اس طرح خالص (یعنی گناہوں سے پاک و صاف) کر دیتی ہے جس طرح آگ کی بھٹی لوہے کے میل کچیل کو چھانٹ دیتی ہے۔","حسن",{"k":"مسند الشھاب للقضاعی (۱۴۰۶)۔"}],[39,"علقمہ رحمہ اللہ بیان کرتے ہیں کہ:\nسیدنا ابن مسعود رضی اللہ عنہ رسول اللہ  صلی اللہ علیہ وسلم  کی خدمت میں حاضر ہوئے تو آپ  صلی اللہ علیہ وسلم  کو بخار ہوا پڑا تھا۔ انہوں نے اپنا ہاتھ آپ پر رکھا اور عرض کیا: اے اللہ کے رسول! آپ کو تو بہت ہی سخت بخار ہے۔ تو رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا: مجھے تم میں سے دو آدمیوں کے برابر بخار ہوتا ہے۔ میں نے عرض کیا: یہ اس لیے ہے کیونکہ آپ کو اجر بھی دوہرا ملتا ہے؟ تو رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا: جس بھی کسی مسلمان کو کوئی مصیبت پہنچتی ہے یا اس سے بھی چھوٹی تکلیف آتی ہے، تو اللہ تعالیٰ اس کے گناہوں کو اس طرح جھاڑ دیتا ہے جس طرح درخت اپنے پتے جھاڑتا ہے۔","",{"k":"صحیح بخاری (۵۶۴۷)، صحیح مسلم (۲۵۷۱)۔"}],[40,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ میں نے رسول اللہ  صلی اللہ علیہ وسلم  کو فرماتے سنا:\nیقینا بخار گناہوں کو اس طرح جھاڑتا ہے جس طرح درخت اپنے پتے جھاڑتا ہے۔","حسن",{"k":"تاریخ بغداد للخطیب (۱۴؍۶۶)۔"}],[41,"سیدنا اسد بن کرز سے مروی ہے کہ انہوں نے نبی  صلی اللہ علیہ وسلم  کو فرماتے سنا:\nمریض کے گناہ اس طرح جھڑتے ہیں جس طرح درخت کے پتے جھڑتے ہیں۔","ضعیف",{"k":"مسند أحمد (۴؍۷۰)، المعجم الکبیر للطبرانی (۱؍۳۳۵)، الترغیب والترھیب للمنذری (۴؍۱۴۸)، مجمع الزوائد للھیثمی (۲؍۳۰۱)۔"}],[42,"سیدنا ابوایوب انصاری رضی اللہ عنہ بیان کرتے ہیں کہ:\nرسول اللہ  صلی اللہ علیہ وسلم  نے ایک انصاری شخص کی عیادت کی تو اس پر جھک گئے اور اس کا حال چال پوچھا، تو اس نے کہا: اے اللہ کے نبی! سات راتوں سے نہ تو میری آنکھ لگی ہے اور نہ ہی کوئی مجھ سے ملنے آیا ہے۔ تو رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا: میرے بھائی! صبر کرو، میرے بھائی! صبر کرو، تم گناہوں سے اسی طرح نکل آئے ہو جس طرح ان میں داخل ہوئے تھے۔ راوی بیان کرتے ہیں کہ پھر رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا: بیماری کی گھڑیاں گناہوں کی گھڑیوں کو ختم کر دیتی ہیں۔","حسن",{"k":"شعب الإیمان للبیھقی (۷؍۱۸۱)۔"}],[43,"سیدنا معاویہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ  صلی اللہ علیہ وسلم  کو فرماتے سنا:\nمومن کو جو بھی کوئی جسمانی بیماری آتی ہے اور اسے تکلیف پہنچاتی ہے تو اس کے بدلے میں اس کے گناہوں کا کفارہ کر دِیا جاتا ہے۔","حسن",{"k":"مسند أحمد (۴؍۹۸)، المعجم الکبیر للطبرانی (۱۹؍۳۵۹)، شعب الإیمان للبیھقی (۷؍۱۶۸)، المستدرک للحاکم (۱؍۴۹۸)، الترغیب والترھیب للمنذری (۴؍۱۴۴)۔"}],[44,"سیدنا ابوہریرہ اور سیدنا ابوسعید رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nمومن کو جو بھی پریشانی، تکلیف، بیماری اور غم پہنچتا ہے، یہاں تک کہ اگر اسے کوئی رنج پریشانی میں مبتلا کر دیتا ہے تو اللہ تعالیٰ اسے بھی اس کے گناہوں کا کفارہ بنا دیتا ہے۔","",{"k":"صحیح بخاری (۵۶۴۲)، صحیح مسلم (۲۵۷۳)۔"}],[45,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nمسلمان کو جو بھی کوئی مصیبت پہنچتی ہے؛ اللہ تعالیٰ اس کے صلے میں اس کے گناہوں کو ختم کر دیتا ہے، یہاں تک کہ اگر اسے کوئی کانٹا بھی چبھ جائے (تو تب بھی یہی فضیلت حاصل ہوتی ہے)۔","",{"k":"صحیح بخاری (۵۶۴۰)، صحیح مسلم (۲۵۷۲)۔"}],[46,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجس بھی مومن کو دنیا میں کوئی کانٹا ہی چبھ جائے یا اس سے بھی چھوٹی کوئی تکلیف آئے اور وہ اس پر اَجر کی اُمید رکھے، تو اللہ تعالیٰ اس کے بدلے میں روزِ قیامت اس کی خطاؤں کو معاف فرما دے گا۔","صحیح",{"k":"مسند أحمد (۲؍۴۰۲)۔"}],[47,"سیدنا ابوسعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nمسلمان کو جو بھی پریشانی، دُکھ تکلیف اور غم پہنچتا ہے، یہاں تک کہ جو رنج اسے پریشان کر دیتا ہے، تو اللہ تعالیٰ اس کے بدلے بھی اس کی برائیوں کو دُور کر دیتا ہے۔","",{"k":"صحیح بخاری (۵۶۴۱)، صحیح مسلم (۲۵۷۳)۔"}],[48,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجس بھی مومن کو دنیا میں کوئی کانٹا ہی چبھ جائے یا اس سے بھی چھوٹی کوئی تکلیف آئے اور وہ اس پر اَجر کی اُمید رکھے، تو اللہ تعالیٰ اس کے بدلے میں روزِ قیامت اس کی خطاؤں کو معاف فرما دے گا۔","صحیح",{"k":"الأدب المفرد للبخاری (۵۰۷)۔"}],[49,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجس بھی بندۂ مسلم کو کوئی کانٹا چبھتا ہے یا اس سے بھی چھوٹی کوئی تکلیف پہنچتی ہے اور وہ اس پر اجر و ثواب کی اُمید رکھتا ہے تو اللہ تعالیٰ اس کی وجہ سے اس کے گناہوں کو معاف فرما دیتا ہے۔","صحیح",{"k":"مسند أحمد (۲؍۴۰۳)، الأدب المفرد للبخاری (۵۰۷)۔"}],[50,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجو بھی مومن مرد و عورت اور مسلمان مرد و عورت کسی مرض کا شکار ہوتا ہے؛ تو اللہ تعالیٰ اس سے اس کے گناہوں کو ختم کر دیتا ہے۔","إسنادہ لا بأس بہ",{"k":"مسند أحمد (۳؍۳۸۶)، مسند أبی داود الطیالسی (۱۷۷۳)، الأدب المفرد للبخاری (۵۰۸)، مسند أبی یعلی الموصلی (۳۳۰۵)۔"}],[51,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nکانٹا چبھنے سے یا اس سے بھی چھوٹی کوئی تکلیف جب مومن کو پہنچتی ہے تو اس کے بدلے میں گناہوں کا کفارہ کر دِیا جاتا ہے۔","",{"k":"صحیح بخاری (۵۶۴۰)، صحیح مسلم (۲۵۷۲)۔"}],[52,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ  صلی اللہ علیہ وسلم  کو فرماتے سنا:\nمسلمان کی تکلیف اس کے گناہوں کا کفارہ بن جاتی ہے۔","رجالہ ثقات",{"k":"شعب الإیمان للبیھقی (۷؍۱۵۸)، المستدرک للحاکم (۱؍۴۹۸)۔"}],[53,"محمد بن جبیر بن مطعم رحمہ اللہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nیقینا اللہ تعالیٰ اپنے بندے کو بیماری سے آزماتا ہے، یہاں تک کہ اس سے ہر وہ گناہ دُور کر دیتا ہے جو اس سے سرزد ہوا ہوتا ہے۔","حسن، لکنہ مرسل",{"k":"المعجم الکبیر للطبرانی (۲؍۱۲۹)، مجمع الزوائد للھیثمی (۲؍۳۰۲)، المستدرک للحاکم (۱؍۳۴۸)، الترغیب والترھیب للمنذری (۴؍۲۹۷)۔"}],[54,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں:\nکسی مسلمان کو کوئی کانٹا چبھ جائے، یا اس سے بھی چھوٹی تکلیف پہنچے، تو اللہ تعالیٰ اس کے بدلے میں اس کے گناہوں کو معاف فرما دیتا ہے۔","رجالہ ثقات",{"k":"مسند أحمد (۶؍۲۶۱)۔"}],[55,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ  صلی اللہ علیہ وسلم  کو فرماتے سنا:\nجو بھی مومن مرد و عورت اور مسلمان مرد و عورت کسی مرض کا شکار ہوتا ہے؛ تو اللہ تعالیٰ بدلے میں اس کے گناہوں کو معاف فرما دیتا ہے۔","رجالہ ثقات",{"k":"صحیح ابن حبان (۲۹۲۷)، مجمع الزوائد للھیثمی (۲؍۳۰۱)۔"}],[56,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجو مومن مرد و عورت مسلسل جسمانی، مالی یا اولاد کی پریشانیوں میں مبتلا رہتا ہے؛ یہاں تک کہ اللہ تعالیٰ سے جا ملتا ہے، اس پر کوئی گناہ باقی نہیں رہتا۔","حسن",{"k":"مسند أحمد (۲؍۲۸۷)، سنن الترمذی (۲۳۹۹)، الأدب المفرد للبخاری (۴۹۴)، الزھد لھناد (۴۰۲)، صحیح ابن حبان (۲۹۱۳)، شعب الإیمان للبیھقی (۷؍۱۵۹)، المستدرک للحاکم (۱؍۴۹۷)۔"}],[57,"عطاء بن یسار رحمہ اللہ سے مروی ہے کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nاللہ تعالیٰ بندے کو مسلسل آزماتا رہتا ہے، یہاں تک کہ جب بندہ اللہ سے جا ملتا ہے تو اس کا کوئی گناہ باقی نہیں بچا ہوتا ہے۔","مرسل",{"k":"المعجم الکبیر للطبرانی (۲؍۱۲۹)، مجمع الزوائد للھیثمی (۲؍۳۰۲)، المستدرک للحاکم (۱؍۳۴۸)، الترغیب والترھیب للمنذری (۴؍۲۹۷)۔","f":"اللہ تعالیٰ اپنے اسی بندے سے ایسا کرتا ہے جس سے اس کو محبت ہوتی ہے، اس لیے اسے دنیا میں کسی آزمائش سے دوچار کر کے آخرت کی بڑی آزمائش سے بچا لیتا ہے بلکہ اس کو دنیا میں ہی گناہوں سے پاک صاف کر کے اپنے پاس بلاتا ہے اور پھر اپنے ہاں عظیم درجات پر فائز کر دیتا ہے۔"}],[58,"معاذ بن انس الجہنی رحمہ اللہ بیان کرتے ہیں کہ:\nمیں سیدنا ابودرداء رضی اللہ عنہ کے ایامِ مرض میں ان کے پاس گیا تو میں نے کہا: اے ابودرداء! یقینا ہم تو تندرست رہنا ہی پسند کرتے ہیں، بیمار ہونا نہیں۔ تو سیدنا ابودرداء رضی اللہ عنہ نے کہا: میں نے رسول اللہ  صلی اللہ علیہ وسلم  کو فرماتے سنا: یقینا سر کی تکلیف اور اندرونی بخار جس مومن شخص کو ہو جاتے ہیں تو اس کے گناہوں میں سے رائی کے دانے کے برابر بھی کوئی گناہ نہیں چھوڑتے، خواہ اس کے گناہ اُحد پہاڑ کے برابر ہی ہوں۔","لا بأس بہ",{"k":"مسند أحمد (۵؍۱۹۸)، المعجم الأوسط للطبرانی (۶۳۴)، شعب الإیمان للبیھقی (۷؍۱۷۵)، مجمع الزوائد للھیثمی (۲؍۳۰۱)۔"}],[59,"یزید بن ابی حبیب رحمہ اللہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nسر کی تکلیف اور اندرونی بخار مسلمان شخص سے تب تک جدا نہیں ہوتے جب تک کہ اسے صاف و شفاف چاندی کی طرح (گناہوں سے پاک) نہیں کر چھوڑتے۔","مرسل",{"k":"شعب الإیمان للبیھقی (۹۴۳۱)، الدر المنثور للسیوطی (۲؍۷۰۱)۔"}],[60,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\nمیں اُمِ عبداللہ بن ابی ذئاب کی عیادت کے لیے گیا جب وہ بیمار ہوئیں، تو انہوں نے کہا: اے ابوہریرہ! میں سیدہ اُمِ سلمہ رضی اللہ عنہا کی بیماری میں ان کی عیادت کے لیے گئی تو انہوں نے میرے ہاتھ میں پھوڑا دیکھا اور کہا: میں نے رسول اللہ  صلی اللہ علیہ وسلم  کو فرماتے سنا: اللہ تعالیٰ جب کسی بندے کو آزمائش میں مبتلا کرتا ہے اور وہ آزمائش ایسی صورت میں آتی ہے کہ جسے وہ ناپسند کرتا ہے، تو اللہ تعالیٰ اس آزمائش کو اس کے لیے گناہوں کا کفارہ اور پاکیزگی کا باعث بنا دیتا ہے، اور یہ اسی صورت میں ہوتا ہے کہ بندہ اس آزمائش سے خلاصی کے لیے کسی غیر اللہ کے پاس دھکے نہ کھاتا پھرے یا اس سے خلاصی کے لیے کسی غیر اللہ سے دعا نہ مانگے۔","ضعیف",{"k":"الترغیب والترھیب للمنذری (۴؍۱۴۱)۔"}],[61,"عطیہ بن قیس رحمہ اللہ بیان کرتے ہیں کہ:\nسیدنا کعب رضی اللہ عنہ بیمار ہوئے تو اہل دمشق میں سے کچھ لوگ ان کی عیادت کو آئے اور انہوں نے پوچھا: اے ابواسحاق! کیسی طبیعت ہے؟ تو انہوں نے فرمایا: اس جسم کی خیریت کے ساتھ ہوں جس کا گناہوں کی وجہ سے مواخذہ ہوا ہے، اگر اس کا پروردگار چاہے گا تو اسے عذاب دے گا اور اگر چاہے گا تو اس پر رحم فرمائے گا، اور اگر اس نے اسے (صحت یاب کر کے) اُٹھا لیا تو اسے ایک نئی خلقت دے گا، جس میں اس کا کوئی گناہ باقی نہ ہو گا۔","ضعیف",{"k":"تفرّد بہ المؤلف۔"}],[62,"سعید بن وھب رحمہ اللہ بیان کرتے ہیں کہ:\nمیں سیدنا سلمان رضی اللہ عنہ کے ساتھ کندہ کے ایک آدمی کی عیادت کے لیے گیا تو سیدنا سلمان رضی اللہ عنہ نے فرمایا: یقینا مسلمان کی آزمائش کی جاتی ہے اور وہ آزمائش اس کے گزشتہ گناہوں کا کفارہ بن جاتی ہے اور آئندہ کے لیے (رب تعالیٰ کی) خوشنودی چاہنے کا ذریعہ بن جاتی ہے۔ جبکہ کافر کی آزمائش کی جاتی ہے تو اس کی مثال اونٹ کی سی ہوتی ہے کہ جسے کھول دِیا جائے تو اسے کچھ معلوم نہیں ہوتا کہ کیوں کھولا گیا ہے اور باندھ دِیا جائے تو کچھ معلوم نہیں ہوتا کہ کیوں باندھا گیا ہے۔","رجالہ ثقات",{"k":"المصنف لابن أبی شیبۃ (۳؍۲۳۱)، الزھد لھناد (۱؍۲۴۲)، الأدب المفرد للبخاری (۴۹۳)۔"}],[63,"سیدنا ابوامامہ رضی اللہ عنہ سے مروی ہے کہ نبی  صلی اللہ علیہ وسلم  نے فرمایا:\nبخار جہنم کی ایک دھونکنی ہے، سو جس مومن کو بخار ہوتا ہے اسے (جہنم کی) آگ سے حصہ مل جاتا ہے۔","ضعیف",{"k":"مسند أحمد (۵؍۲۶۴)، المعجم الکبیر للطبرانی (۸؍۹۳)، شعب الإیمان للبیھقی (۷؍۱۶۱)، الترغیب والترھیب للمنذری (۴؍۱۵۴)، مجمع الزوائد للھیثمی (۲؍۳۰۵)۔"}],[64,"سیدنا عثمان بن عفان رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nبخار؛ قیامت کے روز مومن کا (جہنم کی) آگ سے حصہ بن جائے گا۔","ضعیف",{"k":"تاریخ دمشق لابن عساکر (۵۹؍۳۱۳)۔","f":"یعنی اسے آخرت میں اس کے گناہوں پر ملنے والی سزا اس قدر کم ہو جاتی ہے جس قدر اسے دنیا میں بخار ہوا ہوتا ہے۔"}],[65,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجو بھی مسلمان بیمار ہوتا ہے تو اللہ تعالیٰ اس پر اپنے دو فرشتے مقرر کر دیتا ہے جو تب تک اس سے الگ نہیں ہوتے جب تک کہ اللہ تعالیٰ اس کے معاملے میں دو بہتر کاموں میں سے ایک کا فیصلہ نہیں فرما دیتا: یا تو وہ اسے موت سے ہمکنار کر دیتا ہے یا اسے زندگی بخش دیتا ہے۔ پھر جب عیادت کے لیے آنے والے لوگ اس سے پوچھتے ہیں کہ تمہاری طبیعت کیسی ہے؟ تو وہ کہتا ہے: میں اللہ کا شکرگزار ہوں اور اللہ ہی تعریف و ستائش کے لائق ہے، میں اب خود کو بہتر محسوس کرتا ہوں۔ تو فرشتے اس سے کہتے ہیں: تجھے پہلے خون سے بہتر خون کی بشارت ہو اور پہلی صحت سے اچھی صحت مبارک ہو۔ لیکن اگر وہ کہے کہ میں تو بہت سخت آزمائش میں مبتلا ہوں۔ تو فرشتے اس سے کہتے ہیں: تجھے پہلے خون سے برے خون کی بشارت ہو اور تیری اس آزمائش سے بھی لمبی آزمائش کی تجھے مبارک ہو۔","ضعیف",{"k":"شعب الإیمان للبیھقی (۱۲؍۳۲۹)۔","f":"انسان کو بہ ہر حال خدا تعالیٰ کا شکرگزار رہنا چاہیے، کسی بھی صورت میں اپنی زبان پر ناشکری کے کلمات نہیں لانے چاہئیں۔ جس ذاتِ مقدس نے آزمائش ڈالی ہے اس نے تکلیف کے اس وقت سے کہیں زیادہ تندرستی اور فراخت کا وقت بھی تو عطا کیا تھا۔ اگر کچھ وقت کے لیے وہ اپنے بندے کو آزماتا ہے تو محبتِ الٰہی کا اتنا تو پاس بندے کو رکھنا چاہیے کہ اس کا کوئی شکوہ نہ کرے۔ وگرنہ فرشتوں سے دعاؤں کی بہ جائے بددعائیں ہی لے گا۔"}],[66,"عمران بن حُدیر بیان کرتے ہیں کہ:\nابومجلز رحمہ اللہ فرمایا کرتے تھے: مریض سے وہی باتیں کرو جو اسے اچھی لگتی ہوں۔ راوی بیان کرتے ہیں کہ مجھے طاعون کا مرض لاحق تھا تو وہ میرے پاس آیا کرتے اور فرماتے: آج کے دِن کو زندوں میں شمار کیجیے اور جو اس سے اوپر ہو جائے اسے بھی ان ہی میں شمار کر لینا۔ راوی کہتے ہیں کہ میں اس بات سے خوش ہو جاتا۔","رجالہ ثقات",{"k":"شعب الإیمان للبیھقی (۱۱؍۴۲۶)۔","f":"پسند کی باتوں سے صرف وہ باتیں مراد ہیں جن میں کوئی شرعی قباحت نہ ہو، لیکن اگر مریض کا دِل غیر شرعی یا غیر اخلاقی باتیں کرنے کو چاہے تو ایسی صورت میں اس کا ساتھ دینا قطعاً جائز نہیں ہے۔"}],[67,"سیدنا عقبہ بن عامر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nتم اپنے مریضوں کو کھانے پینے پر مجبور مت کرو، کیونکہ بلاشبہ انہیں اللہ تعالیٰ کھلاتا اور پلاتا ہے۔","ضعیف",{"k":"سنن الترمذی (۲۰۴۰)، سنن ابن ماجہ (۳۴۴۴)، المعجم الکبیر للطبرانی (۱۷؍۲۹۳)، المعجم الأوسط للطبرانی (۶۲۷۲)، مسند أبی یعلی الموصلی (۱۷۴۱)، المستدرک للحاکم (۱؍۵۰۱)۔"}],[68,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\nمیں بیمار ہو گئی تو میرے گھر والے مجھے ہر چیز ، یہاں تک کہ پانی سے بھی پرہیز کرواتے تھے۔ ایک رات مجھے پیاس لگی، میرے پاس کوئی بھی نہیں تھا، میں لٹکتے ہوئے مشکیزے کے قریب ہوئی اور تھوڑا سا پانی پی لیا۔ پانی پی کر میں کھڑی ہوئی تو اچھی بھلی ہو گئی، میں سمجھنے لگی کہ یہ پانی پینا ہی میرے بدن کی صحت کا باعث بنا ہے۔ سیدہ عائشہ رضی اللہ عنہا فرمایا کرتی تھیں: بیمار کو کسی چیز سے پرہیز نہ کراؤ۔","لا بأس بہ",{"k":"المستدرک للحاکم (۴؍۴۰۸)۔"}],[69,"سیدنا ابن عمر رضی اللہ عنہما بیان کرتے ہیں کہ میں نے سیدنا عمر رضی اللہ عنہ کو فرماتے سنا:\nاگر تمہارے مریض کا کسی چیز کو دِل چاہے تو اسے منع مت کرو، کیونکہ شاید اللہ تعالیٰ نے ہی اس میں اس چیز کی چاہت ڈالی ہو تاکہ وہ اس چیز میں اس کے لیے شفا رکھ دے۔","حسن",{"k":"شعب الإیمان للبیھقی (۱۱؍۴۳۶)۔"}],[70,"عبدالملک بن عمیر بیان کرتے ہیں کہ سیدنا ابوالدرداء رضی اللہ عنہ نے فرمایا:\nایک رات کا بخار ایک سال (کے گناہوں) کا کفارہ بن جاتا ہے۔","ضعیف",{"k":"شعب الإیمان للبیھقی (۱۲؍۲۸۳)۔"}],[71,"ثابت رحمہ اللہ بیان کرتے ہیں کہ:\nہم امام حسن رحمہ اللہ کے ساتھ صفوان بن محرز کے ہاں ان کی عیادت کرنے گئے تو ان کا صاحبزادہ باہر نکلا اور اس نے کہا: وہ پیٹ کے مرض میں مبتلا ہیں، آپ ان سے ملاقات نہیں کر سکتے۔ تو حسن رحمہ اللہ نے فرمایا: (اگر اس بیماری کے باعث) آج ان کا گوشت اور خون لے لیا جائے اور اس کے بدلے میں انہیں اجر و ثواب سے نواز دِیا جائے تو یہ اس کے لیے اس بات سے بہتر ہے کہ اسے مٹی کھا جائے۔","رجالہ ثقات",{"k":"الزھد لأحمد بن حنبل، ص: ۲۵۷۔","f":"امام حسن رحمہ اللہ کے کہنے کا مطلب یہ تھا کہ اگر پیٹ کی بیماری سے آج دنیا میں ان کا کچھ گوشت اور خون ضائع بھی ہو جاتا ہے تو یہ رائیگاں نہیں جائے گا، بلکہ اس پر انہیں اجر و ثواب سے نوازا جائے گا، اس لیے بہ جائے اس کے کہ اس گوشت کو قبر کی مٹی کھائے؛ اس کا یہاں آزمائش میں مبتلا ہوکر ضائع ہو جانا یا کم ہو جانا اس سے کہیں بہتر ہے۔"}],[72,"ثابت رحمہ اللہ بیان کرتے ہیں کہ:\nہم سیدنا ربیعہ بن حارث رضی اللہ عنہ کی عیادت کے لیے حاضر ہوئے جبکہ ان کی طبیعت بہت گراں ہو چکی تھی، تو انہوں نے فرمایا: یقینا جو شخص میرے جیسی اس حالت میں ہوتا ہے اس کے دِل میں آخرت کا خیال بھر جاتا ہے اور اس کی نظر میں دنیا کی مکھی سے بھی چھوٹی ہو جاتی ہے۔","رجالہ ثقات",{"k":"تفرّد بہ المؤلف۔"}],[73,"سیدنا عبادہ بن صامت رضی اللہ عنہ بیان کرتے ہیں کہ:\nمیں نبی  صلی اللہ علیہ وسلم  کی خدمت میں حاضر ہوا تو آپ تکلیف میں مبتلا تھے۔ اس تکلیف کی شدت اس قدر تھی کہ بس اللہ ہی کو حال معلوم تھا۔ پھر میں شام کے وقت آپ  صلی اللہ علیہ وسلم  کی خدمت میں حاضر ہوا تو عرض کیا: اے اللہ کے رسول! میں جب صبح آپ کے پاس آیا تھا تو آپ بہت سخت تکلیف میں مبتلا تھے، جس کا حال اللہ ہی جانتا تھا۔ لیکن اب شام کو حاضر ہوا ہوں تو اللہ تعالیٰ نے آپ کو صحت یاب کر دیا ہے۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: جبرائیل علیہ السلام نے مجھے ایک دَم کیا ہے۔ اے عبادہ! کیا میں وہ دَم تمہیں بھی نہ سکھلا دوں؟ میں نے عرض کیا: اے اللہ کے رسول! کیوں نہیں۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: (وہ دَم یہ ہے:)\nبِسْمِ اللّٰہِ أَرْقِیکَ، وَاللّٰہُ یَشْفِیکَ مِنْ حَسَدِ کُلِّ حَاسِدٍ وَعَیْنٍ اللّٰہُ یَشْفِیکَ\n‘‘اللہ کے نام کے ساتھ میں تجھے دَم کرتا ہوں، اللہ تجھے ہر حسد کرنے والے کے حسد سے اور ہر بری نظر سے شفا عطا فرمائے، اللہ تعالیٰ ہی تجھے شفا دے گا۔’’\nسیدنا عبادہ بن صامت رضی اللہ عنہ بیان کرتے ہیں کہ:\nمیں نبی  صلی اللہ علیہ وسلم  کی خدمت میں حاضر ہوا تو آپ تکلیف میں مبتلا تھے۔ اس تکلیف کی شدت اس قدر تھی کہ بس اللہ ہی کو حال معلوم تھا۔ پھر میں شام کے وقت آپ  صلی اللہ علیہ وسلم  کی خدمت میں حاضر ہوا تو عرض کیا: اے اللہ کے رسول! میں جب صبح آپ کے پاس آیا تھا تو آپ بہت سخت تکلیف میں مبتلا تھے، جس کا حال اللہ ہی جانتا تھا۔ لیکن اب شام کو حاضر ہوا ہوں تو اللہ تعالیٰ نے آپ کو صحت یاب کر دیا ہے۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: جبرائیل علیہ السلام نے مجھے ایک دَم کیا ہے۔ اے عبادہ! کیا میں وہ دَم تمہیں بھی نہ سکھلا دوں؟ میں نے عرض کیا: اے اللہ کے رسول! کیوں نہیں۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: (وہ دَم یہ ہے:)\nبِسْمِ اللّٰہِ أَرْقِیکَ، وَاللّٰہُ یَشْفِیکَ مِنْ حَسَدِ کُلِّ حَاسِدٍ وَعَیْنٍ اللّٰہُ یَشْفِیکَ\n‘‘اللہ کے نام کے ساتھ میں تجھے دَم کرتا ہوں، اللہ تجھے ہر حسد کرنے والے کے حسد سے اور ہر بری نظر سے شفا عطا فرمائے، اللہ تعالیٰ ہی تجھے شفا دے گا۔’’","حسن",{"k":"مسند أحمد (۵؍۳۲۳)، سنن ابن ماجہ (۳۵۲۷)، السنن الکبرٰی للنسائی (۱۰۸۴۲)، صحیح ابن حبان (۲۹۶۸)۔\nمسند أحمد (۵؍۳۲۳)، سنن ابن ماجہ (۳۵۲۷)، السنن الکبرٰی للنسائی (۱۰۸۴۲)، صحیح ابن حبان (۲۹۶۸)۔"}],[74,"امام حسن رحمہ اللہ نے درد اور تکلیف کا تذکرہ کرتے ہوئے فرمایا:\nسنو! اللہ کی قسم! مسلمان کے وہ ایام جو اس کے لیے خوشی کا باعث ہو سکتے ہیں وہ ایام ہیں جن میں اس کے لیے اللہ تعالیٰ کا قرب حاصل کرنے کا سامان ہو اور ان میں اسے اس چیز کی یاد دِلائی جاتی ہے جسے وہ اپنی آخرت کے سلسلے میں بھول چکا ہوتا ہے اور اس کے باعث اس کے گناہوں کا کفارہ کیا جاتا ہے۔","حسن",{"k":"شعب الإیمان للبیھقی (۱۲؍۳۵۱)۔"}],[75,"ابومحمد حبیب الھرانی بیان کرتے ہیں کہ:\nمیری بیماری کے ایام میں امام حسن رحمہ اللہ نے میری عیادت کی اور مجھ سے فرمایا: اے حبیب! اگر ہمیں صرف انہی امور میں اجر سے نوازا جاتا جنہیں ہم پسند کرتے ہیں؛ تو ہمارا اجر بہت کم ہوتا، اور یقینا ربِ کریم بندے کو آزماتا ہے جبکہ وہ (آزمائش کو) ناپسند کرتا ہے، حالانکہ اللہ تعالیٰ اللہ تعالیٰ اس پر اسے اجرِ عظیم سے نوازتا ہے۔","حسن",{"k":"شعب الإیمان للبیھقی (۱۲؍۳۵۲)۔","f":"یعنی اگر انسان کو صرف اس کے پسندیدہ کاموں پر ہی اجر و ثواب سے نوازا جاتا تو پھر تو اس کا اجر بہت کم ہوتا، کیونکہ انسان طبعی طور پر مصائب و تکالیف اور آزمائشوں کو پسند نہیں کرتا، بلکہ فراخی و تندرستی کی زندگی چاہتا ہے، جبکہ اجر و ثواب تو مصائب و بلایا کی صورت میں ملتا ہے۔"}],[76,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\nرسول اللہ  صلی اللہ علیہ وسلم  ایک درخت کے پاس جا کر رُک گئے اور اسے زور سے ہلایا، یہاں تک کہ جتنے اللہ نے چاہے اس کے پتے گرے، پھر آپ  صلی اللہ علیہ وسلم  نے فرمایا: مصائب اور تکالیف میری اُمت کے گناہوں کو میری نسبت کے باعث اس درخت کے پتوں سے بھی زیادہ تیز جھاڑ دیتے ہیں۔","ضعیف",{"k":"الترغیب والترھیب للمنذری (۴؍۱۴۵)۔"}],[77,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\nرسول اللہ  صلی اللہ علیہ وسلم  ایک درخت کے پاس تشریف لائے اور اسے زور سے ہلایا، یہاں تک کہ اس کے پتے گر نے لگے، پھر آپ  صلی اللہ علیہ وسلم  نے فرمایا: مصیبت (یا فرمایا کہ) مصائب اور تکالیف میری اُمت کے گناہوں کو میری نسبت کی وجہ سے اس درخت کے پتوں سے بھی زیادہ تیز جھاڑ دیتی ہیں۔","ضعیف",{"k":"مجمع الزوائد للھیثمی (۲؍۳۰۱)۔"}],[78,"عکرمہ رحمہ اللہ بیان کرتے ہیں کہ:\nسیدنا انس بن مالک رضی اللہ عنہ بیمار ہوئے تو ان کی عیادت کے لیے ایک آدمی آیا، وہ ان کے پاس آ کر ٹھہرا اور کہا: اے ابوحمزہ! اگر میرا گھر دور نہ ہوتا تو میں روزانہ آپ کی خدمت میں حاضر ہوتا اور آپ کو سلام کرتا۔ سیدنا انس رضی اللہ عنہ اپنے بستر پر سیدھے لیٹے ہوئے تھے اور ان کے چہرے پر کپڑے کا ٹکڑا یا رومال تھا، انہوں نے اسے اپنے چہرے سے ہٹایا، پھر سیدھے ہو کر بیٹھ گئے اور کہا: سنو! میں نے رسول اللہ  صلی اللہ علیہ وسلم  کو فرماتے سنا: جو شخص کسی مریض کی عیادت کرتا ہے وہ تب تک رحمت میں داخل رہتا ہے جب تک کہ اس کے پاس پہنچ نہیں جاتا، پھر جب اس کے پاس (پہنچ کر) بیٹھ جاتا ہے تو رحمت اسے ڈھانپ لیتی ہے۔ سیدنا انس رضی اللہ عنہ نے بیان کیا کہ جب نبی  صلی اللہ علیہ وسلم  نے یہ فرمایا تو میں نے عرض کیا: یہ تو مریض کی عیادت کرنے والے کی فضیلت ہو گئی، مریض کے لیے کیا اجر ہے؟ آپ  صلی اللہ علیہ وسلم  نے فرمایا: جب بندہ تین دِن تک بیمار رہتا ہے تو وہ گناہوں سے اس طرح نکل جاتا ہے جیسے وہ اس دِن (گناہوں سے پاک) تھا جس دِن اس کی ماں نے اسے جنم دِیا تھا۔","ضعیف",{"k":"المعجم الصغیر للطبرانی (۵۱۹)۔"}],[79,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ:\nنبی  صلی اللہ علیہ وسلم  مریض کی عیادت تین دِن کے بعد ہی فرمایا کرتے تھے۔","ضعیف",{"k":"سنن ابن ماجہ (۱۴۳۷)، المعجم الأوسط للطبرانی (۳۶۴۲)، الکامل لابن عدی (۶؍۳۱۷)۔"}],[80,"نعمان بن ابوعیاش الزرقی رحمہ اللہ فرماتے ہیں:\nمریض کی عیادت تین دِن کے بعد کرنی چاہیے۔","إسنادہ لا بأس بہ",{"k":"الزھد لھناد (۱؍۲۲۸)، المقاصد الحسنۃ للسخاوی، ص: ۲۹۳، تنزیہ الشریعۃ لابن عراق (۲؍۳۵۷)۔"}],[81,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nاونٹنی کا دودھ دوہنے کے بہ قدر وقت (مریض کے پاس بیٹھنا) بھی عیادت ہی ہوتی ہے۔","ضعیف",{"k":"شعب الإیمان للبیھقی (۶؍۵۴۳)۔","f":"یعنی ضروری نہیں ہے کہ آپ مریض کے پاس گھنٹوں بیٹھیں تو ہی عیادت کا فریضہ ادا ہوتا ہے بلکہ مختصر سا وقت بیٹھنا بھی عیادت ہی شمار ہوتا ہے۔ لہٰذا جس قدر ہو سکے عیادت کا اہتمام کرنا چاہیے تاکہ یہ اخلاقی فرضہ بھی ادا ہو سکے اور عیادت کا ڈھیروں اجر و ثواب بھی حاصل کیا جا سکے۔"}],[82,"سعید بن مسیب رحمہ اللہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nسب سے زیادہ فضیلت والی عیادت وہ ہے جس میں (عیادت کرنے والا) جلدی اُٹھ پڑے۔","مرسل",{"k":"شعب الإیمان للبیھقی (۱۱؍۴۳۱)۔"}],[83,"طاؤس رحمہ اللہ فرماتے ہیں کہ:\nبہترین عیادت وہ ہے جو مختصر ترین ہو۔","حسن لشواھدہ",{"k":"المصنف لعبد الرزاق (۳؍۵۹۴)۔"}],[84,"امام طاؤس رحمہ اللہ فرماتے ہیں:\nافضل عیادت وہ ہوتی ہے جو مختصر وقت کے لیے ہو۔","حسن لغیرہ",{"k":"شعب الإیمان للبیھقی (۱۱؍۴۳۳)، المصنف لعبد الرزاق (۳؍۵۹۴)۔","f":"یہ اس صورت میں ہے کہ جب مریض کی طبیعت زیادہ خراب ہو اور لوگوں کا جمع ہونا اس کے لیے گراں گزر رہا ہو، یا کسی کا زیادہ دیر تک بیٹھے رہنا اس کے لیے تکلیف کا باعث ہو۔ لیکن اگر مریض کا دِل چاہ رہا ہو کہ اس کے پاس بیٹھ کر باتیں کی جائیں تو پھر زیادہ دیر تک بیٹھنے میں کوئی حرج نہیں ہے۔"}],[85,"سیدنا ثوبان رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nیقینا جب آدمی اپنے (مسلمان) بھائی کی عیادت کرتا ہے تو جب تک واپس نہیں آ جاتا تب تک جنت کے باغات میں ہی رہتا ہے۔","",{"k":"صحیح مسلم (۲۵۶۸)۔"}],[86,"سیدنا علی رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ  صلی اللہ علیہ وسلم  کو فرماتے سنا:\nجب کوئی شخص اپنے(مسلمان)بھائی کی عیادت کرنے آتا ہے تو وہ (مریض کے پاس آکر) بیٹھ جانے تک جنت کے باغات میں چلتا آتا ہے، اور جب وہ بیٹھ جاتاہے تورحمت اس پرسایہ فگن ہوجاتی ہے، پھراگروہ صبح کو(عیادت کے لیے) آیا ہو تو شام تک ستّرہزار فرشتے اس کے حق میں رحمت کی دعائیں کرتے رہتے ہیں اور اگر وہ شام کو آیا ہو تو صبح تک ستّرہزار فرشتے اس کے لیے دعائیں کرتے رہتے ہیں۔","صحیح",{"k":"مسند أحمد (۱؍۱۳۸)، سنن أبی داود (۳۱۰۰)، سنن ابن ماجہ (۱۴۴۲)، مسند البزار (۶۲۰)۔"}],[87,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجو شخص کسی مریض کی عیادت کرتا ہے یا کسی (مسلمان) بھائی سے اللہ کی رضا کی خاطر ملنے جاتا ہے، تو آسمان سے ایک فرشتہ یہ آواز لگاتا ہے کہ تو بھی پاک (اور اچھا) ہے اور تیرا چلنا بھی اچھا ہے اور تو نے جنت میں گھر بنا لیا ہے۔","حسن",{"k":"مسند أحمد (۲؍۳۴۴)، سنن الترمذی (۲۰۰۸)، سنن ابن ماجہ (۱۴۴۳)، الأدب المفرد للبخاری (۳۴۵)، مسند عبد بن حمید (۱۴۵۱)، صحیح ابن حبان (۲۹۶۱)۔"}],[88,"سیدنا ابوسعید رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجب آدمی فقط رضائے الٰہی کی خاطر کسی مریض کی عیادت کرتا ہے تو اس کے ساتھ ستر ہزار فرشتے چل پڑتے ہیں جو اس کے لیے استغفار کرتے ہیں اور وہ رحمت میں داخل رہتا ہے، یہاں تک کہ جب اس کے پاس پہنچ جاتا ہے تو اس رحمت میں ڈوب جاتا ہے۔","ضعیف",{"k":"لسان المیزان (۳؍۱۶)۔"}],[89,"عبداللہ بن نافع بیان کرتے ہیں کہ:\nامامِ حسن رضی اللہ عنہ بیمار ہوئے تو سیدنا ابوموسیٰ اشعری رضی اللہ عنہ ان کی عیادت کے لیے آئے، تو سیدنا علی رضی اللہ عنہ نے ان سے کہا: ہمارے دِل میں جو آپ کے بارے میں خفگی ہے وہ ہمیں اس بات سے نہیں روک سکتی کہ ہم آپ سے وہ حدیث بیان کریں جو ہم نے سنی ہے (وہ یہ ہے کہ) جو شخص کسی مریض کی عیادت کرتا ہے تو ستر ہزار فرشتے اس کے پیچھے جاتے ہیں اور وہ تمام اس کے لیے استغفار کرتے ہیں، اگر وہ صبح کو (عیادت کے لیے) گیا ہو تو شام تک اور اگر وہ شام کو گیا ہو تو صبح تک وہ مغفرت کی دعائیں کرتے رہتے ہیں، اور اس کے لیے جنت میں ایک باغ تیار کر دِیا جاتا ہے۔","حسن",{"k":"مسند أحمد (۱؍۱۳۸)، مسند البزار (۶۲۰)۔"}],[90,"عبداللہ بن یسار بیان کرتے ہیں کہ:\nعمرو بن حریث رضی اللہ عنہ امام حسن بن علی بن ابی طالب رضی اللہ عنہ کی عیادت کے لیے آئے تو سیدنا علی رضی اللہ عنہ نے کہا: اے عمرو! یوں تو آپ حسن کی عیادت کے لیے آئے ہیں لیکن دِل میں جو کچھ چھپا رکھا ہے اس کا کیا ہو گا؟ تو عمرو رضی اللہ عنہ نے کہا: اے علی! ہاں، لیکن آپ میرے دِل کے رب نہیں ہیں کہ جس طرح چاہیں اسے تصرف کرنا شروع کر دیں۔ تو سیدنا علی رضی اللہ عنہ نے کہا: لیکن اس کے باوجود ہم آپ سے نصیحت کی بات کہنے سے نہیں رُکیں گے، میں نے رسول اللہ  صلی اللہ علیہ وسلم  کو فرماتے سنا: جو بھی مسلمان کسی مسلمان کی عیادت کرتا ہے اللہ تعالیٰ اس کے لیے ستر ہزار فرشتے مقرر فرما دیتا ہے جو شام تک ان کے ہر لمحے میں اس کے لیے رحمت کی دعائیں کرتے رہتے ہیں اور اگر وہ شام کو عیادت کرے تو صبح تک رات کی ہر گھڑی میں اس کے لیے دعائیں کرتے رہتے ہیں۔","ضعیف",{"k":"مسند أحمد (۱؍۹۷)، صحیح ابن حبان (۲۹۵۸)، مجمع الزوائد للھیثمی (۳؍۳۱)۔"}],[91,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجو شخص کسی مریض کی عیادت کرتا ہے اور ایک گھڑی اس کے پاس بیٹھتا ہے تو اللہ تعالیٰ اس کے لیے ایک سال کے اعمال جاری فرما دیتا ہے جس میں اس نے پلک جھپکنے کے برابر بھی نافرمانی نہیں کی ہوتی۔","ضعیف",{"k":"الترغیب والترھیب للمنذری (۴؍۱۶۵)، حلیۃ الأولیاء لأبی نعیم (۸؍۱۶۱)۔"}],[92,"سیدنا زید بن ارقم رضی اللہ عنہ بیان کرتے ہیں کہ:\nمجھے آشوبِ چشم کا مرض لاحق ہو گیا تو رسول اللہ  صلی اللہ علیہ وسلم  نے میری عیادت فرمائی۔","حسن",{"k":"مسند أحمد (۴؍۳۷۵)، المستدرک للحاکم (۱؍۴۹۲)۔"}],[93,"بکر بن عبداللہ المزنی رحمہ اللہ فرماتے ہیں:\nمریض کی عیادت کی جائے اور تندرست سے ملاقات کی جائے۔","حسن",{"k":"حلیۃ الأولیاء لأبی نعیم (۲؍۲۲۷)، الطبقات لابن سعد (۷؍۲۱۱)۔","f":"یعنی صرف کسی کے بیمار ہونے کی صورت میں ہی اس کے پاس نہ جایا جائے بلکہ تندرستی میں بھی مسلمان بھائی کی ملاقات کے لیے جانے کا اہتمام رکھنا چاہیے۔ اس سے نہ صرف اس کی محبت حاصل ہوتی ہے بلکہ اللہ تعالیٰ بھی خوش ہوتا ہے۔"}],[94,"امام شعبی رحمہ اللہ فرماتے ہیں:\n(لمبی) عیادت مریض کے اہل خانہ پر ان کے مریض سے بھی زیادہ گراں ہو جاتی ہے، لوگ بے وقت عیادت کے لیے آتے ہیں اور لمبی دیر تک بیٹھے رہتے ہیں۔","ضعیف",{"k":"المصنف لعبد الرزاق (۳؍۵۹۴)۔"}],[95,"ابوالعالیہ رحمہ اللہ بیان کرتے ہیں کہ:\nغالب القطان رحمہ اللہ ان کی عیادت کے لیے تشریف لائے اور کچھ ہی دیر ٹھہرے اور پھر اُٹھ کھڑے ہوئے۔ تو ابوالعالیہؒ نے کہا: عرب کس قدر شفیق ہیں، مریض کے پاس بیٹھ نہیں رہتے، کیونکہ مریض کو اچانک کوئی حاجت پیش آ جاتی ہے لیکن وہ اپنے پاس بیٹھے ہوئے لوگوں سے شرماتا رہتا ہے۔","حسن",{"k":"شعب الإیمان للبیھقی (۱۱؍۴۳۲)۔"}],[96,"عکرمہ رحمہ اللہ سے مروی ہے کہ سیدنا ابن عباس رضی اللہ عنہما نے فرمایا:\nسال میں ایک مرتبہ مریض کی عیادت لازمی کی جائے، لیکن اگر تم زیادہ مرتبہ کرو تو یہ نفلی نیکی ہے۔","ضعیف",{"k":"المعجم الکبیر للطبرانی (۱۱؍۲۵۸)، مسند البزار (۱؍۳۶۸)، مجمع الزوائد للھیثمی (۲؍۲۹۶)۔","f":"یعنی کم از کم سال بھر میں ایک بار کسی مریض کی عیادت لازمی کرنی چاہیے، لیکن زیادہ کی کوئی قید نہیں۔ جتنا زیادہ کوئی اس پر عمل کرے گا اتنا ہی زیادہ وہ اجر کمائے گا۔ عیادت کی ترغیب اس لیے ہے تاکہ انسان کو اللہ تعالیٰ کی اسے دی ہوئی عظیم نعمت صحت کی قدر و اہمیت کا اندازہ ہوتا رہے۔"}],[97,"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nایک دِن کے وقفے کے ساتھ عیادت کرو اور چار دِن کے بعد جاؤ، سوائے اس صورت کے کہ مریض کی حالت زیادہ خراب ہو۔","ضعیف",{"k":"شعب الإیمان للبیھقی (۶؍۵۴۲)۔"}],[98,"سیدنا ابوامامہ باہلی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nتم میں سے کسی کا اپنے مریض بھائی کی عیادت کرنا اس طرح مکمل ہوتا ہے کہ وہ اپنا ہاتھ اس پر رکھے اور اس سے پوچھے: صبح کیسی رہی؟ شام کیسی گزری؟","ضعیف",{"k":"مسند أحمد (۵؍۲۵۹)، سنن الترمذی (۲۷۳۱)، المعجم الکبیر للطبرانی (۸؍۲۱۱)۔"}],[99,"سیدنا ابواُمامہ رضی اللہ عنہ سے مروی ہے کہ نبی  صلی اللہ علیہ وسلم  نے فرمایا:\nمریض کی عیادت تب مکمل ہوتی ہے کہ تم میں سے کوئی اپنا ہاتھ اس کی پیشانی پر یا اس کے ہاتھ پر رکھے اور اس سے پوچھے کہ اس کا کیا حال ہے؟ اور تمہارا آپس میں سلام مصافحے کے ساتھ پورا ہوتا ہے۔","ضعیف",{"k":"مسند أحمد (۵؍۲۵۹)، سنن الترمذی (۲۷۳۱)، المعجم الکبیر للطبرانی (۸؍۲۱۱)۔"}],[100,"سیدنا ابواُمامہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nمریض کی عیادت کرنے والا رحمت میں غوطہ زن رہتا ہے اور عیادت تب مکمل ہوتی ہے کہ آدمی اپنا ہاتھ مریض کی جانب بڑھائے۔","ضعیف",{"k":"مسند أحمد (۵؍۲۵۹)، سنن الترمذی (۲۷۳۱)، المعجم الکبیر للطبرانی (۸؍۲۱۱)۔"}],[101,"عطاء رحمہ اللہ فرماتے ہیں:\nکامل عیادت کا یہ بھی جزو ہے کہ آپ اپنا ہاتھ مریض پر رکھیں۔","رجالہ ثقات",{"k":"شعب الإیمان للبیھقی (۱۱؍۴۲۴)۔"}],[102,"سیدنا ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nمریض کی دعا کو رَد نہیں کیا جاتا، یہاں تک کہ وہ صحت یاب ہو جائے۔","ضعیف",{"k":"شعب الإیمان للبیھقی (۷؍۲۱۰)۔"}],[103,"عبداللہ بن ابی صالح بیان کرتے ہیں کہ:\nجب میں بیمار تھا تو امام طاؤس رحمہ اللہ میرے پاس تشریف لائے۔ میں نے گزارش کی: اے ابوعبدالرحمان! میرے لیے دعا فرما دیجیے۔ تو انہوں نے فرمایا: آپ خود ہی اپنے لیے دعا کیجیے، کیونکہ اللہ تعالیٰ سے جب کوئی لاچار شخص دعا کرتا ہے تو وہ قبول فرماتا ہے۔","فیہ من لم أعرفہ",{"k":"شعب الإیمان للبیھقی (۱۲؍۳۶۷)۔"}],[104,"حسن رحمہ اللہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nبخار؛ موت کا راہنما ہے اور یہ زمین میں مومن کے لیے اللہ کی قید ہے۔","إسنادہ حسن والحدیث مرسل",{"k":"شعب الإیمان للبیھقی (۱۲؍۲۸۴)۔"}],[105,"سعید بن جبیر رحمہ اللہ فرماتے ہیں:\nبخار؛ موت کا راہنما ہے۔","حسن",{"k":"الزھد لھناد (۲۰۷)۔","f":"راہنما ہونے سے مراد یہ ہے کہ موت کو انسان تک پہنچنے کی راہ بخار ہی دِکھاتا ہے۔ اس لیے جب کسی کو بخار ہو جائے تو اسے چاہیے کہ وہ اپنے گناہوں کی توبہ و استغفار کرے اور جس قدر ممکن ہو سکے نیک اعمال کا اہتمام کرے، مبادا یہ اس کا آخری وقت ہو۔"}],[106,"امام حسن رحمہ اللہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nبخار؛ موت کا راہنما ہے اور یہ زمین میں اللہ کا قیدخانہ ہے، وہ جب چاہتا ہے اپنے بندے کو (اس میں) بند کر دیتا ہے، پھر وہ جب چاہتا ہے اسے چھوڑ دیتا ہے۔ سو تم بخار کو پانی کے ساتھ ہلکا کر لیا کرو۔","مرسل",{"k":"شعب الإیمان للبیھقی (۱۲؍۲۸۴)، ضعیف الجامع الصغیر (۲۷۹۷)۔","f":"اللہ تعالیٰ جب دیکھتا ہے کہ اب بندہ اس کے قوانین کی خلاف ورزی کرنے لگ گیا ہے اور اس کی قائم کردہ حدود سے تجاوز کرنے لگا ہے تو پھر اسے سیدھی راہ پر لانے کے لیے اس قیدخانے میں ڈال دیتا ہے۔ یہی وجہ ہے کہ بندہ جب کسی بیماری میں مبتلا ہوتا ہے تو اللہ تعالیٰ کو بہت یاد کرنے لگتا ہے، اس سے تعلق جوڑ لیتا ہے اور اس سے اپنے گناہوں کی معافیاں مانگنے لگتا ہے۔ لہٰذا جب بندہ کچھ سبق حاصل کر لیتا ہے اور راہِ راست پر آ جاتا ہے تو تب اللہ تعالیٰ اسے رہائی دے دیتا ہے۔"}],[107,"سیدنا ابن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ:\nمیں رسول اللہ  صلی اللہ علیہ وسلم  کے ساتھ بیٹھا ہوا تھا کہ آپ مسکرا پڑے۔ ہم نے عرض کیا: اے اللہ کے رسول! کون سی بات آپ کے مسکرانے کی وجہ بنی؟ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: بیماری کی وجہ سے مومن کے رونے دھونے پر تعجب ہوتا ہے، حالانکہ اگر اسے معلوم ہو جائے کہ اس بیماری پر اسے کس قدر اجر و ثواب ملے گا تو وہ اس بات کو پسند کرے گا کہ وہ مرتے دَم تک بیماری میں ہی مبتلا رہے۔ پھر آپ  صلی اللہ علیہ وسلم  دوسری مرتبہ مسکرائے اور اپنا سر مبارک آسمان کی طرف اُٹھایا۔ ہم عرض گذار ہوئے: اے اللہ کے رسول! اب آپ کس بات سے مسکرا دِیے؟ اور آپ نے اپنا سر مبارک بھی آسمان کی طرف اُٹھایا ہے (اس کی کیا وجہ ہے؟) تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: مجھے وہ دو فرشتے بہت بھلے لگے جو آسمان سے اُترے اور ایک مومن بندے کو اس کی نماز والی جگہ میں تلاش کرنے لگے جو جہاں وہ نماز پڑھا کرتا تھا، لیکن انہیں وہ نہیں ملا، چنانچہ وہ اللہ تعالیٰ کی طرف (آسمانوں میں) چڑھ گئے اور انہوں نے جا کر کہا: اے پروردگار! تیرا جو فلاں بندہ ہے، ہم اس کے شب و روز کے اتنے اتنے اعمال لکھا کرتے ہیں لیکن آج ہم نے اسے دیکھا کہ تو نے اسے (بیمار کر کے) اپنے جال میں بند کر دِیا ہے، لہٰذا ہم اس کا کوئی عمل لکھ نہ پائے۔ تو اللہ تعالیٰ فرماتا ہے: میرے بندے کے وہ اعمال لکھتے رہو جو وہ شب و روز میں کیا کرتا تھا اور اس کا کچھ بھی اجر کم نہ کرنا۔ جو میں نے اسے (بیماری کی وجہ سے) روک رکھا ہے؛ اس کا اجر دینا میرے ذِمے ہے اور جو وہ عمل کیا کرتا تھا؛ اس کے اجر کا بھی وہ حق دار ہے۔","ضعیف",{"k":"المعجم الأوسط للطبرانی (۲۳۱۷)، مسند الطیالسی (۳۴۷)، مسند البزار (۵؍۱۶۷)، شعب الإیمان للبیھقی (۷؍۱۸۵)، الترغیب والترھیب للمنذری (۴؍۱۴۷)، مجمع الزوائد للھیثمی (۲؍۳۰۴)، حلیۃ الأولیاء لأبی نعیم (۴؍۲۶۶)۔"}],[108,"سیدنا عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ:\nجب مومن بیمار ہوتا ہے تو اللہ تعالیٰ فرشتوں سے فرماتا ہے: میرے بندھن میں قید میرے اس بندے کے وہی اعمال لکھتے رہو جو یہ اپنی صحت کے ایام میں کیا کرتا تھا۔","رجالہ رجال الصحیح",{"k":"مسند أحمد (۲؍۱۵۹)، سنن الدارمی (۲۷۷۰)، المستدرک للحاکم (۱؍۴۹۹)، مجمع الزوائد للھیثمی (۲؍۳۰۳)۔"}],[109,"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nاہل دنیا میں سے جب کسی بندے کی آزمائش کی جاتی ہے تو اللہ تعالیٰ اس کی طرف دو فرشتوں کو بھیجتا ہے اور فرماتا ہے: میرے بندے کے پاس جاؤ، اگر وہ اچھی بات کہے اور عیادت کرنے والوں سے میرا کوئی شکوہ نہ کرے تو میں اسے اس کو ایسے گوشت میں بدل دوں گا جو اس کے گوشت سے بہتر ہو گا اور (اس کے جسم میں) ایسا خون (جاری کر) دوں گا جو اس کے خون سے بہتر ہو گا، پھر اگر میں نے اس کی جان قبض کر لی تو میں اس کے لیے جنت واجب کر دوں گا اور اگر اسے (بیماری کی) اس قید سے آزاد کر دِیا جس میں وہ بند تھا، تو اس کا عمل جاری رہے گا (یعنی وہ بیماری کی حالت میں عمل نہیں بھی کر رہا ہو تو اس کو عمل کا ثواب ملتا رہتا ہے)۔","ضعیف",{"k":"السنن الکبرٰی للبیھقی (۳؍۳۷۵)، المستدرک للحاکم (۱؍۵۰۰)۔"}],[110,"ابوعمران الجونی رحمہ اللہ فرماتے ہیں:\nجب مسلمان بندہ بیمار ہوتا ہے تو اللہ تعالیٰ بائیں جانب کے فرشتوں سے فرماتا ہے: میرے بندے کا کوئی گناہ مت لکھنا۔ اور دائیں جانب کے فرشتوں سے فرماتا ہے: یہ اپنی صحت کے عالم میں جو سب سے اچھا عمل کرتا تھا؛ اسی کے مثل عمل لکھتے رہو۔","رجالہ ثقات",{"k":"مسند أبی یعلی الموصلی (۶۶۳۸)، الترغیب والترھیب للمنذری (۴؍۱۴۷)، مجمع الزوائد للھیثمی (۲؍۳۰۴)۔"}],[111,"امام ابومجلز رحمہ اللہ فرمایا کرتے تھے:\nیقینا اللہ تعالیٰ بندے کو آزمائش میں مبتلا کیے رکھتا ہے، یہاں تک کہ اس کا کوئی گناہ باقی نہیں رہتا۔","لا بأس بہ",{"k":"مجمع الزوائد للھیثمی (۲؍۳۰۲)، المستدرک للحاکم (۱؍۳۴۸)، الترغیب والترھیب للمنذری (۴؍۲۹۷)۔"}],[112,"امام حسن رحمہ اللہ فرماتے ہیں:\nیقینا بندے کی مالی طور پر آزمائش کی جاتی ہے اور وہ صبر کرتا ہے، لیکن اس کے باعث وہ (جنت کے) بلند درجات تک نہیں پہنچ پاتا۔ اسی طرح اسے اس کی اولاد کے معاملے میں آزمایا جاتا ہے اور وہ صبر کا مظاہرہ کرتا ہے، لیکن اس کے باعث بھی وہ بلند درجات تک نہیں پہنچ پاتا۔ پھر اس کے بدن میں (کوئی بیماری لگا کر) اس کی آزمائش کی جاتی ہے اور وہ صبر سے کام لیتا ہے، تو اس کے ذریعے وہ (جنت کے) بلند و بالا درجات تک پہنچ جاتا ہے۔","فیہ من لم أعرفہ",{"k":"شعب الإیمان للبیھقی (۱۲؍۳۵۱)۔"}],[113,"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی  صلی اللہ علیہ وسلم  نے فرمایا:\nجس شخص کو ایک رات کا بخار ہو اور وہ صبر کا مظاہرہ کرے اور اللہ کے اس فیصلے پر راضی ہو، تو وہ گناہوں سے اس طرح نکل جاتا ہے جس طرح وہ اس روز (گناہوں سے پاک و صاف) تھا جس روز اس کی ماں نے اسے جنم دِیا تھا۔","ضعیف",{"k":"شعب الإیمان للبیھقی (۷؍۱۶۷)۔"}],[114,"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجو شخص کسی مریض کی عیادت کرنے آتا ہے تو وہ مسلسل رحمت میں داخل رہتا ہے، یہاں تک کہ وہ (مریض کے پاس آ کر) بیٹھ جائے، پس جب وہ بیٹھ جاتا ہے تو وہ رحمت میں غوطہ زن ہو جاتا ہے۔","حسن",{"k":"مسند أحمد (۳؍۳۰۴)، المستدرک للحاکم (۱؍۵۰۱)، الترغیب والترھیب للمنذری (۴؍۱۶۶)، مجمع الزوائد للھیثمی (۲؍۲۹۷)۔"}],[115,"سیدنا ابواُمامہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nمریض کی عیادت کرنے والا رحمت میں غوطہ زن رہتا ہے اور عیادت تب مکمل ہوتی ہے کہ آدمی اپنا ہاتھ مریض کی جانب بڑھائے۔","ضعیف",{"k":"مسند أحمد (۵؍۲۵۹)، سنن الترمذی (۲۷۳۱)، المعجم الکبیر للطبرانی (۸؍۲۱۱)۔"}],[116,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ  صلی اللہ علیہ وسلم  کو فرماتے سنا:\nیقینا مریض کی عیادت کے لیے جانے والا رحمت میں داخل رہتا ہے اور جب (مریض کے پاس جا کر) بیٹھ جاتا ہے تو رحمت میں غوطہ زن ہو جاتا ہے۔","ضعیف",{"k":"زوائد الھیثمی للحارث (۲۵۲)۔"}],[117,"سیدنا کعب بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجو شخص مریض کی عیادت کے لیے جاتا ہے وہ رحمت میں داخل ہو جاتا ہے اور جب وہ بیٹھ جاتا ہے تو پھر وہ رحمت میں ٹھہر ہی جاتا ہے۔","ضعیف",{"k":"مسند أحمد (۳؍۴۶۰)، المعجم الکبیر للطبرانی (۱۹؍۱۰۲)، الترغیب والترغیب للمنذری (۴؍۱۶۶)، مجمع الزوائد للھیثمی (۲؍۲۹۷)۔"}],[118,"امام ضحاک رحمہ اللہ فرماتے ہیں:\nاگر قرآن کی قراء ت نہ کرنی ہوتی تو میری یہ خواہش ہوتی کہ میں صاحبِ فراش رہتا (یعنی بیمار ہو کر بستر پر ہی پڑا رہتا) اس کی وجہ یہ ہے کہ مریض سے گناہ کو اُٹھا لیا جاتا ہے، اس کے نامۂ اعمال میں وہی اعمال لکھے جاتے ہیں جو وہ تندرستی میں کرتا تھا اور اس کی برائیوں کا کفارہ کر دِیا جاتا ہے۔","ضعیف",{"k":"مسند أبی یعلی الموصلی (۶۶۳۸)، الترغیب والترھیب للمنذری (۴؍۱۴۷)، مجمع الزوائد للھیثمی (۲؍۳۰۴)۔","f":"حضرتِ امام رحمہ اللہ نے قرآن کے ساتھ والہانہ عقیدت اور وارفتگی کے باعث ایسا فرمایا۔ انہیں قرآن کے ساتھ محبت اس قدر تھی کہ اگر انہیں قرأت چھوٹ جانے کا اندیشہ نہ ہوتا تو وہ صاحبِ فراش رہنا پسند فرماتے، اس لیے کہ بیمار شخص کے لیے اللہ تعالیٰ نے بہت سے انعامات و عنایات رکھ چھوڑی ہیں۔"}],[119,"ابوالملیح بیان کرتے ہیں کہ:\nصالح بن مسمار رحمہ اللہ ایک مریض کی عیادت کے لیے گئے اور میں بھی ان کے ہمراہ تھا، جب آپ اس کے پاس سے اُٹھے تو فرمایا: یقینا تمہارے پروردگار نے تم سے تعلق کی بناء پر ناگواری کا اظہار کیا ہے، لہٰذا تم بھی اب اس کے ساتھ تعلق جوڑ لو۔","حسن",{"k":"تاریخ بغداد للخطیب (۱۴؍۲۱)۔"}],[120,"یحییٰ بن ابی کثیر رحمہ اللہ بیان کرتے ہیں کہ:\nرسول اللہ  صلی اللہ علیہ وسلم  نے سیدنا سلمان رضی اللہ عنہ کو غیرحاضر پایا تو ان کے بارے میں پوچھا، آپ کو بتلایا گیا کہ وہ بیمار ہیں۔ چنانچہ آپ  صلی اللہ علیہ وسلم  ان کی عیادت کے لیے تشریف لائے، پھر فرمایا: اللہ تعالیٰ تمہارے اجر کو بڑا کرے اور تمہیں تاحیات تمہارے دِین اور جسم کے معاملے میں عافیت سے نوازے۔ یقینا تمہیں اس تکلیف کی برکت سے تین فضیلتیں حاصل ہوئی ہیں: ایک تو یہ ہے کہ تمہارے پروردگار کی طرف سے یاددہانی ہے کہ تم اس تکلیف کی وجہ سے اسے یاد کر سکے۔ دوسری یہ ہے کہ یہ بیماری تمہارے گزشتہ گناہوں کے خاتمے کا باعث ہے اور تیسری یہ ہے تم جو چاہو دعا کرو، کیونکہ بلاشبہ (مصیبت یا تکلیف میں) مبتلا شخص کی دعا قبول ہوتی ہے۔","منقطع",{"k":"تاریخ دمشق لابن عساکر (۲۱؍۴۱۷)۔"}],[121,"امام وھب بن منبہ رحمہ اللہ فرماتے ہیں:\nآدمی تب تک کامل فقیہ نہیں ہو سکتا جب تک کہ وہ آزمائش کو نعمت نہ سمجھے اور خوش حالی کو مصیبت نہ سمجھے، اس لیے کہ آزمائش میں مبتلا شخص خوش حالی کا انتظار کرتا ہے اور خوش حالی والا شخص آزمائش کا انتظار کرتا ہے۔","ضعیف",{"k":"حلیۃ الأولیاء لأبی نعیم (۴؍۵۶)، الزھد لأحمد بن حنبل، ص: ۳۷۳۔"}],[122,"امام کردوس ثعلبی رحمہ اللہ فرماتے ہیں:\nمیں نے انجیل میں دیکھا تو وہاں یہ بات پڑھی کہ یقینا اللہ تعالیٰ بندے کو ایسے معاملے سے دوچار کر دیتا ہے جسے وہ ناپسند کرتا ہے (یعنی کوئی مرض، تکلیف یا پریشانی وغیرہ) جبکہ اللہ تعالیٰ اسے پسند کرتا ہے، تاکہ وہ دیکھے کہ بندہ اس کے سامنے کیسے گڑگڑاتا ہے۔","حسن لغیرہ",{"k":"شعب الإیمان للبیھقی (۱۲؍۳۶۸)۔"}],[123,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\nمیں نے عرض کیا: اے اللہ کے رسول! یقینا میں خوب جانتی ہوں کہ قرآنِ کریم میں کون سی آیت سب سے سخت ہے۔ آپ  صلی اللہ علیہ وسلم  نے استفسار فرمایا: اے عائشہ! کون سی آیت ہے؟ میں نے عرض کیا: اے اللہ کے رسول! وہ یہ آیت ہے: ﴿مَنْ یَعْمَلْ سُوءً ا یُجْزَ بِہٖ﴾ ‘‘جو شخص برائی کرے گا؛ اسے اس کا بدلہ دِیا جائے گا۔’’ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: بندۂ مومن کو جو کوئی مصیبت آتی ہے، یہاں تک کہ اگر کانٹا بھی چھبتا ہے، تو یہ بدلہ ہی ہے۔","لا بأس بہ",{"k":"مسند أحمد (۶؍۲۱۸)، مسند أبی داود الطیالسی (۱۵۸۴)، سنن الترمذی (۲۹۹۱)۔"}],[124,"اُمیہ بیان کرتی ہیں کہ:\nانہوں نے سیدہ عائشہ رضی اللہ عنہا سے اس آیت کے متعلق: ﴿إِنْ تُبْدُوا مَا فِی أَنْفُسِکُمْ أَوْ تُخْفُوہُ﴾ ‘‘اگر تم اس چیز کو ظاہر کر دو جو تمہارے دِلوں میں ہے، یا اسے چھپائے رکھو (اللہ تعالیٰ تم سے اس کا حساب لے گا)۔’’ اور اس آیت: ﴿مَنْ یَعْمَلْ سُوءً ا یُجْزَ بِہٖ﴾ ‘‘جو شخص کوئی برا عمل کرے گا؛ اسے اس کا بدلہ دِیا جائے گا۔’’کے بارے میں سوال کیا تو سیدہ عائشہ رضی اللہ عنہا نے فرمایا:جب سے میں نے رسول اللہ  صلی اللہ علیہ وسلم  سے (اس کے بارے میں) سوال کیا تب سے کسی نے مجھ سے نہیں پوچھا۔ رسول اللہ  صلی اللہ علیہ وسلم  نے مجھ سے فرمایا تھا: اے عائشہ! اس سے مراد اللہ تعالیٰ کی طرف سے آنے والی وہ پے در پے مصیبتیں ہیں جو وہ اپنے بندے پر مسلط کرتا ہے، مثلاً بخار ہو جانا، کوئی تکلیف پہنچنا، یا کانٹا چبھنا، یہاں تک کہ وہ سامان جو آدمی اپنی آستین میں رکھے اور گم کر بیٹھے، پھر گھبرا کر تلاش کرے تو اسے اپنے پہلو میں ہی مل جائے (یعنی اس قدر چھوٹی پریشانی بھی)، پھر ایسا ہوتا ہے کہ مومن اپنے گناہوں سے اس طرح نکل جاتا ہے جس طرح آگ کی بھٹی سے سرخ سونے کی ڈَلی نکل آتی ہے۔","ضعیف",{"k":"مسند أحمد (۶؍۲۱۸)، مسند أبی داود الطیالسی (۱۵۸۴)، سنن الترمذی (۲۹۹۱)۔"}],[125,"زیاد بن ربیع رحمہ اللہ بیان کرتے ہیں کہ:\nمیں نے سیدنا اُبی بن کعب رضی اللہ عنہ سے کہا: کتاب اللہ میں ایک آیت ہے جو مجھے غمگین کر دیتی ہے۔ انہوں نے پوچھا: کون سی آیت؟ میں نے کہا: ﴿مَنْ یَعْمَلْ سُوءً ا یُجْزَ بِہٖ﴾ ‘‘جو شخص کوئی برا عمل کرے گا؛ اسے اس کا بدلہ دِیا جائے گا۔’’ میں تو آپ کو بڑا فقیہ سمجھتا تھا، میری رائے کے مطابق اس کی تفسیر یہ ہے کہ مومن کو قدم پھسل جانے یا رَگ پھڑکنے جیسی کوئی بھی مصیبت آتی ہے تو وہ گناہوں کی وجہ سے ہی آتی ہے جبکہ اللہ تعالیٰ بندے کے جن گناہوں کو معاف فرماتا ہے وہ کہیں زیادہ ہیں۔","حسن",{"k":"الزھد لھناد (۱؍۲۴۹)، الدر المنثور للسیوطی (۲؍۶۹۸)، تفسیر ابن جریر الطبری (۵؍۲۹۲)۔"}],[126,"ربیع بن زیاد بیان کرتے ہیں کہ:\nمیں سیدنا اُبی رضی اللہ عنہ سے ملا اور ان سے عرض کیا: میں نے کتاب اللہ کی یہ آیت پڑھی تو اس نے مجھے غمگین کر دِیا: ﴿مَنْ یَعْمَلْ سُوءً ا یُجْزَ بِہٖ﴾ ‘‘جو شخص کوئی برا عمل کرے گا؛ اسے اس کا بدلہ دِیا جائے گا۔’’ میں تو تمہیں بڑا فقیہ سمجھتا تھا، میری رائے کے مطابق اس کی تفسیر یہ ہے کہ مومن کو کوئی خوف آنے، یا چیونٹی کے کاٹنے، یا رَگ پھڑکنے جیسی کوئی بھی مصیبت آتی ہے تو وہ گناہوں کی وجہ سے ہی آتی ہے جبکہ اللہ تعالیٰ بندے کے جن گناہوں کو معاف فرماتا ہے وہ کہیں زیادہ ہیں۔","رجالہ ثقات",{"k":"الدر المنثور للسیوطی (۲؍۶۹۸)، تفسیر الطبری (۵؍۲۹۲)۔"}],[127,"قیس بن عباد رحمہ اللہ فرماتے ہیں:\nتکلیف کے لمحات خطاؤں کے لمحات کو ختم کر دیتی ہیں۔","حسن",{"k":"الزھد لھناد (۱؍۲۴۲)۔","f":"یعنی جن اوقات و لمحات میں انسان پر تکلیف، پریشانی، مصیبت یا کوئی بیماری آتی ہے، ان کے بدلے میں اللہ تعالیٰ ان اوقات و لمحات کو معاف فرما دیتا ہے جن میں اس سے گناہ سرزد ہوئے ہوتے ہیں۔"}],[128,"عمرو بن شرید بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجو بھی مومن بیمار ہوتا ہے، یہاں تک کہ وہ بیماری اسے کمزور کر دے، تو اس کی بخشش فرما دی جاتی ہے۔","مرسل",{"k":"مسند الفردوس للدیلمی (۴؍۲۷)۔"}],[129,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nمومن کی کوئی رَگ بھی پھڑکتی ہے تو اللہ تعالیٰ اس کے بدلے بھی اس کے لیے اس نیکی لکھ دیتا ہے، اس کی ایک برائی کم کر دیتا ہے اور اس کا ایک گناہ مٹا دیتا ہے۔","حسن",{"k":"المعجم الأوسط للطبرانی (۲۴۶۰)، المستدرک للحاکم (۱؍۴۹۸)، الترغیب والترھیب للمنذری (۴؍۱۴۶)، مجمع الزوائد للھیثمی (۲؍۳۰۴)۔"}],[130,"سیدنا ابوبکر صدیق رضی اللہ عنہ فرماتے ہیں:\nاللہ تعالیٰ (ہر قسم کی تکلیف اور پریشانی کے بدلے میں) مسلمان کے گناہوں کا کافرہ فرماتا رہتا ہے، یہاں تک کہ یہاں تک کہ کوئی تکلیف ہو جانا، اس کے جوتے کا تسمہ ٹوٹ جانا، اور اس سامان کا گم ہو جانا جسے آدمی نے اپنی آستین میں رکھا ہو، پھر گھبرا کر تلاش کرے تو اسے اپنے پہلو میں ہی مل جائے۔","رجالہ ثقات",{"k":"الزھد لأحمد بن حنبل: ص ۱۳۶، الدر المنثور للسیوطی (۲؍۷۰۰)، المعجم الأوسط للطبرانی (۱؍۵۳۴)۔"}],[131,"عبداللہ بن عبید بن عمیر بیان کرتے ہیں کہ:\nایک آدمی نے سیدہ عائشہ رضی اللہ عنہا سے کہا: مجھے پتا چلا ہے کہ آپ فرماتی ہیں: جب مسلمان بیمار ہوتا ہے تو اس کے لیے وہ عمل لکھا جاتا ہے جو اس نے اپنی بیماری کے آخری ایام میں کیا۔ تو انہوں نے فرمایا: اس طرح نہیں ہے، بلکہ میں نے تو یہ کہا ہے کہ اس کی بیماری کے آخری لمحے تک اس کے نامہ اعمال میں اس کا بہترین عمل لکھا جاتا ہے۔","رجالہ ثقات",{"k":"مسند أبی یعلی الموصلی (۶۶۳۸)، الترغیب والترھیب للمنذری (۴؍۱۴۷)، مجمع الزوائد للھیثمی (۲؍۳۰۴)۔"}],[132,"محمد بن افلح رحمہ اللہ بیان کرتے ہیں کہ:\nسیدنا ابوہریرہ رضی اللہ عنہ کا گھر ذوالحلیفہ میں تھا۔ جب جمعے کا دِن آتا تھا تو وہ آ کر مدینہ میں ایک بڑھیا کے ہاں غسل کرتے اور جمعے کی تیاری کرتے، اور (اس بڑھیا سے) پوچھا کرتے:اے اُمِ فلاں! آپ کا کیا حال ہے؟ ایک بار اس نے کہا: اللہ کی قسم! میں خود کو بہت تکلیف میں پاتی ہوں۔ تو سیدنا ابوہریرہ رضی اللہ عنہ نے فرمایا: کیا میں تمہیں اس کے مثل کا نہ بتلاؤں؟ اس نے پوچھا: اس کا مثل کیا ہے؟ تو آپ نے فرمایا: کیا آپ نے دیکھا نہیں کہ جب موسمِ بہار آتا ہے تو کس طرح اس موسم میں شگفتہ و تروتازہ اور سرسبز و شاداب ہو جاتے ہیں، لیکن جب خزاں کا موسم آتا ہے تو ہوائیں چلتی ہیں اور کس طرح موسم خشک ہو جاتا ہے اور پتے جھڑنے لگتے ہیں۔ تو اس عورت نے کہا: کیوں نہیں (بالکل ایسے ہی ہوتا ہے) تو آپ نے فرمایا: اسی طرح تکالیف بھی گناہوں کا جھاڑ دیتی ہیں۔","حسن",{"k":"تفرّد بہ المؤلف۔"}],[133,"عبید بن عمیر رحمہ اللہ بیان کرتے ہیں کہ:\nنبی  صلی اللہ علیہ وسلم  نے ایک مریض کی عیادت کی اور فرمایا: جسم میں جو بھی رَگ ہوتی ہے انسان جب اس سے کوئی تکلیف محسوس کرتا ہے تو اس کے پروردگار کی طرف سے اس کے پاس ایک آنے والا آتا ہے (یعنی فرشتہ) اور وہ اسے خوشخبری دیتا ہے کہ اس (تکلیف) کے بعد اس پر (آخرت کا) عذاب نہیں ہو گا۔ اور نبی  صلی اللہ علیہ وسلم  اپنے صحابہ کرام رضی اللہ عنہم میں سے ایک آدمی کے پاس تشریف لائے، جو کہ بیمار تھے، تو آپ  صلی اللہ علیہ وسلم  نے پوچھا: کیسی طبیعت ہے تمہاری؟ تو انہوں نے کہا: میں (رحمتِ خداوندی کی) اُمید بھی لگائے ہوئے ہوں اور (عذابِ الٰہی سے) ڈر بھی رہا ہوں۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! اس حالت کے اندر جس شخص میں یہ دونوں خصلتیں جمع ہو جائیں؛ تو اللہ تعالیٰ اسے وہ (انعامات و درجات) عطا فرما دیتا ہے جس کی اس نے اُمید لگائی ہوتی ہے اور اسے اس (عذاب) سے محفوظ کر لیتا ہے جس سے وہ ڈر رہا ہوتا ہے۔","رجالہ ثقات",{"k":"شعب الإیمان للبیھقی (۲؍۵)۔"}],[134,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nیقینا بخار جہنم کی بھاپ کے اثر سے ہوتا ہے، لہٰذا تم اسے پانی سے ٹھنڈا کر لیا کرو۔\nسیدنا ابن عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nیقینا بخار جہنم کی بھاپ کے اثر سے ہوتا ہے، لہٰذا تم اسے پانی سے ٹھنڈا کر لیا کرو۔\nسیدنا رافع بن خدیج رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ  صلی اللہ علیہ وسلم  کو فرماتے سنا:\nبخار جہنم کی بھاپ کے اَثر سے ہوتا ہے، لہٰذا اسے پانی کے ساتھ ٹھنڈا کر دیا کرو۔\nسیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nبخار جہنم کے بھاپ کے اَثر سے ہوتا ہے، لہٰذا اسے پانی کے ساتھ بجھا دیا کرو۔\nسیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nیقینا بخار جہنم کی بھاپ کے اَثر سے ہوتا ہے، لہٰذا تم اسے پانی کے ساتھ بجھا دیا کرو۔","حسن",{"k":"صحیح بخاری (۳۲۶۳)، صحیح مسلم (۲۲۱۰)۔\nصحیح مسلم (۲۲۰۹)۔\nصحیح بخاری (۳۲۶۲)، صحیح مسلم (۲۲۱۲)۔\nصحیح بخاری (۵۳۹۱)۔\nصحیح بخاری (۳۲۶۳)، صحیح مسلم (۲۲۱۰)۔"}],[135,"سیدنا ابن عمر رضی اللہ عنہما بیان کرتے ہیں کہ میں نے رسول اللہ  صلی اللہ علیہ وسلم  کو بخار کا تذکرہ کرتے ہوئے فرماتے سنا:\nجب تم کچھ بخار محسوس کرو تو اسے پانی کے ساتھ ٹھنڈا کر لیا کرو، کیونکہ یہ جہنم (کی تپش) میں سے ہی کچھ ہوتا ہے۔","",{"k":"صحیح مسلم (۱۷۳۲)۔"}],[136,"فاطمہ بنت منذر بیان کرتی ہیں کہ:\nجب کسی عورت کو بخار ہو جاتا تو سیدہ اسماء بنت ابی بکر رضی اللہ عنہما پانی منگوا کر اس کے گریبان میں ڈالتیں اور فرماتیں: یقینا رسول اللہ  صلی اللہ علیہ وسلم  نے ہمیں حکم فرمایا کہ ہم اسے پانی کے ساتھ ٹھنڈا کریں۔","",{"k":"صحیح بخاری (۵۷۲۴)۔"}],[137,"ابوجمرہ رحمہ اللہ بیان کرتے ہیں کہ:\nسیدنا ابن عباس رضی اللہ عنہما نے مجھے (حاضر ہونے کا) مراسلہ لکھا، تو میں کچھ دِن ان کی خدمت میں حاضر نہ ہو سکا، تو انہوں نے پوچھا: تمہیں کس کام نے روک لیا تھا؟ میں نے عرض کیا: بخار ہو گیا تھا۔ تو انہوں نے کہا: رسول اللہ  صلی اللہ علیہ وسلم  کا فرمان ہے کہ بخار جہنم کی بھاپ کے اَثر سے ہوتا ہے، لہٰذا اسے آبِ زم زم کے ساتھ ٹھنڈا کر لیا کرو۔","",{"k":"صحیح بخاری (۳۲۶۱)۔"}],[138,"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nبخار جہنم کی ایک دھونکنی ہے، اسے ٹھنڈے پانی کے ذریعے خود سے دُور کر دِیا کرو۔","",{"k":"سنن ابن ماجہ (۳۴۷۵)۔"}],[139,"سیدنا ثوبان رضی اللہ عنہ بیان کرتے ہیں کہ نبی  صلی اللہ علیہ وسلم  نے فرمایا:\nجب تم میں سے کسی کو بخار ہو جائے ۔۔۔ اور یقینا بخار (جہنم کی) آگ کا ایک ٹکڑا ہے۔۔۔ تو اسے چاہیے کہ وہ اسے پانی کے ساتھ ختم کر دے۔ وہ بہتی ہوئی نہر پر جائے اور جس جانب پانی کا بہاؤ ہو اس طرف منہ کر لے اور یہ کلمات پڑھے:\nبِسْمِ اللّٰہِ اَللّٰہُمَّ اشْفِ عَبْدَکَ وَصَدِّقْ رَسُولُکَ\n‘‘اللہ کے نام کے ساتھ، اے اللہ! اپنے بندے کو شفا عطا فرما اور اپنے رسول  صلی اللہ علیہ وسلم  (کی بات) کو سچ کر دِکھا۔’’\nیہ کام نمازِ فجر کے بعد سورج طلوع ہونے سے پہلے پہلے کرے اور نہر کے پانی میں تین بار ڈُبکی لگائے۔ تین دِن تک یہ کام کرے، لیکن اگر افاقہ نہ ہو پانچ دِن کرے، اور اگر پانچ دِنوں میں بھی صحت یابی نہ ہو تو سات دِن تک یہ کام کرے۔ یقینا اللہ تعالیٰ کے حکم کے ساتھ سات دِن سے زیادہ اسے کرنا نہیں پڑے گا (یعنی تب تک ضرور صحت یاب ہو جائے گا)۔","ضعیف",{"k":"مسند أحمد (۵؍۲۸۱)، سنن الترمذی (۲۰۸۴)، المعجم الکبیر للطبرانی (۲؍۱۰۲)۔"}],[140,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\nرسول اللہ  صلی اللہ علیہ وسلم  کے اہلِ خانہ میں سے جب کسی کو بخار ہو جاتا تو آپ  صلی اللہ علیہ وسلم  ‘‘حساء’’ تیار کرنے کا حکم دیتے۔ جب وہ تیار ہو جاتا تو آپ  صلی اللہ علیہ وسلم  انہیں حکم فرماتے کہ اس میں سے کچھ مَل لو، اور فرماتے: اس سے غمزدہ انسان کے دِل کو سہارا ملتا ہے اور بیمار کے دِل سے رنج کو اس طرح دُور کر دیتا ہے جس طرح تم میں سے کوئی عورت پانی کے ساتھ اپنے چہرے سے میل کچیل کو دُور کر دیتی ہے۔","حسن",{"k":"مسند أحمد (۶؍۳۲)، سنن الترمذی (۲۰۳۹)، سنن ابن ماجہ (۳۴۴۵)، السنن الکبرٰی للنسائی (۷۵۷۳)، المستدرک للحاکم (۴؍۱۳۱)۔","f":"‘‘حساء’’ عرب کا ایک کھانا ہوتا تھا، جو آٹے، پانی اور روغن سے تیار کیا جاتا تھا، اس میں کبھی شیرینی ملائی جاتی تھی اور کبھی اس میں شہد ڈال لیا جاتا تھا۔ ہمارے ہاں اسے ‘‘ہریرہ’’ کہا جاتا ہے۔"}],[141,"سیدنا ابوموسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجب بندہ بیمار ہو جاتا ہے، یا سفر میں ہوتا ہے، تو اللہ تعالیٰ اس کے لیے اتنا ہی اجر و ثواب لکھ دیتا ہے جتنے وہ بہ حالتِ اقامت اور تندرستی میں عمل کرتا ہے۔","",{"k":"صحیح بخاری (۲۹۹۶)۔"}],[142,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nمومن کو جب بھی کوئی کانٹا چبھتا ہے، یا اس سے بھی ہلکی کوئی تکلیف پہنچتی ہے، تو اللہ تعالیٰ اس کے بدلے میں اس کا ایک درجہ بلند فرما دیتا ہے اور ایک گناہ معاف کر دیتا ہے۔","",{"k":"صحیح مسلم (۲۵۷۲)۔"}],[143,"جابر بن زید رحمہ اللہ فرماتے ہیں:\nموت کا فرشتہ لوگوں کو جہاں بھی ملتا بغیر کسی مرض کے ہی انہیں فوت کر دیتا۔ لوگ اسے برا بھلا کہنے لگے تو اس نے اللہ تعالیٰ سے اس بات کی شکایت کی جو لوگ اسے بددعائیں دیتے تھے۔ تو اس سے کہا گیا: اے ملک الموت! واپس جاؤ (اب کوئی تمہیں ایسا نہیں کہے گا) پھر اللہ تعالیٰ نے بیماریاں اُتاریں (جن میں مبتلا ہو کر لوگ مرنے لگے) تو سب لوگ ملک الموت کو بھول گئے اور اب جب بھی کوئی مرتا ہے تو یہی کہا جاتا ہے کہ فلاں فلاں بیماری کی وجہ سے مر گیا۔","رجالہ ثقات",{"k":"تاریخ بغداد للخطیب (۱۴؍۲۷۶)۔"}],[144,"سعید التیمی رحمہ اللہ بیان کرتے ہیں کہ:\nربیع بن خثیم کے بھائی ان کے پاس آئے، ربیع رحمہ اللہ کو فالج ہو گیا تھا اور ان کا لعاب ان کے منہ سے بہتا رہتا تھا، میں لعاب کو صاف کرنے لگا اور کہنے لگا: آپ کے اہلِ خانہ نے آپ کی قدر نہیں کی۔ تو انہوں نے فرمایا: مجھے یہ بات اچھی نہیں لگتی کہ یہ تکلیف جو میرے ساتھ ہے اس کو دُور کرنا اللہ پر مشکل ہو۔","حسن",{"k":"شعب الإیمان للبیھقی (۱۲؍۳۴۹)، الزھد لھناد (۱؍۲۳۱)، حلیۃ الأولیاء لأبی نعیم (۲؍۱۱۵)، سیر أعلام النبلاء للذھبی (۴؍۲۶۰)۔"}],[145,"ہشام بن عروہ اپنے والد کے حوالے سے روایت کرتے ہیں کہ:\nوہ ولید بن عبدالملک کی جانب روانہ ہوئے۔ ابھی وہ وادئ قرٰی میں ہی پہنچے تھے کہ انہوں نے اپنے پاؤں میں کچھ محسوس کیا۔ دیکھا تو پھوڑا نکل آیا تھا۔ انہوں نے ابھی سفر کی کئی منازل طے کرنا تھی۔ چنانچہ (آپ کے ہم سفر) لوگوں نے ارادہ کیا کہ آپ کو اونٹ پر رکھے ہوئے پالکی نما کجاوے میں بٹھا دیں۔ آپ نے انکار کیا لیکن انہوں نے زبردستی کی اور آپ کے لیے ایک کجاوے والی اونٹنی لے آئے، چنانچہ آپ اس پر سوار ہو گئے۔ اس سے پہلے آپ کبھی اس پر سوار نہیں ہوئے تھے۔ جب صبح ہوئی تو آپ نے یہ آیت پڑھی: ﴿مَا یَفْتَحِ اللّٰہُ لِلنَّاسِ مِنْ رَحْمَۃٍ فَلَا مُمْسِکَ لَہَا﴾ ‘‘اللہ تعالیٰ لوگوں کے لیے جو رحمت کھولتا ہے، اسے کوئی روک نہیں سکتا۔’’ یہاں تک کہ جب اس سے فارغ ہوئے تو فرمایا: اللہ تعالیٰ نے اس اُمت کو کس قدر نعمتوں سے نوازا ہے۔ ان کجاووں کی صورت میں بھی ایک نعمت ہے۔ لیکن لوگ ان نعمتوں کا شکر ہی ادا نہیں کرتے۔ اتنے میں آپ کے پاؤں کی تکلیف بڑھ گئی۔ یہاں تک کہ جب آپ ولید کے پاس پہنچے تو انہوں نے کہا: اے ابوعبداللہ!اسے کاٹ دیجیے، کیونکہ مجھے خدشہ ہے کہ یہ اس سے آگے تک بڑھ جائے گا۔ آپ نے کہا: ٹھیک ہے جو تمہیں بہتر لگے۔ چنانچہ انہوں نے آپ کے لیے ایک طبیب بلایا جس نے آپ سے کہا: کوئی نشہ آور مشروب پی لیجیے۔ آپ نے کہا: میں تو کبھی کوئی نشہ آور مشروب نہیں پیوں گا۔ چنانچہ طبیب نے ان کا عذر قبول کیا۔ پھر اس نے آری پکڑی اور اسے آگ پر گرم کیا۔ عروہ رحمہ اللہ اس کے سامنے ٹیک لگا کر بیٹھ گئے، تو طبیب نے آدھی پنڈلی اور اس سے زائد حصہ کاٹ دِیا۔ عروہؒ صرف ‘‘حس، حس’’ کر رہے تھے (یعنی درد کی معمولی سی آواز نکال رہے تھے) یہ دیکھ کر ولید نے کہا:میں نے ان بزرگ سے زیادہ صبر والا کبھی کوئی آدمی نہیں دیکھا۔ اسی سفر میں عروہ رحمہ اللہ کا محمد نامی بیٹا بھی فوت ہوا تھا۔ وہ رات کے وقت جانوروں کے اصطبل میں پیشاب کرنے کے لیے گیا تو ایک خچر نے اسے ٹانگ مار کر قتل کر دیا۔ یہ عروہ رحمہ اللہ کا سب سے پیارا بیٹا تھا، لیکن عروہ رحمہ اللہ کی زبان سے اس بارے میں ایک بھی (آہ و بکاء کا) کلمہ نہیں سنا گیا۔ پھر جب وہ واپس آئے اور وادئ قرٰی میں پہنچے تو انہوں نے یہ آیت پڑھی: ﴿لَقِینَا مِنْ سَفَرِنَا ہٰذَا نَصَبًا﴾ ‘‘ہمیں تو اس سفر سے سخت تکلیف اُٹھانا پڑی۔’’ (پھر فرمایا:) اے اللہ! میرے سات بیٹے تھے، ان میں سے ایک تو نے لے لیا اور چھے باقی چھوڑ دِیے ہیں، میرے چار کنارے تھے (یعنی دو پاؤں اور دو ہاتھ) تو نے ایک کنارہ لے لیا اور تین باقی چھوڑ دِیے، تیری قسم! اگر تو نے آزمایا ہے تو عافیت بھی دی ہے اور اگر تو نے لیا ہے تو باقی بھی چھوڑا ہے۔ پھر جب وہ مدینہ پہنچے تو ان کی قوم میں سے عطاء بن ذویب نامی ایک صاحب ان کے پاس آئے اور کہا: اے ابوعبداللہ! اللہ کی قسم! ہم اس بات کے کبھی ضرورت مند نہیں رہے کہ ہم آپ کی وجہ سے کسی پر سبقت لے جائیں یا آپ کے ذریعے کسی کو ہرا دیں، بلکہ ہم صرف آپ کی علمی رائے کے اور آپ کی محبت کے محتاج رہے ہیں، سو جو مصیبت آپ پر آئی ہے اسے اللہ تعالیٰ نے آپ (کو روزِ قیامت اجر سے نوازنے) کے لیے ذخیرہ کر لیا ہے اور جس جس چیز کا ہم اپنے لیے باقی رہنا پسند کرتے ہیں (یعنی آپ کی ذات) تو وہ باقی بچ گئی ہے۔","إسنادہ لیس بالقوی",{"k":"حلیۃ الأولیاء لأبی نعیم (۹؍۱۷۹)، صفۃ الصفوۃ لابن الجوزی (۲؍۸۶)، الدر المنثور للسیوطی (۷؍۵)، سیر أعلام النبلاء للذھبی (۴؍۴۳۰)۔"}],[146,"نافع بن ذویب بیان کرتے ہیں کہ:\nعروہ بن زبیر رحمہ اللہ ولید بن عبدالملک کے پاس آئے تو ان کے پاؤں پر ایسا پھوڑا نکل آیا جو عضو کو کھا جانے والا تھا۔ چنانچہ ولید نے ان کی طرف اطباء بھیجے تو ان تمام کی آراء اس پر متفق ہوئیں کہ اگر ہم نے اسے کاٹا نہیں تو یہ انہیں مار ڈالے گا۔ عروہ رحمہ اللہ نے پوچھا: تم یہ کیسے کرو گے؟ انہوں نے کہا: ہم آپ کو ایک چیز پلائیں گے جس کے بعد ہم جو کچھ بھی کریں گے آپ کو چنداں محسوس نہیں ہو گا۔ عروہؒ نے کہا: تم ایسا نہیں کر سکتے۔ چنانچہ انہوں نے اسے آری کے ساتھ کاٹ دیا، لیکن آپ نے کسی ایک بھی عضو کو حرکت نہیں دی اور صبر کا مظاہرہ کیا۔ پھر جب انہوں نے طبیبوں کے ہاتھ میں (اپنا کٹا ہوا) پاؤں دیکھا تو اسے منگوا کر اپنے ہاتھ میں اُلٹ پلٹ کر دیکھا، پھر فرمایا: سن لے! اس ذات کی قسم جس نے مجھے تم پر اُٹھائے رکھا! یقینا وہ جانتا ہے کہ میں اس پاؤں کے ساتھ کبھی کسی حرام یا نافرمانی کے کام کی طرف چل کر نہیں گیا۔ عبداللہ بن نافع بن ذویب یا ان کے علاوہ اہل دمشق کے کوئی راوی اپنے والد کے حوالے سے روایت کرتے ہیں کہ جب عروہ رحمہ اللہ کے ساتھ یہ کیا گیا (یعنی ان کا پاؤں کاٹا گیا) تو وہ ان کے پاس حاضر ہوئے تو عروہ رحمہ اللہ نے یہ بات کہی، پھر پاؤں کے متعلق حکم فرمایا تو اسے اچھی طرح دھویا گیا، خوشبو لگائی گئی اور عمدہ پاپلین میں لپیٹ دِیا گیا، پھر آپ اسے (دفن کرنے کے لیے) مسلمانوں کے قبرستان میں لے گئے۔","",{"k":"صفۃ الصفوۃ لابن الجوزی (۲؍۸۷)، المعرفۃ والتاریخ للفسوی (۱؍۵۵۳)۔"}],[147,"ابوالمطرف مغیرہ بن مطرف بیان کرتے ہیں کہ:\nعروہ بن زبیر رحمہ اللہ ایک وفد کے ہمراہ ولید بن عبدالملک کے پاس آئے اور ان کے ساتھ ان کے پانچ بیٹے بھی تھے۔ حجاج نے ولید کو ایک خچر بھیجا تھا۔ ولید نے اس پر عروہ رحمہ اللہ کو سوار کیا تو اس خچر نے ان کے بڑے بیٹے محمد کو لات ماری، جس سے اس کی موت واقع ہو گئی۔ پھر ایسا ہوا کہ عروہ رحمہ اللہ کے پاؤں کی ایک اُنگلی پر پھوڑا نکل آیا۔ ان سے کہا گیا کہ اُنگلی کو کاٹ دیجیے۔ لیکن انہوں نے بات نہ مانی۔ پھر پورا پاؤں اس سے متاثر ہو گیا۔ انہیں کہا گیا کہ پاؤں کاٹ دیجیے لیکن انہوں نے پھر نہ بات مانی۔ اس کا اثر بڑھتے بڑھتے پنڈلی تک آ پہنچا۔ اب ان سے کہا گیا کہ اگر آپ نے پنڈلی کو نہ کاٹا تو یہ ران تک آ پہنچے گا اور ران کاٹنا ممکن بھی نہیں ہو گا۔ تو انہوں نے کہا: ٹھیک ہے اسے کاٹ دو۔ طبیبوں نے کہا: ہم آپ کو کچھ پلاتے ہیں، جس سے آپ کو ہوش نہیں رہے گی اور یوں آپ کاٹنے کی تکلیف محسوس نہیں کریں گے۔ تو انہوں نے فرمایا: اس کی ضرورت نہیں ہے، تم بس میری ٹانگ کا اتنا حصہ چھوڑ دینا کہ جس پر میں سجدہ کر سکوں۔ چنانچہ انہوں نے گھٹنے سے نیچے والی ہڈی تک چھوڑ دیا اور آری کے ساتھ متاثرہ حصے کو کاٹ دِیا، پھر خون روکنے کے لیے اس کو داغ دِیا۔ عروہ رحمہ اللہ نے (اس دوران) نہ تو کوئی بات کی اور نہ ہی آہ و بکاء کی۔ پھر جب وہ مدینہ تشریف لائے تو ان کے اہل خانہ اور دوست و احباب ملنے آئے تو وہ فرمانے لگے: ﴿لَقَدْ لَقِینَا مِنْ سَفَرِنَا ہٰذَا نَصَبًا﴾ ‘‘یقینا ہمیں تو اس سفر سے سخت تکلیف اُٹھانا پڑی۔’’ پھر فرمانے لگے: (اے اللہ!) اگر تو نے آزمائش کی ہے تو یقینا تو نے عافیت سے بھی نوازا ہے اور اگر تو نے لیا ہے تو باقی بھی چھوڑا ہے، تو نے میرا ایک بیٹا لیا ہے جبکہ چار کو باقی چھوڑا ہے اور تو نے ایک عضو لیا ہے جبکہ تین (یعنی دو ہاتھوں اور ایک پاؤں) کو باقی چھوڑا ہے۔","",{"k":"تاریخ بغداد للخطیب (۹؍۵۰)۔"}],[148,"ابوعروہ بیان کرتے ہیں کہ:\nطبیبوں نے عروہ رحمہ اللہ کی ٹانگ کاٹی، جب وہ ہڈی تک پہنچے تو انہوں نے ایک لمحے کے لیے اپنا سر تکیے پر رکھ لیا، پھر کچھ افاقہ ہوا تو ان کے چہرے پر پسینہ بہہ رہا تھا اور وہ فرما رہے تھے: (اے اللہ!) اگر تو نے آزمائش کی ہے تو عافیت سے بھی نوازا ہے اور اگر تو نے (میرا ایک بیٹا) لیا ہے تو (چار کو) باقی بھی چھوڑا ہے۔","",{}],[149,"امام زہری رحمہ اللہ بیان کرتے ہیں کہ:\nجب عروہ بن زبیر رحمہ اللہ کے پاؤں میں پھوڑا نکلا تو ان سے کہا گیا: کیا ہم آپ کے علاج کے لیے طبیب کو نہ بلا لائیں؟ تو انہوں نے فرمایا: چاہو تو بلا لاؤ۔ چنانچہ طبیب آیا اور اس نے کہا: ہم آپ کو ایک مشروب پلائیں گے جس سے آپ کو ہوش نہیں رہے گا۔ تو انہوں نے فرمایا: تم اپنا کام جاری رکھو، میں نہیں سمجھتا کہ جو شخص عقل زائل کر دینے والا مشروب پیے تو اسے رب تعالیٰ کی بھی پہچان رہے۔ چنانچہ اس نے آپ کے بائیں گھٹنے پر آری رکھی اور ہم بھی آپ کے اِرد گرد ہی تھے، تو ہم نے (آپ کے منہ سے) ‘‘حس’’ کی بھی آواز نہیں سنی (یعنی تکلیف کا ذرا سا بھی اظہار نہیں کیا)۔ جب طبیب نے ٹانگ کاٹ دی تو آپ فرمانے لگے: (اے اللہ!) اگر تو نے کچھ لیا ہے تو (بہت سا) باقی بھی تو چھوڑا ہے اور اگر تو نے آزمایا ہے تو عافیت بھی دی ہے۔ راوی بیان کرتے ہیں کہ آپ نے اس رات بھی قرآن کی تلاوت کا ناغہ نہیں کیا۔","رجالہ ثقات",{"k":"سیر أعلام النبلاء للذھبی (۴؍۴۳۰)۔"}],[150,"ابوالاسود رحمہ اللہ بیان کرتے ہیں کہ:\nعروہ رحمہ اللہ کے پاؤں میں پھوڑا نکل آیا، تو ولید نے ان کے پاس طبیب بھیجا، اس نے کہا: میرے خیال میں آپ کی ٹانگ کاٹنا پڑے گی ورنہ اس کا اثر سارے جسم میں سرایت کر جائے گا۔ تو عروہ رحمہ اللہ نے پوچھا: کیا تم (ایسے ہی ٹھیک کرنے میں) کامیاب ہو سکتے ہو؟ اس نے کہا: میرے خیال میں تو اسے کاٹنا ہی پڑے گا۔ چنانچہ عروہ رحمہ اللہ نے فرمایا: ٹھیک ہے کاٹ دو۔ تو طبیب تین چھوٹی آرِیاں لے آیا۔ پہلی کے ساتھ اس نے ہڈی کو کاٹا، پھر دوسری کے ساتھ ٹانگ کا کچھ حصہ کاٹا، پھر تیسری سے کاٹا، اور یوں مکمل ٹانگ کاٹ دی۔ عروہ رحمہ اللہ اس کے بعد کئی سال تک حیات رہے اور آپ تمام لوگوں سے زیادہ صبر والے تھے۔","رجالہ ثقات",{"k":"تفرّد بہ المؤلف۔"}],[151,"امام اوزاعی رحمہ اللہ بیان کرتے ہیں کہ:\nعروہ رحمہ اللہ کی ٹانگ کاٹ دی گئی تو انہوں نے اسے اپنے ہاتھ میں پکڑ کر فرمایا: اے اللہ! یقینا تو جانتا ہے کہ میں اس کو کبھی تیری نافرمانی کے کام کی طرف لے کر نہیں گیا۔","حسن",{"k":"صفۃ الصفوۃ لابن الجوزی (۲؍۸۷)، المعرفۃ والتاریخ للفسوی (۱؍۵۵۳)۔"}],[152,"ہشام بن عروہ رحمہ اللہ بیان کرتے ہیں کہ:\nایک آدمی عروہ بن زبیر رحمہ اللہ کے پاس آیا اور ان سے تعزیت کرنے لگا۔ آپ نے پوچھا: تم مجھ سے کس بات کی تعزیت کر رہے ہو؟ کیا میری ٹانگ گی؟ اس نے کہا: نہیں، بلکہ میں آپ کے بیٹے کی تعزیت کر رہا ہوں جسے جانور نے ٹانگ مار کر فوت کر دیا۔ تو عروہ رحمہ اللہ نے فرمایا: اگر تو نے آزمائش کی ہے تو عافیت سے بھی نوازا ہے اور اگر تو نے (میرا ایک بیٹا) لے لیا ہے تو (چار بیٹے) باقی بھی تو چھوڑے ہیں۔","صحیح",{"k":"سیر أعلام النبلاء للذھبی (۴؍۴۳۳)۔"}],[153,"ابوعروبہ زبیری بیان کرتے ہیں کہ:\nجس روز عروہ رحمہ اللہ کی ٹانگ کاٹی گئی اور ولید بن عبدالملک ان سے پوچھ رہے تھے کہ وہ کوئی چیز پی لیں جس سے ان کو ہوش نہ رہے (اور درد محسوس نہ ہو) تو انہوں نے فرمایا: میں کوئی چیز نہیں پی سکتا، تاکہ وہ میرے اور میرے پروردگار کے ذِکر کے درمیان حائل نہ ہو سکے۔ تو ولید نے ان سے کہا: اے ابوعبداللہ! کیوں نہیں، میرے ماں باپ آپ پر قربان ہو جائیں، اللہ کی قسم! میں نے آپ کے علاوہ کسی کے لیے انہیں کبھی جمع نہیں کیا۔ لیکن انہوں نے پھر بھی ان کی بات نہ مانی۔ چنانچہ (بغیر بے ہوش کیے ہی) آری کے ساتھ ان کی ٹانگ کاٹ دی گئی۔","",{}],[154,"ابومسکین اور ابوالمقوم بیان کرتے ہیں کہ:\nعروہ رحمہ اللہ سے کہا گیا: ہم آپ کو ایک دوا پلائیں گے اور ٹانگ کاٹ دیں گے، یوں آپ کو اس کی کوئی تکلیف محسوس نہیں ہو گی۔ تو انہوں نے فرمایا: اللہ کی قسم! مجھے اس بات سے چنداں خوشی نہیں ہو گی کہ یہ محفوظ طریقہ مجھے اس کے درد سے بچا لے گا۔","",{}],[155,"ہشام بن عروہ بیان کرتے ہیں کہ:\nعروہ رحمہ اللہ نے یہ آیت پڑھی: ﴿لَقَدْ لَقِینَا مِنْ سَفَرِنَا ہٰذَا نَصَبًا﴾ ‘‘یقینا ہمیں تو اس سفر سے سخت تکلیف اُٹھانا پڑی۔’’ اور فرمایا: اگر تو نے آزمائش کی ہے تو عافیت سے بھی نوازا ہے اور اگر تو نے (میرا ایک بیٹا) لے لیا ہے تو (چار بیٹے) باقی بھی تو چھوڑے ہیں۔","حسن",{"k":"صفۃ الصفوۃ لابن الجوزی (۲؍۸۷)، المعرفۃ والتاریخ للفسوی (۱؍۵۵۳)۔"}],[156,"ہشام اپنے والد (عروہ رحمہ اللہ) کے حوالے سے بیان کرتے ہیں کہ:\nجب ان کی ٹانگ کاٹ دی گئی تو انہوں نے فرمایا: اے اللہ! اگر تو نے آزمائش میں ڈالا ہے تو عافیت سے بھی نوازا ہے اور اگر تو نے کچھ لیا ہے تو باقی بھی چھوڑا ہے، تو نے صرف ایک (ٹانگ) لی ہے اور تین چیزیں (یعنی ایک ٹانگ اور دو بازو) باقی چھوڑ دیے ہیں۔","رجالہ ثقات",{"k":"تاریخ بغداد للخطیب (۴؍۱۱۲)۔"}],[157,"عبداللہ بن معاویہ زبیری بیان کرتے ہیں کہ:\nمیں نے ہشام بن عروہ سے سوال کیا: آپ کے والد گرامی جب وضوء کرتے تھے تو کٹی ہوئی ٹانگ پر کیا کرتے تھے؟ تو انہوں نے کہا: اس پر مسح کرتے تھے۔","ضعیف",{"k":"تفرّد بہ المؤلف۔"}],[158,"امام زہری رحمہ اللہ بیان کرتے ہیں کہ:\nجب عروہ بن زبیر رحمہ اللہ کی ٹانگ میں پھوڑا نکل آیا تو ولید نے ان کی طرف طبیب بھیجے، انہوں نے کہا: ہمیں یہ ٹانگ کاٹنا پڑے گی۔ چنانچہ اسے کاٹ دیا گیا۔ لیکن اس روز عروہ رحمہ اللہ کے چہرے پر تکلیف کے آثار تک نمایاں نہیں ہوئے۔","حسن",{"k":"حلیۃ الأولیاء لأبی نعیم (۲؍۱۷۹)، سیر أعلام النبلاء للذھبی (۴؍۴۲۹)۔"}],[159,"ابومعشر بیان کرتے ہیں کہ:\nجس وقت عروہ رحمہ اللہ کی ٹانگ کاٹی گئی تو ان سے کہا گیا: اگر ہم آپ کو کچھ پلا دیں تو آپ کو تکلیف نہیں محسوس ہو گی۔ تو انہوں نے فرمایا: اللہ تعالیٰ نے میری آزمائش اسی لیے کی ہے تاکہ وہ میرا صبر دیکھ سکے، کیا میں اس کے حکم سے منہ پھیر لوں؟","ضعیف",{"k":"تفرّد بہ المؤلف۔"}],[160,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ حضرت جبرائیل علیہ السلام نے رسول اللہ  صلی اللہ علیہ وسلم  کو دعا سکھلائی اور رسول اللہ  صلی اللہ علیہ وسلم  نے سیدنا ابوہریرہ رضی اللہ عنہ کو سکھلائی، جب وہ بیمار تھے۔ فرمایا: جب تو کسی بیماری میں مبتلا ہو جائے تو یہ دعا پڑھا کر:\n‘‘اللہ کے سوا کوئی معبود نہیں، وہ یکتا ہے، اس کا کوئی شریک نہیں، اسی کی بادشاہت ہے اور اسی کے لائق تمام تر تعریفات ہیں، وہی زندہ کرتا اور موت دیتا ہے، وہ ہمیشہ زندہ رہنے والی ذات ہے، اسے کبھی موت نہیں آئے گی۔ وہ ذات بہت پاک ہے جو بندوں کا پروردگار ہے اور بلاد کا رب ہے۔ تمام تعریفیں اللہ تعالیٰ ہی کو سزاوار ہیں، بہت زیادہ، پاکیزہ اور بابرکت، ہر حال میں۔ اللہ سب سے بڑا ہے۔ اللہ تعالیٰ کی شان و عظمت کا اقرار کرتے ہوئے، اس کی کبریائی اور قدرت و عظمت کو مانتے ہوئے، ہر حال میں۔ اے اللہ! اگر تو نے اس بیماری میں میری موت لکھی ہے تو مجھے بخش دے، مجھے گناہوں سے نکال لے اور مجھے جنتِ عدن میں جگہ عطا فرما دے۔’’","",{"k":"الترغیب فی الدعاء (۱۲۲)، العمدۃ من الفوائد والآثار الصحاح (۱؍۱۲۳)۔"}],[161,"امام حسن رحمہ اللہ نے درد اور تکلیف کا تذکرہ کرتے ہوئے فرمایا:\nسنو! اللہ کی قسم! مسلمان کے وہ ایام جو اس کے لیے خوشی کا باعث ہو سکتے ہیں وہ ایام ہیں جن میں اس کے لیے اللہ تعالیٰ کا قرب حاصل کرنے کا سامان ہو اور ان میں اسے اس چیز کی یاد دِلائی جاتی ہے جسے وہ اپنی آخرت کے سلسلے میں بھول چکا ہوتا ہے اور اس کے باعث اس کے گناہوں کا کفارہ کیا جاتا ہے۔","حسن",{"k":"شعب الإیمان للبیھقی (۱۲؍۳۵۱)۔"}],[162,"شبیب بن شیبہ بیان کرتے ہیں کہ میں نے امام حسن رحمہ اللہ کو فرماتے سنا:\nاسلاف رحمہم اللہ میں سے ایک صاحب تھے، جب کسی سال ان کو جانی یا مالی طور پر کوئی مصیبت نہ آتی تو وہ فرماتے: کیا بات ہے؟ کیا اللہ تعالیٰ ہم سے رُوٹھ گیا ہے؟","حسن",{"k":"السنن الکبرٰی للبیھقی (۳؍۳۸۳)، شرح السنۃ للبغوی (۵؍۲۲۳)۔"}],[163,"سیدنا علی بن ابی طالب رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ  صلی اللہ علیہ وسلم  کو فرماتے سنا:\nجس شخص نے رضائے الٰہی کی جستجو میں، اللہ کے وعدے کو پورا کرتے ہوئے اور اللہ کے ہاں موجود اجر و انعام کے حصول کا شوق رکھتے ہوئے کسی مریض کی عیادت کی تو اس پر ستر ہزار فرشتے مقرر کر دِیے جاتے ہیں جو اسے تب تک رحمت کی دعائیں دیتے رہتے ہیں جب تک کہ وہ اپنے گھر میں داخل نہیں ہو جاتا۔","ضعیف",{"k":"مسند أحمد (۱؍۱۳۸)، المعجم الأوسط للطبرانی (۳۲۴)۔"}],[164,"سیدنا ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\nنبی  صلی اللہ علیہ وسلم  ایک دیہاتی کی عیادت کے لیے اس کے پاس تشریف لے گئے اور فرمایا: گھبرانے کی بات نہیں ہے، اگر اللہ نے چاہا تو یہ بیماری (تمہارے گناہوں سے) پاکیزگی کا باعث بن جائے گی۔ تو اس دیہاتی نے کہا: آپ کہتے ہیں کہ یہ بیماری گناہوں سے پاکیزگی کا باعث بن جائے گی؟ ہرگز نہیں، بلکہ یہ تو ایک سخت بخار ہے جو بوڑھے کو اپنی سخت لپیٹ میں لیے ہوئے ہے اور اسے قبریں دِکھا کر چھوڑے گا۔ تو رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا: ہاں، اب ایسا ہی ہو گا۔","",{"k":"صحیح بخاری (۳۶۱۶)۔","f":"اس حدیث مبارکہ میں اوّلاً تو مریض کی عیادت کے وقت کی دعا تعلیم فرمائی گئی ہے۔ نبی  صلی اللہ علیہ وسلم  کی عادتِ مبارکہ تھی کہ جب بھی آپ کسی مریض کی عیادت کے لیے تشریف لے جاتے تو اسے یوں دعا دیتے: لَا بَأْسَ طَہُورٌ إِنْ شَاءَ اللّٰہُ لہٰذا مریض کی عیادت کے وقت اس سنت مبارکہ کا خاص طور پر اہتمام کرنا چاہیے۔\nثانیاً اس روایت سے یہ ثابت ہو رہا ہے کہ ناشکری کی زبان نہیں بولنی چاہیے۔ بلکہ سخت تکلیف میں بھی صبر کا مظاہرہ کرتے ہوئے اللہ کا شکر اور اس کے فیصلے پر رضامندی کا اظہار ہی کرنا چاہیے۔"}],[165,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\nرسول اللہ  صلی اللہ علیہ وسلم  جب مریض کے پاس تشریف لاتے تو اس کے لیے یوں دعا فرماتے:\nأَذْہِبِ الْبَأْسَ رَبَّ النَّاسِ، وَاشْفِ، أَنْتَ الشَّافِی لَا شِفَاءَ إِلَّا شِفَاؤُکَ شِفَاءً لَا یُغَادِرُ سَقَمًا.\n‘‘اے لوگوں کے پروردگار! تکلیف کو ختم کر دے اور شفا عطا فرما دے، تو ہی شفا دینے والا ہے، تیری شفا کے علاوہ کوئی شفا نہیں ہے، ایسی شفا عطا فرما کہ جو بیماری کا نام و نشان تک نہ چھوڑے۔’’","",{"k":"صحیح بخاری (۵۳۵۱)، صحیح مسلم (۲۱۹۱)۔"}],[166,"سیدنا علی رضی اللہ عنہ بیان کرتے ہیں کہ:\nنبی  صلی اللہ علیہ وسلم  جب کسی مریض کے پاس تشریف لاتے تو اپنا دایاں ہاتھ مبارک اس کے رُخسار پر رکھتے اور (یہ دعا) فرماتے:\nأَذْہِبِ الْبَأْسَ رَبَّ النَّاسِ وَاشْفِ أَنْتَ الشَّافِی شِفَاءً لَا یُغَادِرُ سَقَمًا.\n‘‘اے لوگوں کے پروردگار! تکلیف کو ختم کر دے اور شفا عطا فرما دے، تو ہی شفا دینے والا ہے، ایسی شفا دے کہ جو بیماری کا نام و نشان تک نہ چھوڑے۔","ضعیف",{"k":"مسند البزار (۳؍۸۰)، مسند عبد بن حمید (۶۶)۔"}],[167,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\nسیدہ فاطمہ رضی اللہ عنہا اپنے والد گرامی  صلی اللہ علیہ وسلم  کو یہ دَم کیا کرتی تھیں:\nبِسْمِ اللّٰہِ وَبِاللّٰہِ أَذْہِبِ الْبَأْسَ رَبَّ النَّاسِ وَاشْفِ أَنْتَ الشَّافِی لَا شِفَاءَ إِلَّا شِفَاؤُکَ شِفَاءً لَا یُغَادِرُ سَقَمًا یَا أَرْحَمَ الرَّاحِمِینَ.\n‘‘اللہ کے نام کے ساتھ اور اللہ کی توفیق کے ساتھ (میں دَم کرتی ہوں) اے لوگوں کے پروردگار! تکلیف کو ختم کر دے اور شفا عطا فرما دے، تو ہی شفا دینے والا ہے، تیری شفا کے علاوہ کوئی شفا نہیں ہے، ایسی شفا عطا فرما کہ جو بیماری کا نام و نشان تک نہ چھوڑے۔ اے ارحم الراحمین!’’\nسیدہ فاطمہ رضی اللہ عنہا (یہ کلمات پڑھ کر) پھونک مارا کرتی تھیں، تھوک نہیں لگاتی تھیں۔","ضعیف",{"k":"الکامل لابن عدی (۶؍۶۴)۔"}],[168,"سیدنا علی رضی اللہ عنہ بیان کرتے ہیں کہ:\nرسول اللہ  صلی اللہ علیہ وسلم  نے سیدنا سعد رضی اللہ عنہ کے بیمار ہونے پر ان کی عیادت کی، پھر ان کے لیے (یوں) دعا فرمائی:\nاَللّٰہُمَّ أَذْہِبْ عَنْہُ الْبَأْسَ رَبَّ النَّاسِ مَلِکَ النَّاسِ، أَنْتَ الشَّافِی لَا شَافِیَ إِلَّا أَنْتَ، أَرْقِیکَ مِنْ کُلِّ شَیْءٍ یَأْتِیکَ مِنْ کُلِّ حَسَدٍ أَوْ عَیْنٍ، اللّٰہُمَّ أَصْحِ قَلْبَہُ وَجِسْمَہُ، وَاشْفِ سَقَمَہُ، وَأَجِبْ دَعْوَتَہُ.\n‘‘اے اللہ! اس کی تکلیف کو ختم کر دے۔ اے لوگوں کے پروردگار! اے لوگوں کے مالک! تو ہی شفا دینے والا ہے، تیرے سوا کوئی شفا نہیں دے سکتا۔ (اے مریض!) میں تجھے حسد یا نظر بد جیسی ہر اس چیز سے دَم کرتا ہوں جو بھی تیرے پاس آئے۔ اے اللہ! اس کے قلب و جسم کو تندرست کر دے، اس کی بیماری کو شفا سے ختم کر دے اور اس کی دعا کو قبولیت سے نواز۔’’","حسن",{"k":"تاریخ بغداد للخطیب (۱۱؍۷۸)۔"}],[169,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ:\nرسول اللہ  صلی اللہ علیہ وسلم  ایک آدمی کی عیادت کی غرض سے اس کے پاس تشریف لائے تو وہ کراہنے کی سی آوازیں نکال رہا تھا، تو رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا: تم یہ دعا کیوں نہیں کرتے؟ رَبَّنَا آتِنَا فِی الدُّنْیَا حَسَنَۃً وَفِی الْآخِرَۃِ حَسَنَۃً وَقِنَا عَذَابَ النَّارِ ‘‘اے ہمارے پروردگار! ہمیں دنیا میں بھی اچھائی عطا فرما اور آخرت میں بھی اچھائی سے نواز، اور ہمیں آگ کے عذاب سے بچا۔’’","",{"k":"صحیح مسلم (۲۶۸۸)۔"}],[170,"سیدنا ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nآدمی جب کسی ایسے مریض کے پاس بیٹھے اور تین یا سات مرتبہ یہ پڑھے، تو اسے شفایاب کر دِیا جاتا ہے:\nأَسْأَلُ اللّٰہَ الْعَظِیمَ رَبَّ الْعَرْشِ الْعَظِیمِ أَنْ یَشْفِیَہٗ.\n‘‘میں اللہ تعالیٰ سے؛ کہ جو بڑی عظمت والا ہے اور عرشِ عظیم کا پروردگار ہے، سوال کرتا ہوں کہ وہ اسے شفا عطا فرما دے۔’’","صحیح",{"k":"مسند أحمد (۱؍۲۳۹)، سنن أبی داود (۳۱۰۶)، سنن الترمذی (۲۰۸۳)، الأدب المفرد للبخاری (۱۱؍۴۴۸)، مسند أبی یعلی الموصلی (۲۴۳۰)، صحیح ابن حبان (۲۹۷۵)، السنن الکبرٰی للنسائی (۱۰۸۸۲)، المستدرک للحاکم (۱؍۴۹۳)۔"}],[171,"سیدنا عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجب آدمی مریض کی عیادت کرنے آئے تو اسے یہ کلمات کہنے چاہئیں:\nاَللّٰہُمَّ اشْفِ عَبْدَکَ یَنْکَأُ لَکَ عَدُوًّا أَوْ یَمْشِی لَکَ إِلٰی صَلَاۃٍ.\n‘‘اے اللہ! اپنے بندے کو شفا سے نواز دے، تاکہ یہ تیرے دشمن کو موت کے گھاٹ اُتار سکے اور تیرے لیے نماز پڑھنے جا سکے۔’’","حسن",{"k":"مسند أحمد (۲؍۱۷۲)، سنن أبی داود (۳۱۰۷)، صحیح ابن حبان (۳۴۴)، المستدرک للحاکم (۱؍۴۹۵)۔"}],[172,"سیدنا سلمان رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے میری عیادت کی تو فرمایا:\n‘‘اللہ تعالیٰ تیری بیماری کو شفا دے، تیرے گناہ معاف فرمائے اور تیرے بدن و جسم میں تاحیات عافیت دے۔’’","ضعیف",{"k":"المعجم الکبیر للطبرانی (۶؍۲۴۰)، المستدرک للحاکم (۱؍۷۳۴)، تاریخ دمشق لابن عساکر (۲۱؍۴۱۷)، مجمع الزوائد للھیثمی (۲؍۲۹۹)۔"}],[173,"ابوزُبید رحمہ اللہ بیان کرتے ہیں کہ:\nمیں، نوف بکالی، بنوعامر کا ایک شخص اور ایک اور آدمی، سیدنا ابوایوب رضی اللہ عنہ کی عیادت کے لیے حاضر ہوئے اور ہم نے کہا: اے اللہ! انہیں عافیت سے نواز اور شفا عطا فرما۔ تو انہوں نے فرمایا: تم یوں کہو: اے اللہ! اگر تو ان کی موت کا وقت آ چکا ہے تو ان کی مغفرت فرما اور اس پر رحم فرما، اور اگر اس کا وقت نہیں آیا تو اسے عافیت سے نواز اور شفا عطا فرما۔","إسنادہ لا بأس بہ",{"k":"مسند أحمد (۳؍۱۴۸)، المصنف لابن أبی شیبۃ (۳؍۲۳۳)، شرح السنۃ للبغوی (۵؍۲۴۱)، مسند أبی یعلی الموصلی (۷؍۲۳۲)۔"}],[174,"سیدنا سعد رضی اللہ عنہ کی آزادکردہ لونڈی اُمِ طارق بیان کرتی ہیں کہ:\nمیں رسول اللہ  صلی اللہ علیہ وسلم  کے پاس بیٹھی ہوئی تھی کہ اسی دوران بخار آیا اور اس نے دروازے پر دستک دی۔ آپ  صلی اللہ علیہ وسلم  نے استفسار فرمایا: کون ہو؟ اس نے کہا: میں اُمِ ملدم (یعنی بخار) ہوں۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: ہم نہ تو تجھے خوش آمدید کہیں گے اور نہ ہی ہم تیرے اپنے ہیں۔","رجالہ ثقات",{"k":"مسند أحمد (۶؍۳۷۸)، المعجم الکبیر للطبرانی (۲۵؍۱۴۴)، مجمع الزوائد للھیثمی (۲؍۳۰۶)۔","f":"نبی  صلی اللہ علیہ وسلم  نے بخار کی آمد پر چنداں خوشی کا اظہار نہیں کیا۔ یہاں یہ بات ملحوظ رہے کہ تکلیف و مصیبت آنے پر صبر کا مظاہرہ نہ کرنے، ناشکری کی زبان استعمال کرنے اور آہ و بکاء اور پریشانی کا اظہار کرنے کی مذمت کا یہ مطلب قطعی نہیں ہے کہ انسان یہ خواہش کرنے لگے کہ اس پر مصائب اور آزمائشیں ٹوٹ پڑیں، بلکہ شریعت نے آزمائش کی خواہش کرنے سے منع فرمایا ہے۔ البتہ اگر بہ رضائے الٰہی کسی پر کوئی تکلیف یا مصیبت آن پڑتی ہے تو پھر اسے ہمت اور صبر سے برداشت کرنا چاہیے اور اسے گناہوں کی پاکیزگی کا باعث سمجھتے ہوئے اللہ تعالیٰ سے اجر کی اُمید رکھنی چاہیے۔ یہ بلاشبہ فضیلت والا عمل ہے، لیکن آزمائش اور مصیبت کی آرزو کرنا قطعاً ممدوح نہیں ہے۔"}],[175,"سیدنا ابن عمر رضی اللہ عنہما سے مروی ہے کہ نبی  صلی اللہ علیہ وسلم  نے فرمایا:\nمیں نے خواب میں ایک سیاہ فام عورت دیکھی، جس کے بال پراگندہ تھے اور اس سے بہت بدبو آ رہی تھی۔ وہ مدینہ سے نکلی اور جا کر مہیعہ مقام پر ٹھہر گئی۔ میں نے اس خواب کی تعبیر یہ کی ہے کہ مدینہ کی وباء کو اللہ تعالیٰ مہیعہ کی طرف منتقل کر دے گا۔","",{"k":"صحیح بخاری (۷۰۳۹)۔"}],[176,"سیدہ اسماء بنت ابی بکر رضی اللہ عنہا بیان کرتی ہیں کہ:\nمیری گردن میں پھوڑے پھنسیاں نکل آئے، میں نے اس کا تذکرہ سیدہ عائشہ رضی اللہ عنہا سے کیا اور کہا: میرے لیے نبی  صلی اللہ علیہ وسلم  سے (اس کا کوئی علاج) دریافت فرمائیے۔ چنانچہ انہوں نے آپ  صلی اللہ علیہ وسلم  سے پوچھا تو آپ نے فرمایا: اپنا ہاتھ اس پر رکھو اور تین مرتبہ یہ دعا پڑھو:\nبِسْمِ اللّٰہِ اللّٰہُمَّ أَذْہِبْ عَنِّی شَرَّ مَا أَجِدُ وَفُحْشَہٗ بِدَعْوَۃِ نَبِیِّکَ الطِّیبِ الْمُبَارَکِ الْمَکِینِ عِنْدَکَ بِسْمِ اللّٰہِ\n‘‘اللہ کے نام کے ساتھ، اے اللہ! جو میں تکلیف محسوس کر رہا ہوں؛ اس کو اور اس کی غلاظت کو مجھ سے دُور لے جا، اپنے نبی کی پاکیزہ اور بابرکت دعا کے ساتھ، جو تیرے ہاں رُتبے والا ہے، اللہ کے نام کے ساتھ۔’’\nچنانچہ میں نے ایسا ہی کیا تو ان کی سوزش اُتر گئی۔ ابوالفضل رحمہ اللہ فرماتے ہیں: میں نے جس کسی بھی ایسے مریض پر یہ دعا پڑھی جس کی موت کا وقت نہ آیا ہو، تو اللہ کے حکم سے وہ صحت یاب ہو گیا۔","",{"k":"الدعاء للطبرانی (۱۱۳۵)، تاریخ دمشق لابن عساکر (۵۰؍۷۲)۔"}],[177,"نبی  صلی اللہ علیہ وسلم  کی ایک زوجہ مطہرہ رضی اللہ عنہا بیان کرتی ہیں کہ:\nنبی صلی اللہ علیہ وسلم  میرے پاس تشریف لائے اور آپ کی دو اُنگلیوں کے درمیان پھنسی نکلی ہوئی تھی۔ آپ  صلی اللہ علیہ وسلم  نے پوچھا: کیا ذریرہ ہے؟ تو میں نے وہ آپ کو لا دِیا۔ آپ  صلی اللہ علیہ وسلم  نے اسے انگلی پر رکھا اور فرمایا:\nاَللّٰہُمَّ مُکَبِّرَ الصَّغِیرِ وَمُطْفِءَ الْکَبِیرِ أَطْفِءْہَا عَنِّی\n‘‘اے اللہ! چھوٹے کو بڑا کرنے والے اور بڑے کوختم کرنے والے! میری اس پھنسی کو ختم کر دے۔’’\nتو وہ پھنسی ختم ہو گئی۔","حسن",{"k":"مسند أحمد (۵؍۳۷۰)، السنن الکبرٰی للنسائی (۱۰۸۷۰)، المستدرک للحاکم (۴؍۲۳۰)، مجمع الزوائد للھیثمی (۵؍۹۵)۔","f":"ذریرہ ایک سفوف ہوتا ہے، جو زخم پر لگایا جاتا ہے۔"}],[178,"ربیعہ بن کلثوم بیان کرتے ہیں کہ:\nہم امام حسن رحمہ اللہ کے پاس حاضر ہوئے، انہیں داڑھ کی تکلیف تھی اور وہ فرما رہے تھے: ﴿مَسَّنِیَ الضُّرُّ وَأَنْتَ أَرْحَمُ الرَّاحِمِینَ﴾ ‘‘مجھے تکلیف آ پہنچی ہے اور تو ہی سب سے زیادہ رحم کرنے والا ہے۔’’","حسن",{"k":"شعب الإیمان للبیھقی (۱۲؍۳۸۳)۔"}],[179,"ابوغسان عباء ۃ رحمہ اللہ فرماتے ہیں کہ مجھے نیشاپور میں بخار ہو گیا اور مجھے شب و روز بخار ہی رہنے لگا، تو میں نے یہ دعا پڑھی:\n‘‘اے اللہ! جب بھی تو نے مجھے کوئی نعمت عطا فرمائی؛ تو میں نے اس نعمت کے ملنے پر بہت کم ہی شکر ادا کیا اور جب بھی تو نے مجھے کسی آزمائش میں مبتلا کیا؛ تو میں نے اس آزمائش کے آنے پر کم ہی صبر کا مظاہرہ کیا۔ اے وہ ذات کہ جس کی نعمت لینے پر بہت کم شکر ادا کیا جائے تو پھر بھی وہ مجھے رُسوا نہ کرے! اے وہ ذات کہ جس کی آزمائش آنے پر بہت کم صبر کیا جائے تو پھر بھی وہ مجھ پر عتاب نہ فرمائے! اور اے وہ ذات کہ جو مجھے نافرمانیاں کرتا دیکھ کر بھی رُسوا نہ کرے! میری تکلیف کو ختم کر دے۔’’\nتو اس دعا کی برکت سے میرا بخار اُتر گیا۔","حسن",{"k":"شعب الإیمان للبیھقی (۱۲؍۴۶۵)۔"}],[180,"محمد بن سالم بیان کرتے ہیں کہ مجھ سے ثابت رحمہ اللہ نے کہا:\nاے محمد! جب تجھے تکلیف ہو تو اپنا ہاتھ اس جگہ پر رکھو جہاں تکلیف ہو رہی ہو، پھر یہ دعا پڑھو:\nبِسْمِ اللّٰہِ، أَعُوذُ بِعِزَّۃِ اللّٰہِ وَقُدْرَتِہِ مِنْ شَرِّ مَا أَجِدُ مِنْ وَجَعِی ہٰذَا\n‘‘اللہ تعالیٰ کے نام کے ساتھ، میں اس شر سے؛ جو میں اپنی اس تکلیف سے محسوس کر رہا ہوں، اللہ کی عزت کی پناہ میں آتا ہوں۔’’\nپھر اپنا ہاتھ اُٹھا لو اور دوبارہ طاق عدد میں ایسا کرو۔ سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ یہ دَم رسول اللہ  صلی اللہ علیہ وسلم  نے بتلایا تھا۔","حسن",{"k":"سنن الترمذی (۳۵۸۸)، المستدرک للحاکم (۴؍۲۴۴)۔"}],[181,"سیدنا ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\nرسول اللہ  صلی اللہ علیہ وسلم  سیدنا حسن و حسین رضی اللہ عنہما کو (اللہ تعالیٰ کی) پناہ میں دِیا کرتے تھے اور فرماتے: تمہارے بابا حضرت ابراہیم علیہ السلام (اپنے صاحبزادگان) حضرت اسماعیل علیہ السلام اور حضرت اسحاق علیہ السلام کو ان کلمات کے ساتھ پناہ دِیا کرتے تھے:\nأُعِیذُکُمَا بِکَلِمَاتِ اللّٰہِ التَّامَّۃِ مِنْ کُلِّ شَیْطَانٍ وَہَامَّۃٍ وَمِنْ کُلِّ عَیْنٍ لَامَّۃٍ.\n‘‘میں تم دونوں کو اللہ کے کامل کلمات کی پناہ میں دیتا ہوں کہ ہر شیطان، ہر موذی چیز اور ہر بدنظر کے شر سے محفوظ رہو۔’’","حسن",{"k":"سنن أبی داود (۴۷۳۷)، سنن الترمذی (۲۰۶۰)، سنن ابن ماجہ (۳۵۲۵)، مسند أحمد (۴؍۲۰)، المصنف لابن أبی شیبۃ (۸؍۴۹)۔"}],[182,"سیدنا عبدالرحمان بن عوف رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nکیا میں تمہیں پناہ کی ایک دعا نہ سکھاؤں؟ میرے والد حضرت ابراہیم علیہ السلام اپنے صاحبزادوں اسحاق اور اسماعیل علیہ السلام کو انہی کے ساتھ پناہ دِیا کرتے تھے اور میں بھی حسن و حسین (رضی اللہ عنہما) کو انہی کے ساتھ ہی (اللہ کی) پناہ میں دیتا ہوں۔ میں نے عرض کیا: کیوں نہیں۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: یہ دعا پڑھا کرو:\nحَسْبِیَ اللّٰہُ وَکَفٰی، سَمِعَ اللّٰہُ دَاعِیًا لِمَنْ دَعَا لِأَمْرٍ مَا وَرَاءَ أَمْرِ اللّٰہِ لِرَامٍ رَمٰی\n‘‘مجھے اللہ ہی کافی ہے اور وہی کفایت کرے گا، اللہ تعالیٰ نے اس شخص کی دعا کو سن لیا جس نے اسے کسی ضرورت کے لیے پکارا، اللہ تعالیٰ کے بعد کوئی مشکلات حل نہیں کر سکتا۔’’","إسنادہ لیس بالقوی",{"k":"التمھید لابن عبد البر (۲۴؍۴۴۲)۔"}],[183,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nاے ابوہریرہ! کیا میں تمہیں ایک ایسا کام نہ بتاؤں جو حق ہے؟ جو شخص اپنی بیماری کے بعد (بستر مرض پر) لیٹنے کے پہلے ہی وقت میں وہ کلمات پڑھ لے گا؛ اللہ تعالیٰ ان کی برکت سے اسے جہنم سے نجات دے دے گا۔ میں نے عرض کیا: کیوں نہیں، میرے ماں باپ آپ پر قربان ہوں (ضرور بتلائیے)۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: جب تم یہ کلمات اپنی بیماری میں (بستر مرض پر) لیٹنے کے پہلے ہی وقت میں پڑھو گے تو اللہ تعالیٰ تمہیں جہنم سے آزاد فرما دے گا:\nلَا إِلٰہَ إِلَّا اللّٰہُ یُحْیِی وَیُمِیتُ وَہُوَ حَیُّ لَا یَمُوتُ، سُبْحَانَ رَبِّ الْعِبَادِ وَالْبِلَادِ، وَالْحَمْدُ لِلَّہِ کَثِیرًا طَیِّبًا مُبَارَکًا فِیہِ عَلٰی کُلِّ حَالٍ، اللّٰہُ أَکْبَرُ کَبِیرًا، کِبْرِیَاءُ رَبِّنَا وَجَلَالُہٗ وَقُدْرَتُہٗ بِکُلِّ مَکَانٍ، اللّٰہُمَّ إِنْ أَنْتَ أَمْرَضَتْنِی لِتَقْبِضَ رُوحِی فِی مَرَضِی ہٰذَا فَاجْعَلْ رُوحِی فِی أَرْوَاحِ مَنْ سَبَقَتْ لَہٗ مِنَّا الْحُسْنٰی، وَبَاعِدْنِی مِنَ النَّارِ کَمَا بَاعَدْتَ أُولٰئِکَ الَّذِینَ سَبَقَتْ لَہُمْ مِنَّا الْحُسْنٰی\n‘‘اللہ کے سوا کوئی معبود نہیں، وہی زندہ کرتا اور موت دیتا ہے، وہ ہمیشہ زندہ رہنے والی ذات ہے، اسے کبھی موت نہیں آئے گی۔ وہ ذات بہت پاک ہے جو بندوں کا پروردگار ہے اور بلاد کا رب ہے۔ تمام تعریفیں اللہ تعالیٰ ہی کو سزاوار ہیں، بہت زیادہ، پاکیزہ اور بابرکت، ہر حال میں۔ اللہ سب سے بڑا ہے۔ ہمارے رب کی کبریائی، اس کا جلال و عظمت اور اس کی قدرت ہر جگہ موجود ہے۔ اے اللہ! اگر تو نے مجھے اس لیے بیمار کیا ہے کہ اس بیماری میں تو میری رُوح قبض کرے تو میری رُوح کو ان ارواح میں شامل فرمانا جن کی نیکی ہم سے سبقت لے گئی ہے اور مجھے جہنم سے اسی طرح دُور رکھنا جس طرح تو نے ان لوگوں کو رکھا ہے جن کی نیکی ہم سے سبقت لے گئی ہے۔’’\nآپ  صلی اللہ علیہ وسلم  نے فرمایا: یہ دعا پڑھنے کے بعد اگر تجھے موت آ جاتی ہے تو تُو اللہ تعالیٰ کی رضامندی و خوشنودی اور جنت کی طرف گامزن ہو جائے گا اور اگر تجھ سے گناہ سرزد ہوئے ہوں تو اللہ تعالیٰ تجھے معاف فرما دے گا۔","حسن",{"k":"عمل الیوم واللیلۃ لابن السنی (۵۴۹)۔"}],[184,"سیدنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجب اللہ تعالیٰ مسلمان بندے کو کسی جسمانی آزمائش میں مبتلا کرتا ہے تو (عمل لکھنے والے) فرشتے سے فرماتا ہے: اس کا تندرستی والا عمل لکھتے رہو جو یہ کیا کرتا تھا۔ پھر اگر اسے شفا دے دے تو اسے (گناہوں سے) دھو ڈالتا ہے اور پاک کر دیتا ہے اور اگر اس کی جان قبض کر لے تو اس کو بخش دیتا ہے اور اس پر رحم فرماتا ہے۔","حسن",{"k":"مسند أحمد (۳؍۱۴۸)، مسند أبی یعلی الموصلی (۷؍۱۸۴)، شعب الإیمان للبیھقی (۷؍۱۸۴)، الترغیب والترھیب للمنذری (۲؍۳۰۴)۔"}],[185,"ابوبردہ رحمہ اللہ بیان کرتے ہیں کہ:\nمیں سیدنا معاویہ رضی اللہ عنہ کے پاس تھا اور طبیب ان کی کمر پر نکلے ہوئے پھوڑے کا علاج کر رہا تھا، تو وہ (درد کی وجہ سے) تڑپ رہے تھے۔ میں نے ان سے کہا: اگر ہمارا کوئی نوجوان ایسے کرتا تو ہم نے اس پر غصہ ہونا تھا۔ تو انہوں نے کہا: مجھے یہ بات اچھی نہیں لگے گی کہ مجھے درد محسوس نہ ہو، کیونکہ میں نے رسول اللہ  صلی اللہ علیہ وسلم  کو فرماتے سنا: کسی بھی مسلمان کو کوئی جسمانی تکلیف پہنچتی ہے تو وہ اس کے گناہوں کا کفارہ بن جاتی ہے۔","حسن",{"k":"مسند أحمد (۴؍۹۸)، المعجم الکبیر للطبرانی (۱۹؍۳۵۹)، شعب الإیمان للبیھقی (۷؍۱۶۸)، المستدرک للحاکم (۱؍۴۹۸)، الترغیب والترھیب للمنذری (۴؍۱۴۴)، مجمع الزوائد للھیثمی (۲؍۳۰۱)۔"}],[186,"سیدنا خوات بن جبیر رضی اللہ عنہ بیان کرتے ہیں کہ:\nایک دفعہ میں بیمار ہو گیا تو (تندرست ہونے کے بعد جب) میں رسول اللہ صلی اللہ علیہ وسلم  کی خدمت میں حاضر ہوا تو آپ صلی اللہ علیہ وسلم  نے فرمایا: اے خوات! تمہارا جسم تندرست ہو گیا ہے۔ میں نے عرض کیا: اے اللہ کے رسول! آپ کا جسم مبارک بھی تندرست ہے۔ پھر آپ  صلی اللہ علیہ وسلم  نے فرمایا: جو تم نے اللہ سے وعدہ کیا تھا اس کو پورا کرو۔ میں نے گزارش کی: اے اللہ کے رسول! میں نے تو اللہ سے کوئی وعدہ نہیں کیا تھا۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: ہر مریض بیمار ہو کر اپنے آپ سے کوئی اچھائی کی بات کرتا ہے (یعنی دِل میں کسی نیک کام کا ارادہ کرتا ہے) لہٰذا تم بھی اللہ تعالیٰ سے وہ وعدہ پورا کرو جو اس سے کیا تھا۔","ضعیف",{"k":"المستدرک للحاکم (۳؍۴۶۷)، الکامل لابن عدی (۶؍۱۴۶)۔"}],[187,"مصعب بیان کرتے ہیں کہ:\nجب عروہ رحمہ اللہ ولید کے ہاں سے واپس آئے تو انہوں نے فرمایا: میں مدینے میں داخل نہیں ہوں گا، کیونکہ وہاں تو میں اس تکلیف پر خوش ہونے والوں اور نعمت پر حسد کرنے والوں کے درمیان گھر جاؤں گا۔ چنانچہ وہ عقیق مقام پر واقع اپنے محل کی طرف چل پڑے اور ان کے ساتھ جو لوگ تھے، ان میں عیسیٰ بن طلحہ بھی تھے۔ جب آپ اس محل میں داخل ہو گئے تو عیسیٰ بن طلحہ نے آپ سے کہا: ہمیں وہ مصیبت دِکھلائیے جس کی ہم آپ سے تعزیت کر رہے ہیں۔ تو انہوں نے اپنے گھٹنے سے کپڑا ہٹا دِیا، تو عیسیٰ ؒ نے ان سے کہا: اللہ کی قسم! ہم آپ کو کشمکش کے لیے شمار نہیں کرتے، یقینا جس چیز کو اللہ تعالیٰ نے باقی رکھا ہے (یعنی آپ کے علم و دانش کو) وہ آپ کی عقل، زبان، سماعت و بصارت، دونوں ہاتھ اور ایک ٹانگ سے کہیں بڑی نعمت ہے۔ تو عروہ رحمہ اللہ نے ان سے کہا: اے عیسیٰ! کسی نے بھی مجھ سے ایسی تعزیت نہیں کی جیسی تعزیت آپ نے کی ہے۔","حسن",{"k":"تاریخ بغداد للخطیب (۹؍۵۰)۔"}],[188,"امام حسن رحمہ اللہ فرمایا کرتے تھے:\nتم صرف نشانہ لگانے کی ایک جگہ ہو، جس پر روزانہ تیروں سے نشانے بازی کی جاتی ہے، تم پر جو بھی کوئی بیماری آتی ہے وہ نشانے کا ایک تیر ہوتا ہے۔ جس سے عقل والا سمجھ بوجھ حاصل کرتا ہے اور جاہل نادانی میں رہتا ہے۔ یہاں تک کہ (ایک دِن) ایسا تیر آئے گا کہ جس کا نشانہ خطا نہیں ہو گا۔","",{"f":"یعنی انسان کو گاہے گاہے بیماریوں کے تیر لگتے رہتے ہیں، جو عقلمند ہوتا ہے وہ اس سے سبق حاصل کرتا ہے اور باقی کی زندگی کو اللہ کی دی ہوئی مہلت سمجھ کر اس کی خوب بندگی بجا لانے کی کوشش کرتا ہے جبکہ جو جاہل ہوتا ہے وہ نادانی میں ہی رہتا ہے اور ان امراض سے کچھ بھی سبق نہیں سیکھتا، بلکہ جیسا پہلے ہوتا ہے ویسے ہی باقی زندگی گزارتا چلا جاتا ہے۔ پھر ایک روز موت کا تیر آ لگے گا، جس کا نشانہ خطا نہیں ہو گا، پھر نہ کوئی مہلت باقی رہے گی اور نہ آخرت کی تیاری کا کوئی موقع ہاتھ آئے گا۔"}],[189,"امام معروف رحمہ اللہ فرماتے ہیں کہ:\nیقینا اللہ تعالیٰ اپنے مومن بندے کو بیماریوں اور تکالیف سے آزماتا ہے تو وہ اپنے ساتھیوں سے شکوے کرتا ہے، تو اللہ تعالیٰ فرماتا ہے: میری عزت اور میرے جلال کی قسم! میں نے تجھے ان تکالیف کے ساتھ صرف اس لیے آزمایا تھا؛ تاکہ تجھے گناہوں سے دھو سکوں، لہٰذا تو میرے شکوے مت کر۔","فیہ من لم أعرفہ",{"k":"تفرّد بہ المؤلف۔"}],[190,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجس بھی مسلمان کی جسمانی طور پر آزمائش کی جاتی ہے؛ اللہ تعالیٰ اس کی بیماری کے دوران اس کے نامہ اعمال میں سب سے زیادہ فضیلت والا وہ عمل لکھ دیتا ہے جو وہ تندرستی میں کیا کرتا تھا۔","حسن",{"k":"مسند أحمد (۳؍۱۴۸)، مسند أبی یعلی الموصلی (۴۲۳۳)، شعب الإیمان للبیھقی (۷؍۱۸۴)، الترغیب والترھیب للمنذری (۴؍۱۴۷)، مجمع الزوائد للھیثمی (۲؍۳۰۴)۔"}],[191,"سیدنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ نبی  صلی اللہ علیہ وسلم  نے فرمایا:\nجب اللہ تعالیٰ کسی قوم کے ساتھ خیر و بھلائی کا ارادہ فرماتا ہے تو ان کی آزمائش کرتا ہے۔","إسنادہ لا بأس بہ",{"k":"سنن الترمذی (۲۳۹۶)، سنن ابن ماجہ (۴۰۳۱)، مسند أبی یعلی الموصلی (۴۲۲۲)، المعجم الأوسط للطبرانی (۳۲۲۸)، مسند الشھاب للقضاعی (۱۱۲۱)، شعب الإیمان للبیھقی (۷؍۱۴۵)۔"}],[192,"سیدنا ابوسعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nمومن کا سر درد ہو، یا اسے کوئی کانٹا چبھ جائے، یا کوئی بھی چیز اسے تکلیف پہنچائے تو اللہ تعالیٰ اس کے بدلے میں قیامت کے روز ایک درجہ بلند فرما دے گا اور اسی کے صلے میں اس کے گناہوں کو مٹا دے گا۔","حسن",{"k":"شعب الإیمان للبیھقی (۷؍۱۶۸)، الترغیب والترھیب للمنذری (۴؍۱۵۱)۔"}],[193,"سیدنا ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ نبی  صلی اللہ علیہ وسلم  نے فرمایا:\nیہ کلمات ہر بیماری کی دوا ہیں:\nأَعُوذُ بِکَلِمَاتِ اللّٰہِ التَّامَّۃِ وَأَسْمَائِہٖ کُلِّہَا عَامَّۃٍ مِنْ شَرِّ السَّامَّۃِ وَالْہَامَّۃِ وَشَرِّ الْعَیْنِ اللَّامَّۃِ، وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ، وَمِنْ شَرِّ أَبِی قَتَرَۃَ وَمَا وَلَدَ\n‘‘میں اللہ تعالیٰ کے کامل کلمات اور اس کے تمام عام اسماء کے ساتھ ہر زہر، موذی چیز اور نظر بد کے شر سے، ہر حاسد کے شر سے جو حسد کرتا ہے اور افلاس و تنگدستی کے شر سے پناہ مانگتا ہوں۔’’\nتینتیس فرشتے اپنے پروردگار کے پاس آئے اور کہا: ہماری زمین میں بیماریاں پھوٹ پڑی ہیں۔ تو رب تعالیٰ نے فرمایا: اپنی زمین کی مٹی پکڑو اور اسے اپنی تکلیف کی جگہ پر لگا لو، یہ محمد  صلی اللہ علیہ وسلم  کا دَم ہے۔ جو شخص اس کو مال کمانے کا ذریعہ بنا لے یا کسی کو بتانے سے گریز کرے تو وہ کبھی فلاح نہیں پائے گا۔","ضعیف",{"k":"المعجم الأوسط للطبرانی (۶۰۹۳)، مسند أبی یعلی الموصلی (۲۴۱۶)، مجمع الزوائد للھیثمی (۵؍۱۱۰)۔"}],[194,"سیدہ عائشہ رضی اللہ عنہا نبی  صلی اللہ علیہ وسلم  کے بارے میں بیان کرتی ہیں کہ:\nآپ  صلی اللہ علیہ وسلم  جب بیمار ہوتے تھے تو معوّذات پڑھ کر خود پر پھونک مار لیتے تھے۔","",{"k":"صحیح بخاری (۴۴۳۹)، صحیح مسلم (۲۱۹۲)۔","f":"معوّذات سے مراد قرآنِ کریم کی آخری تین سورتیں (سورۃ الاخلاص، سورۃ الفلق اور سورۃ الناس) ہیں۔ سورۃ الاخلاص میں اگرچہ پناہ وغیرہ کے الفاظ کی صراحت نہیں ہے لیکن اللہ تعالیٰ کی صفات پر مشتمل ہونے کی وجہ سے اسے بھی معوّذ کا درجہ حاصل ہے۔"}],[195,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\nمیں نبی  صلی اللہ علیہ وسلم  کو (اللہ کی) پناہ میں دِیا کرتی تھی۔ جب آپ کو وہ مرض لاحق ہوا جس میں آپ رحلت فرما گئے تھے، تو میں (آپ  صلی اللہ علیہ وسلم  کے پاس) گئی اور اسی طرح کرنے لگی جیسے کیا کرتی تھی، تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: مجھ سے اپنا ہاتھ اُٹھا لو، کیونکہ یہ دعا مجھے ایک خاص مُدت تک ہی فائدہ دے سکتی تھی: أَذْہِبِ الْبَأْسَ رَبَّ النَّاسِ بِیَدِکَ الشِّفَاءُ لَا شَافِیَ إِلَّا أَنْتَ اشْفِ شِفَاءً لَا یُغَادِرُ سَقَمًا ‘‘اے لوگوں کے پروردگار! تکلیف کو ختم کر دے، تیرے ہی ہاتھ میں شفا ہے، تیرے علاوہ کوئی شفا دینے والا نہیں، ایسی شفا عطا فرما کہ جو بیماری کا نام و نشان تک نہ چھوڑے۔’’\nسیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ نبی  صلی اللہ علیہ وسلم  جب کسی مریض کے لیے دعا کرتے تو یوں فرماتے:\nاے لوگوں کو کے پروردگار! تکلیف کو ختم کر دے اور شفا عطا فرما دے، تو ہی شفا دینے والا ہے، تیرے سوا کوئی شفایاب نہیں کر سکتا۔","",{"k":"صحیح بخاری (۵۷۵۰)، صحیح مسلم (۲۱۹۱)۔\nصحیح بخاری (۵۷۴۲)۔","f":"آپ  صلی اللہ علیہ وسلم  کے اس فرمان کہ ‘‘یہ دعا مجھے ایک خاص مُدت تک ہی فائدہ دے سکتی تھی’’ کا مطلب یہ ہے کہ آپ  صلی اللہ علیہ وسلم  کو معلوم ہو گیا تھا کہ اب آپ کی وفات کا وقت قریب آ چکا ہے، اس لیے فرمایا کہ اب یہ دعا بھی مجھے فائدہ نہیں دے گی۔ وگرنہ اس سے پہلے تک یہ دعا آپ کی نظر میں کامل شفایابی کا دَم تھی۔"}],[196,"سیدنا علی رضی اللہ عنہ بیان کرتے ہیں کہ:\nنبی  صلی اللہ علیہ وسلم  جب کسی مریض کے پاس تشریف لاتے تو اسے انہی (مندرجہ بالا) جیسے کلمات کے ساتھ ہی (اللہ کی) پناہ میں دیتے تھے۔","إسنادہ لیس بالقوی",{"k":"مسند البزار (۳؍۸۰)، مسند عبد بن حمید (۶۶)۔"}],[197,"سیدنا محمد بن حاطب رضی اللہ عنہ بیان کرتے ہیں کہ:\nمیری پیٹھ جل گئی تو میری والدہ مجھے نبی  صلی اللہ علیہ وسلم  کے پاس لے گئیں۔ آپ  صلی اللہ علیہ وسلم  یہ کلمات پڑھ کر دَم کر کے پھونک مارنے لگے:\nأَذْہِبِ الْبَأْسَ رَبَّ النَّاسِ، وَاشْفِ وَأَنْتَ خَیْرُ شَافٍ.\n‘‘اے لوگوں کے پروردگار! تکلیف کو ختم کر دے اور شفا عطا فرما دے، شفا دینے والی تو ہی بہترین ذات ہے۔’’\nشعبہؒ کہتے ہیں: مجھے شک ہے کہ راوی نے یہ الفاظ بھی بیان کیے تھے:\nشِفَاءً لَا یُغَادِرُ سَقَمًا.\n‘‘ایسی شفا عطا فرما کہ جو بیماری کا نام و نشان تک نہ چھوڑے۔’’","حسن",{"k":"مسند أحمد (۳؍۴۱۸)، صحیح ابن حبان (۲۹۷۷)، المستدرک للحاکم (۴؍۷۰)، مجمع الزوائد للھیثمی (۵؍۱۱۳)، الآحاد والمثانی لابن أبی عاصم (۳۲۰۵)۔"}],[198,"سیدنا عثمان بن عفان رضی اللہ عنہ بیان کرتے ہیں کہ:\nرسول اللہ  صلی اللہ علیہ وسلم  میرے پاس تشریف لائے جب میں بیمار تھا اور آپ  صلی اللہ علیہ وسلم  نے فرمایا: میں تجھے اس چیز سے شر سے؛ جو تو محسوس کر رہا ہے، اس اللہ کی پناہ میں دیتا ہوں جو یکتا و بے نیاز ہے، نہ اس نے کسی کو جنم دیا ہے اور نہ ہی اسے جنم دِیا گیا ہے، اور نہ ہی اس کا کوئی کارساز ہے۔ آپ  صلی اللہ علیہ وسلم  نے سات مرتبہ یہ کلمات کہے۔ پھر جب آپ نے اُٹھنے کا ارادہ کیا تو فرمایا: اے عثمان! ان کلمات کے ساتھ پناہ مانگا کرو، کیونکہ میں نے اس سے بہتر کلمات کے ساتھ پناہ نہیں مانگی۔","ضعیف",{"k":"عمل الیوم واللیلۃ لابن السنی (۵۵۳)، الدعوات الکبیر للبیھقی (۵۲۵)، تاریخ بغداد للخطیب (۱۳؍۲۸۶)، الکامل لابن عدی (۲؍۳۸۲)۔"}],[199,"سیدنا علی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے ان کی عیادت کی تو فرمایا:\nجس مریض کی موت کا وقت نہ آیا ہو، وہ ان کلمات کے ساتھ (اللہ کی) پناہ مانگے تو اللہ تعالیٰ اس سے افاقہ فرما دیتا ہے:\nأَسْأَلُ اللّٰہَ الْعَظِیمَ رَبَّ الْعَرْشِ الْعَظِیمِ أَنْ یَشْفِیَکَ\n‘‘میں عظمت والے اللہ سے سوال کرتا ہوں جو کہ عرشِ عظیم کا رب ہے، کہ وہ تجھے شفا عطا فرما دے۔’’\nان کلمات کو سات مرتبہ پڑھے اور بار بار پڑھ کر خود پر دَم کرتا رہے۔","",{"k":"الدعاء للطبرانی (۱۱۱۳)۔"}],[200,"سیدنا عامر رضی اللہ عنہ بیان کرتے ہیں کہ:\nمیں جنگی علاقے میں تھا کہ جھنڈے اور نشانات بلند کیے گئے۔ میں نے پوچھا: یہ کیا ہے؟ تو بتلایا گیا کہ رسول اللہ  صلی اللہ علیہ وسلم  تشریف لے آئے ہیں۔ سو میں بھی آپ  صلی اللہ علیہ وسلم  کے پاس حاضر ہوا اور آپ کے پاس بیٹھ گیا۔ آپ ایک درخت کے سائے میں تھے۔ آپ کے لیے چادر بچھائی گئی تھی اور آپ  صلی اللہ علیہ وسلم  اس پر تشریف فرما تھے۔ اِرد گرد صحابہ کرام رضی اللہ عنہم تھے۔ صحابہ نے بیماریوں کا ذکر کیا تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: یقینا جب بندۂ مومن کو کوئی بیماری لگتی ہے، پھر اللہ تعالیٰ اسے اس بیماری سے عافیت دے دیتا ہے، تو وہ اس کے گزشتہ گناہوں کا کفارہ بن جاتی ہے اور آئندہ کی زندگی کے لیے نصیحت کا سبب بن جاتی ہے۔ اور جب منافق بیمار ہوتا ہے اور پھر عافیت پاتا ہے تو اس کی مثال اس اونٹ کی سی ہوتی ہے جسے اس کے مالک نے باندھا ہو اور پھر کھول دِیا ہو۔ اسے نہ تو یہ معلوم ہوتا ہے کہ باندھا کیوں تھا؟ اور نہ یہ پتا ہوتا ہے کہ کھولا کیوں ہے؟ ایک آدمی نے کہا: اے اللہ کے رسول! بیماریوں سے کیا مراد ہے؟ تو آپ  صلی اللہ علیہ وسلم  نے پوچھا: کیا تجھے کبھی کوئی بیماری نہیں لگی؟ اس نے کہا: نہیں۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: ہمارے پاس سے اُٹھ جا، تو ہم میں سے نہیں ہے۔","ضعیف",{"k":"سنن أبی داود (۳۰۸۹)، شعب الإیمان للبیھقی (۵؍۴۲۱)، الترغیب والترھیب للمنذری (۴؍۱۴۹)۔"}],[201,"ابن عونؒ بیان کرتے ہیں کہ:\nمحمد رحمہ اللہ جب بیمار ہوتے تھے تو کسی سے اس کا شکوہ نہ کرتے۔ راوی بیان کرتے ہیں کہ بسااوقات کہیں سے کوئی بات معلوم ہو جاتی تھی۔","رجالہ ثقات",{"k":"شعب الإیمان للبیھقی (۱۲؍۳۸۳)۔"}],[202,"ابوحیان التیمی بیان کرتے ہیں کہ:\nکچھ لوگ سوید بن مثعبہ رحمہ اللہ، جو کہ سیدنا عبداللہ رضی اللہ عنہ کے فاضل شاگردوں میں سے تھے، (کی عیادت کے لیے ان) کی خدمت میں حاضر ہوئے تو ان سے ان کا بیٹا کہہ رہا تھا: میری جان آپ پر قربان ہو! ہم آپ کو کھانے پینے کے لیے کیا پیش کریں؟ تو انہوں نے کمزور سی آواز کے ساتھ جواب دیا: موت کمر تک آن پہنچی ہے اور لیٹے لیٹے عرصہ بیت گیا ہے، اللہ کی قسم! مجھے ناخن کی تراش کے بہ قدر بھی یہ خواہش نہیں ہے کہ اللہ تعالیٰ مجھے اس بیماری سے صحت یاب کر دے۔","رجالہ ثقات",{"k":"الزھد لأحمد بن حنبل، ص: ۳۵۹، الزھد لابن المبارک (۴۶۳)، إحیاء علوم الدین للغزالی (۴؍۳۳۹)۔"}],[203,"ابوزُبید بیان کرتے ہیں کہ:\nمیں، نوف بکالی اور ایک اور آدمی، سیدنا ابوایوب رضی اللہ عنہ کی خدمت میں حاضر ہوئے جب وہ بیمار تھے۔ تو نوف نے کہا: اے اللہ! انہیں عافیت سے نواز اور شفا عطا فرما۔ تو انہوں نے فرمایا: تم اس طرح مت کہو، بلکہ یوں کہو: اے اللہ! اگر تو ان کی موت کا وقت آ چکا ہے تو ان کی مغفرت فرما اور اس پر رحم فرما، اور اگر اس کا وقت نہیں آیا تو انہیں عافیت سے نواز اور شفا عطا فرما، اور اس کو مؤخر کر دے۔","إسنادہ لا بأس بہ",{"k":"مسند أحمد (۳؍۱۴۸)، المصنف لابن أبی شیبۃ (۳؍۲۳۳)، شرح السنۃ للبغوی (۵؍۲۴۱)، مسند أبی یعلی الموصلی (۷؍۲۳۲)۔"}],[204,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nخیر و عافیت میں رہنے والے جب قیامت کے دِن ان لوگوں کے اجر و ثواب کو دیکھیں گے جو (دنیا میں) آزمائشوں کا شکار ہوتے رہے، تو وہ یہ خواہش کریں گے کہ کاش! ان کے چمڑوں کو قینچیوں سے کاٹ دیا جاتا۔","حسن",{"k":"سنن الترمذی (۴۰۲)، المعجم الصغیر للطبرانی (۲۴۱)، شعب الإیمان للبیھقی (۷؍۱۸۰)، المصنف لابن أبی شیبۃ (۱۰۸۲۹)۔","f":"دنیا میں فراخی و خوش حالی اور خیر و عافیت کی زندگی گزارنے والے لوگ جب روزِ قیامت ان لوگوں کو بے پناہ اجر و ثواب اور بے حساب انعامات ملتے دیکھیں گے کہ جو دنیا میں طرح طرح کی آزمائش میں مبتلا اور طرح طرح کے مصائب کا شکار رہے، تو وہ اپنی فراخی و خوش حالی کی تمام تر دنیوی زندگی کو ہیچ تصور کریں گے اور خواہش کریں گے کہ کاش! ہمیں دنیا میں آسودگی اور راحت ملنے کی بہ جائے اس قدر آزمایا جاتا کہ ہمارے جسم کے چمڑوں کو قینچیوں سے کاٹ دِیا جاتا لیکن اس کے عوض ہمیں آج کے اس اجر و ثواب سے نواز دِیا جاتا؛ تو ہمیں بہ خوشی قبول ہوتا۔"}],[205,"قیس بن ابوحازم بیان کرتے ہیں کہ:\nسیدنا خالد بن ولید رضی اللہ عنہ نے اپنی بیوی کو طلاق دے دی۔ پھر اس کے محاسن اور خوبیاں بیان کرنے لگے، تو ان سے پوچھا گیا: اے ابوسلیمان! آپ نے اسے طلاق کس وجہ سے دی؟ تو انہوں نے فرمایا: میں نے اس کے کسی ایسے کام کی وجہ سے اسے طلاق نہیں دی کہ جس سے مجھے پریشانی ہوئی ہو اور نہ ہی وہ مجھ سے براسلوک کرتی تھی، لیکن اسے میرے پاس آ کر کبھی کوئی آزمائش نہیں آئی۔","حسن",{"k":"سیر أعلام النبلاء للذھبی (۱؍۳۷۶)۔","f":"یعنی سیدنا خالد بن ولید رضی اللہ عنہ کو اس کا مسلسل عافیت اور فراخی میں رہنا گویا بھلا نہیں لگا اور اسے باعثِ خیر نہیں سمجھا، اسی بناء پر اسے طلاق دے دی۔"}],[206,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\nمیں اُمِ عبداللہ بن ابی ذئاب کی عیادت کے لیے گیا جب وہ بیمار ہوئیں، تو انہوں نے کہا: اے ابوہریرہ! میں سیدہ اُمِ سلمہ رضی اللہ عنہا کی بیماری میں ان کی عیادت کے لیے گئی تو انہوں نے میرے ہاتھ میں پھوڑا دیکھا اور کہا: میں نے رسول اللہ  صلی اللہ علیہ وسلم  کو فرماتے سنا: اللہ تعالیٰ جب کسی بندے کو آزمائش میں مبتلا کرتا ہے اور وہ آزمائش ایسی صورت میں آتی ہے کہ جسے وہ ناپسند کرتا ہے، تو اللہ تعالیٰ اس آزمائش کو اس کے لیے گناہوں کا کفارہ اور پاکیزگی کا باعث بنا دیتا ہے، اور یہ اسی صورت میں ہوتا ہے کہ بندہ اس آزمائش سے خلاصی کے لیے کسی غیر اللہ کے پاس دھکے نہ کھاتا پھرے یا اس سے خلاصی کے لیے کسی غیر اللہ سے دعا نہ مانگے۔","ضعیف",{"k":"الترغیب والترھیب للمنذری (۴؍۱۴۱)۔"}],[207,"سیار بن سلامہ بیان کرتے ہیں کہ:\nمیں ابوالعالیہ رحمہ اللہ کی اس مرض میں ان کی خدمت میں حاضر ہوا جس مرض میں ان کی وفات ہو گئی تھی تو انہوں نے فرمایا: یقینا مجھے بھی وہی معاملہ سب سے زیادہ پسند ہے جو اللہ تعالیٰ کو محبوب ہے۔","حسن",{"k":"صفۃ الصفوۃ لابن الجوزی (۳؍۲۱۲)۔","f":"یعنی اگر اللہ تعالیٰ کو یہ پسند ہے کہ وہ مجھے صحت یاب کر دے تو میں اسی پر خوش ہوں اور اگر اس کی یہ مرضی ہے کہ مجھے اپنے پاس بلا لے تو میں تب بھی اس کے فیصلے پر خوش ہوں۔"}],[208,"یحییٰ بن ابی ہشام ایک شامی شخص سے بیان کرتے ہیں کہ:\nکچھ لوگوں نے ایک مریض کی عیادت کی تو ان میں مہاجرین میں سے ایک صاحب بھی تھے، ان مہاجر نے کہا: یقینا مریض کو چار انعامات حاصل ہوتے ہیں: اس سے قلم کو اُٹھا لیا جاتا ہے (یعنی اس کے گناہ نہیں لکھے جاتے)، اس کا اجر اسی عمل کے مثل ہی لکھا جاتا ہے جو وہ تندرستی کی حالت میں کیا کرتا تھا اور بیماری اس کے ہر جوڑ میں گناہوں کا پیچھا کرتی ہے اور انہیں وہاں سے نکال باہر کرتی ہے۔ پھر اگر تو وہ زندہ رہے تو گناہوں سے بخشی ہوئی زندگی گزارتا ہے اور اگر وہ فوت ہو جائے تو ایسی موت پاتا ہے کہ اس کی مغفرت فرما دی گئی ہوتی ہے۔ راوی کہتے ہیں کہ یہ بات سن کر اس مریض نے کہا: اے اللہ! میں ہمیشہ بستر مرض پر ہی پڑا رہوں۔","",{"k":"الزھد لھناد (۱؍۲۵۲)۔"}],[209,"امام سفیان ثوری رحمہ اللہ بیان کرتے ہیں کہ:\nہم زبید الیامی رحمہ اللہ کے پاس بیٹھا کرتے تھے تو ہم ان سے کہتے: آپ اللہ تعالیٰ سے شفا کی دعا کریں۔ تو وہ فرماتے: اے اللہ! مجھے کمزور کر دے، مجھے کمزور کر دے۔","إسنادہ لا بأس بہ",{"k":"صفۃ الصفوۃ لابن الجوزی (۳؍۹۸)۔","f":"وہ اس طرح کی دعا اجر و ثواب کے حصول کے شوق و رغبت میں کرتے تھے کہ جس قدر بھی مجھ پر کمزوری آئے گی اسی قدر میرا اجر و ثواب بڑھتا جائے گا۔"}],[210,"عمرو بن مُرہ بیان کرتے ہیں کہ:\nربیع بن خثیم رحمہ اللہ کو فالج تھا اور ان کے منہ سے رال بہہ کر ان کی داڑھی پر گر رہی تھی۔ انہوں نے اسے پونچھنے کے لیے اپنا ہاتھ اُٹھایا لیکن اُٹھا نہ سکے۔ یہ دیکھ کر ابوبکر بن ماعز اٹھے اور انہوں نے اسے صاف کر دیا۔ ربیع رحمہ اللہ نے ان کی طرف دیکھا، پھر فرمایا: اے ابوبکر! اللہ کی قسم! مجھے یہ بات اچھی نہیں لگتی کہ یہ تکلیف جو مجھ پر آئی ہے؛ اسے ہٹانا اللہ کے لیے کوئی مشکل کام ہو۔","حسن",{"k":"شعب الإیمان للبیھقی (۱۲؍۳۴۹)، الزھد لھناد (۱؍۲۳۱)، حلیۃ الأولیاء لأبی نعیم (۲؍۱۱۵)، سیر أعلام النبلاء للذھبی (۴؍۲۶۰)۔","f":"یعنی اگر اللہ تعالیٰ نے کسی مصیبت میں انسان کے لیے خیر و بھلائی نہ رکھی ہو تو وہ اسے دُور کرنے پر بھی قادر ہے۔ سو اگر وہ کسی کی مصیبت کو رفع نہیں کرتا تو اس کا مطلب یہ ہے کہ اللہ تعالیٰ کو ابھی اسے مزید گناہوں سے پاک کرنا ہے اور اس کے درجات کو مزید بلند کرنا ہے۔"}],[211,"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی  صلی اللہ علیہ وسلم  نے فرمایا:\nاہل دنیا میں سے جب کسی بندے کی آزمائش کی جاتی ہے تو اللہ تعالیٰ اس کی طرف دو فرشتوں کو بھیجتا ہے اور فرماتا ہے: میرے بندے کے پاس جاؤ، اگر وہ اچھی بات کہے اور عیادت کرنے والوں سے میرا کوئی شکوہ نہ کرے تو میں اسے اس کو ایسے گوشت میں بدل دوں گا جو اس کے گوشت سے بہتر ہو گا اور (اس کے جسم میں) ایسا خون (جاری کر) دوں گا جو اس کے خون سے بہتر ہو گا، پھر اگر میں نے اس کی جان قبض کر لی تو میں اس کے لیے جنت واجب کر دوں گا اور اگر اسے (بیماری کی) اس قید سے آزاد کر دِیا جس میں وہ بند تھا، تو اس کا عمل جاری رہے گا (یعنی وہ بیماری کی حالت میں عمل نہیں بھی کر رہا ہو تو اس کو عمل کا ثواب ملتا رہتا ہے)۔","ضعیف",{"k":"السنن الکبرٰی للبیھقی (۳؍۳۷۵)، المستدرک للحاکم (۱؍۵۰۰)۔"}],[212,"زُریک بن ابوزُریک بیان کرتے ہیں کہ:\nخالد الربعی رحمہ اللہ کو جو بھی تکلیف ہوتی تھی وہ کسی سے شکوہ نہیں کرتے تھے۔ ایک مرتبہ انہیں ذات الجنب کی بیماری لگ گئی اور انہیں خون والی بلغم آنے لگی، تو وہ اس تکلیف پر کراہ اُٹھے، حالانکہ وہ کسی تکلیف پر کراہتے نہیں تھے۔ پھر جب انہیں اس غلطی کا احساس ہوا تو فرمایا: اے اللہ! یہ میرے کس گناہ کا بدلہ ہے کہ میں اس تکلیف پر کرانے لگ گیا ہوں جس میں تو نے مجھے مبتلا کیا ہے۔","حسن",{"k":"تفرّد بہ المؤلف۔"}],[213,"سیدنا ابوالدرداء رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ  صلی اللہ علیہ وسلم  کو فرماتے سنا:\nیقینا سر کی تکلیف اور اندرونی بخار جس مومن شخص کو ہو جاتے ہیں تو اس پر رائی کے دانے کے برابر بھی کوئی گناہ نہیں چھوڑتے، خواہ اس کے گناہ اُحد پہاڑ کے برابر ہی ہوں۔","حسن",{"k":"مسند أحمد (۵؍۱۹۸)، المعجم الأوسط للطبرانی (۶۳۴)، شعب الإیمان للبیھقی (۷؍۱۷۵)، مجمع الزوائد للھیثمی (۲؍۳۰۱)۔"}],[214,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nیقینا جب اللہ تعالیٰ کسی بندے سے محبت فرماتا ہے یا اسے (گناہوں سے) پاک صاف کرنا چاہتا ہے تو اس پر کوئی آزمائش ڈال دیتا ہے اور پھر اس پر (آزمائشیں) ڈالتا ہی جاتا ہے۔ پھر جب بندہ دعا کرتا ہے اور کہتا ہے: اے میرے پیارے پروردگار۔ تو اللہ تعالیٰ فرماتا ہے: میرے بندے میں حاضر ہوں۔ تو مجھ سے جو بھی مانگے گا میں تجھے عطا کروں گا، یا تو میں تجھے وہ فوراً عطا کر دوں گا، یا پھر تیرے لیے ذخیرہ کر لوں گا۔","ضعیف",{"k":"الترغیب والترھیب للمنذری (۴؍۱۴۲)۔","f":"آزمائشوں کا تسلسل سے آنا اللہ تعالیٰ کی محبت اور گناہوں سے پاکی کا باعث ہونے کی علامت ہے، اس لیے انسان پے در پے مصائب آنے پر دِلبرداشتہ ہو کر اپنی قسمت کو کوسنا اور ناشکری کی باتیں کرنا نہ شروع کر دے بلکہ صبر کا مظاہرہ کرتے ہوئے ثابت قدمی سے انہیں جھیلے اور اللہ تعالیٰ سے اجر و ثواب کی اُمید رکھے۔ یقینا اس کا صبر ثمرآور ثابت ہو گا۔ نیز مریض شخص کی دعا قبول ہوتی ہے، وہ جو بھی جائز دعا کرتا ہے اللہ تعالیٰ اسے قبولیت سے نوازتا ہے۔ البتہ قبولیت کی دو صورتیں ہو سکتی ہیں: یا تو اللہ تعالیٰ اس کی مانگی ہوئی چیز اسے فوراً عطا فرما دے، یا پھر روزِ قیامت کے لیے اسے ذخیرہ کر لے۔ گویا جو بھی وہ اللہ تعالیٰ سے مانگے گا وہ اسے ضرور مل کر رہے گا۔ خواہ دنیا میں مل جائے یا کل قیامت کے روز ملے، کہ جہاں اسے دنیا سے زیادہ ضرورت ہو گی۔"}],[215,"امام حسن بصری رحمہ اللہ اللہ تعالیٰ کے اس فرمان: ﴿إِنَّ الْإِنْسَانَ لِرَبِّہٖ لَکَنُودٌ﴾ [العادیات: ۶] ‘‘یقینا انسان اپنے رب کا بہت ناشکرا ہے۔’’ کی تفسیر میں فرماتے ہیں: اس کا مطلب یہ ہے کہ انسان مصیبتوں اور پریشانیوں کو یاد رکھتا ہے اور اللہ تعالیٰ کی نعمتوں کو بھلا دیتا ہے۔","",{}],[216,"امام سفیان رحمہ اللہ سے مروی ہے کہ بعض فقہاء فرماتے ہیں:\nیہ بات بھی صبر کا حصہ ہے کہ آپ اپنی مصیبت اور تکلیف کو (کسی سے) بیان نہ کریں اور نہ ہی اپنے نفس کی پاکی بیان کریں۔","فیہ جھالۃ",{"k":"شعب الإیمان للبیھقی (۱۲؍۳۸۳)۔","f":"نفس کی پاکی بیان کرنے سے مراد یہ ہے کہ کسی کے پاس اپنے صبر اور برداشت کا تذکرہ نہ کریں کہ مجھے اتنی مدت سے یہ مرض لاحق ہے لیکن میں صبر کر رہا ہوں، برداشت سے کام لے رہا ہوں، وغیرہ۔ کیونکہ اس سے ریاکاری کا اندیشہ ہوتا ہے، جو اجر و ثواب کے ضیاع کا باعث ہے۔"}],[217,"سیدنا سعد رضی اللہ عنہ سے مروی ہے کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nمسلمان کا معاملہ بھی بہت دِلچسپ ہے، اگر اسے بھلائی پہنچتی ہے تو وہ اللہ تعالیٰ کی تعریف بیان کرتا ہے اور شکر ادا کرتا ہے اور جب اسے کوئی مصیبت پہنچتی ہے تو وہ اجر و ثواب کی اُمید رکھتے ہوئے صبر کا مظاہرہ کرتا ہے۔ یقینا مسلمان کو ہر چیز میں اجر سے نوازا جاتا ہے، یہاں تک کہ اس لقمے کا بھی اسے اجر ملتا ہے جو وہ اپنے منہ میں ڈالتا ہے۔","حسن",{"k":"مسند أحمد (۱؍۱۸۲)، الزھد لابن المبارک (۱۱۵)، مجمع الزوائد للھیثمی (۷؍۲۰۹)۔"}],[218,"سیدنا عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ:\nمیں رسول اللہ  صلی اللہ علیہ وسلم  کی خدمت میں حاضر ہوا تو آپ کو بخار ہوا پڑا تھا۔ میں نے آپ پر اپنا ہاتھ رکھا، تو عرض کیا: اے اللہ کے رسول! آپ کو تو بہت ہی سخت بخار ہے۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: ہاں، مجھے تم میں سے دو آدمیوں کے برابر بخار ہوتا ہے۔ سنو! جو بھی بندۂ مومن بیمار ہوتا ہے تو اللہ تعالیٰ اس کے گناہوں کو اس طرح گراتا ہے جس طرح درخت اپنے پتے گراتا ہے۔","",{"k":"صحیح بخاری (۵۶۴۷)، صحیح مسلم (۲۵۷۱)۔"}],[219,"امام حسن بصری رحمہ اللہ فرماتے ہیں:\nجو شخص کسی آزمائش میں مبتلا کیا جاتا ہے اور وہ تین دِن تک اسے چھپائے رکھتا ہے (یعنی) کسی سے شکوہ و شکایت نہیں کرتا، تو اللہ تعالیٰ اس وجہ سے اسے انعام میں اپنی رحمت سے نوازتا ہے۔","فیہ جھالۃ",{"k":"شعب الإیمان للبیھقی (۱۲؍۳۷۸)۔"}],[220,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\nمیں نے عرض کیا: اے اللہ کے رسول! یقینا میں خوب جانتی ہوں کہ قرآنِ کریم میں کون سی آیت سب سے سخت ہے۔ آپ  صلی اللہ علیہ وسلم  نے استفسار فرمایا: اے عائشہ! کون سی آیت ہے؟ میں نے عرض کیا: اے اللہ کے رسول! وہ یہ آیت ہے: ﴿مَنْ یَعْمَلْ سُوءً ا یُجْزَ بِہٖ﴾ ‘‘جو شخص برائی کرے گا؛ اسے اس کا بدلہ دِیا جائے گا۔’’ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: بندۂ مومن کو جو کوئی مصیبت آتی ہے، یہاں تک کہ اگر کانٹا بھی چھبتا ہے، تو یہ بدلہ ہی ہے۔","إسنادہ لا بأس بہ",{"k":"مسند أحمد (۶؍۲۱۸)، مسند أبی داود الطیالسی (۱۵۸۴)، سنن الترمذی (۲۹۹۱)۔","f":"یعنی اللہ تعالیٰ مومن کی برائیوں کا بدلہ مصائب و تکالیف کی صورت میں ہی دے دیتا ہے تاکہ وہ اپنے پیارے بندے کو آخرت میں عذاب سے محفوظ رکھ سکے۔"}],[221,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nمومن کو کانٹا چبھنے کی یا اس سے بھی کم مصیبت آتی ہے تو اللہ تعالیٰ اس کے بدلے میں اس کا ایک درجہ بلند فرما دیتا ہے اور اس کا ایک گناہ معاف فرما دیتا ہے۔","",{"k":"صحیح بخاری (۵۶۴۰)، صحیح مسلم (۲۵۷۲)۔"}],[222,"سیدنا عمرو بن حزم رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجو شخص کسی مریض کی عیادت کے لیے جاتا ہے تو وہ رحمت میں گھسا رہتا ہے، یہاں تک کہ جب وہ اس کے پاس جا بیٹھتا ہے تو وہ اس میں (یعنی رحمت میں) ٹھہر جاتا ہے۔ پھر جب وہ اس کے پاس سے کھڑا ہوتا ہے تو جب تک واپس نہیں آ جاتا تب تک رحمت میں ہی داخل رہتا ہے۔","حسن",{"k":"المعجم الأوسط للطبرانی (۵۲۹۶)، السنن الکبرٰی للبیھقی (۴؍۵۹)، مسند عبد بن حمید (۲۸۸)، الترغیب والترھیب للمنذری (۴؍۱۶۶)۔"}],[223,"نافع رحمہ اللہ بیان کرتے ہیں کہ جب سیدنا ابن عمر رضی اللہ عنہما کو کوئی تکلیف یا مصیبت پہنچتی تو وہ یہ دعا فرماتے:\nاے اللہ! ہم سے اس عذاب کو ہم سے دُور کر دے۔","رجالہ ثقات",{"k":"مسند البزار (۱؍۳۶۴)، مجمع الزوائد للھیثمی (۲؍۳۰۶)۔"}],[224,"عطاء بن ابی رباح رحمہ اللہ بیان کرتے ہیں کہ:\nسیدنا ابن عباس رضی اللہ عنہما نے مجھ سے کہا: کیا میں تمہیں جنتی عورت نہ دِکھاؤں؟ میں نے عرض کیا: کیوں نہیں۔ تو انہوں نے کہا: یہ سیادہ فام عورت نبی  صلی اللہ علیہ وسلم  کی خدمت میں حاضر ہوئی اور کہا: مجھے مرگی کا دورہ پڑتا ہے اور میں بے پردہ ہو جاتی ہوں، لہٰذا میرے لیے اللہ تعالیٰ سے (شفا کی) دعا فرما دیجیے۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: اگر تم صبر کر لو تو تمہیں جنت ملے گی، اور اگر تم چاہتی ہو تو میں اللہ سے دعا کر دیتا ہوں، وہ تجھے شفا عطا فرما دے گا۔ تو اس نے کہا: میں بے پردہ ہو جاتی ہوں، بس آپ اللہ تعالیٰ سے یہ دعا فرما دیں کہ میں بے پردہ نہ ہوں۔ تو آپ  صلی اللہ علیہ وسلم  نے اس کے لیے دعا فرما دی۔","",{"k":"صحیح بخاری (۵۶۵۲)، صحیح مسلم (۲۵۷۶)۔"}],[225,"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی  صلی اللہ علیہ وسلم  نے فرمایا:\nجو بھی بندہ کسی مرض میں مبتلا ہوتا ہے تو اللہ تعالیٰ فرشتے کو حکم فرماتا ہے: یہ جو بھی کوئی برا عمل کرے تو وہ اسے نہ لکھے اور جو وہ نیک عمل کرے اسے (ایک نیکی کے بہ جائے) دس نیکیاں لکھے، مزید وہ بیماری کے دِنوں میں اس کے وہ اعمال بھی لکھتا رہے جو وہ تندرستی کی حالت میں کیا کرتا تھا، اگرچہ اب اس نے وہ عمل نہ بھی کیا ہو۔","ضعیف",{"k":"مسند أبی یعلی الموصلی (۶۶۳۸)، الترغیب والترھیب للمنذری (۴؍۱۴۷)، مجمع الزوائد للھیثمی (۲؍۳۰۴)۔"}],[226,"عطاء بن ابی رباح رحمہ اللہ بیان کرتے ہیں کہ سیدنا ابوہریرہ رضی اللہ عنہ نے فرمایا:\nاس بخار سے زیادہ مجھے کوئی بیماری پسند نہیں ہے، کیونکہ یہ ہر جوڑ میں داخل ہو جاتا ہے اور بلاشبہ اللہ تعالیٰ ہر جوڑ کو اس کے حصے کا اجر و ثواب عنایت فرماتا ہے۔","حسن",{"k":"شعب الإیمان للبیھقی (۱۲؍۲۸۵)، المصنف لابن أبی شیبۃ (۳؍۲۳۲)۔"}],[227,"سیدنا عبداللہ بن خبیب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے اپنے صحابہ سے فرمایا:\nکیا تم پسند کرتے ہو کہ تمہیں کوئی مرض نہ لگے؟ صحابہ رضی اللہ عنہم نے عرض کیا: اے اللہ کے رسول! قسم بہ خدا ہم عافیت میں رہنا ہی پسند کرتے ہیں۔ تو رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا: تم میں سے کسی شخص کی بھلائی اس میں نہیں ہے کہ اسے اللہ تعالیٰ یاد نہ کرے۔","إسنادہ لیس بالقوی",{"k":"الترغیب والترھیب للمنذری (۴؍۱۴۶)۔","f":"گویا جس شخص کو اللہ تعالیٰ کسی مرض میں مبتلا کرتا ہے وہ اللہ کے ان خاص لوگوں میں شمار ہوتا ہے جنہیں اللہ تعالیٰ یاد رکھتا ہے، یقینا یہ بہت بڑے اعزاز کی بات ہے۔ اور اللہ کے یاد کردہ لوگوں میں شامل نہ ہونے کی خواہش رکھنا بلاشبہ خیر و بھلائی سے محرومی ہے۔"}],[228,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ:\nبخار نبی  صلی اللہ علیہ وسلم  کے پاس آیا تو آپ  صلی اللہ علیہ وسلم  نے پوچھا: تم کون ہو؟ اس نے کہا: میں اُمِ ملدم (یعنی بخار) ہوں۔ آپ  صلی اللہ علیہ وسلم  نے فرمایا: اہل قباء کے پاس جا رہے ہو؟ اس نے کہا: جی ہاں۔ آپ  صلی اللہ علیہ وسلم  نے فرمایا: چنانچہ وہ ان کے پاس چلا آیا۔ جب انہیں بخار ہو گیا اور انہوں نے اس کی شدت محسوس کی تو آپ  صلی اللہ علیہ وسلم  سے شکایت کرتے ہوئے عرض کیا: اے اللہ کے رسول! ہمیں تو بخار ہو گیا ہے۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: اگر تم چاہو تو میں اللہ تعالیٰ سے دعا کر دیتا ہوں؛ وہ تمہارا بخار اُتار دے گا اور اگر چاہو تو (صبر کرو، کیونکہ) یہ تمہارے لیے (گناہوں سے) پاکیزگی کا باعث بن جائے گا۔ تو انہوں نے کہا: پھر تو یہ ہمارے گناہوں کی پاکیزگی کا باعث ہی بن جائے۔","حسن لغیرہ",{"k":"مسند أحمد (۳؍۳۱۶)، مسند أبی یعلی الموصلی (۱۸۹۲)، صحیح ابن حبان (۲۹۳۵)، الترغیب والترھیب للمنذری (۴؍۱۵۳)، مسند عبد بن حمید (۱۰۲۳)، مجمع الزوائد للھیثمی (۲؍۳۰۶)۔"}],[229,"محمد بن جبیر رحمہ اللہ سے مروی ہے کہ نبی  صلی اللہ علیہ وسلم  نے فرمایا:\nیقینا اللہ تعالیٰ بیماری کے ذریعے اپنے بندے کو آزماتا ہے، یہاں تک کہ اس کی وجہ سے اس کے تمام گناہوں کو ختم کر دیتا ہے۔","حسن، لکنہ مرسل",{"k":"المعجم الکبیر للطبرانی (۲؍۱۲۹)، مجمع الزوائد للھیثمی (۲؍۳۰۲)، المستدرک للحاکم (۱؍۳۴۸)، الترغیب والترھیب للمنذری (۴؍۲۹۷)۔"}],[230,"ابوعمران رحمہ اللہ فرماتے ہیں:\nجب مریض (تکلیف کی وجہ سے) روتا دھوتا ہے تو گناہ گار ہوتا ہے، ایسی صورت میں جو فرشتہ دائیں طرف (یعنی ثواب لکھنے پر) مقرر ہوتا ہے وہ اس بائیں جانب مقرر فرشتے سے کہتا ہے: (اس کا گناہ) مت لکھنا۔","رجالہ ثقات",{"k":"تفرّد بہ المؤلف۔"}],[231,"امام حسن رحمہ اللہ بیان کرتے ہیں کہ:\nسیدنا عمران بن حصین رضی اللہ عنہ کو جسم کی کسی تکلیف میں مبتلا کر دیا گیا تو انہوں نے فرمایا: میں سمجھتا ہوں کہ یہ تکلیف کسی ایک گناہ کی وجہ سے ہی آئی ہے، جبکہ اللہ تعالیٰ جن گناہوں کو معاف فرما دیتا ہے؛ وہ اس سے کہیں زیادہ ہیں۔ اور انہوں نے یہ آیت پڑھی: ﴿وَمَا أَصَابَکُمْ مِنْ مُصِیبَۃٍ فَبِمَا کَسَبَتْ أَیْدِیکُمْ وَیَعْفُو عَنْ کَثِیْرٍ﴾ ‘‘اور تمہیں جو بھی مصیبت پہنچتی ہے وہ تمہارے ہی ہاتھوں کی کمائی ہوتی ہے (یعنی تمہارے گناہوں کا ہی نتیجہ ہوتی ہے) اور اللہ تعالی بہت ساروں کو تو معاف فرما دیتا ہے۔’’","صحیح",{"k":"شعب الإیمان للبیھقی (۱۲؍۲۵۲)، المستدرک للحاکم (۲؍۴۴۵)، المعجم الکبیر للطبرانی (۱۸؍۱۰۷)، مجمع الزوائد للھیثمی (۲؍۳۰۲)۔"}],[232,"سیدنا بریدہ اسلمی رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی  صلی اللہ علیہ وسلم  کو فرماتے سنا:\nمسلمانوں میں سے جس بھی شخص کو کوئی مصیبت آتی ہے، یا اس سے بھی چھوٹی کوئی تکلیف، یعنی کانٹا بھی چبھتا ہے تو وہ (تکلیف) ضرور ان دو باتوں میں سے کسی ایک کی وجہ سے آئی ہوتی ہے: (۱) یا تو اللہ تعالی اس کا کوئی ایسا گناہ بخشنا چاہ رہا ہوتا ہے جو ایسی تکلیف سے ہی بخشا جا سکتا تھا (۲) یا پھر اسے ایسے اعزاز و اکرام سے نوازنا چاہ رہا ہوتا ہے جو اس جیسی تکلیف سے ہی اسے حاصل ہو سکتا تھا۔","ضعیف",{"k":"شعب الإیمان للبیھقی (۷؍۱۶۳)، الترغیب والترھیب للمنذری (۴؍۱۴۳)۔"}],[233,"سعید بن عبدالجبار مرفوعاً روایت کرتے ہیں (یعنی نبی  صلی اللہ علیہ وسلم  نے فرمایا):\nجس شخص نے اس روز بخار کو چھپایا (یعنی کسی سے تذکرہ نہ کرے) جس روز اسے بخار ہوا ہو تو اللہ تعالی اسے گناہوں سے اس طرح نکال لیتا ہے جیسے وہ اس دِن (گناہوں سے پاک و صاف) تھا جس دِن اس کی ماں نے اسے جنم دِیا تھا، اللہ اس کے لیے جہنم سے براء ت لکھ دیتا ہے اور اس کے عیوب کی اسی طرح پردہ پوشی فرماتا ہے جس طرح اس نے دنیا میں اللہ کی آزمائش کو چھپایا تھا۔","ضعیف",{"k":"شرح مشکل الآثار للطحاوی (۳؍۴۸)۔"}],[234,"غالب القطان رحمہ اللہ بیان کرتے ہیں کہ:\nنبی  صلی اللہ علیہ وسلم  ذی النخامہ رضی اللہ عنہ کے پاس تشریف لائے اور وہ بیمار تھے، تو آپ  صلی اللہ علیہ وسلم  نے پوچھا: کتنے دِنوں سے بیمار ہو؟ انہوں نے کہا: اے اللہ کے رسول! سات دِن سے۔ تو آپ  صلی اللہ علیہ وسلم  نے فرمایا: (دو کاموں میں سے کسی ایک کو) اختیار کرو، اگر تم چاہو تو میں اللہ تعالی سے دعا کرتا ہوں وہ تجھے صحت یاب کر دے گا اور اگر تم چاہو تو تین دِن تک صبر کرو، اس سے تم گناہوں سے اس دِن کی طرح نکل جاؤ گے جس دِن تمہاری ماں نے تمہیں جنم دِیا تھا۔ تو انہوں نے کہا: اے اللہ کے رسول! میں صبر ہی کرتا ہوں۔","مرسل",{"k":"تفرّد بہ المؤلف۔"}],[235,"سیدنا ابوسعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ:\nایک آدمی نبی  صلی اللہ علیہ وسلم  کی خدمت میں حاضر ہوا اور اس نے عرض کیا: اے اللہ کے رسول! میں عمر رسیدہ ہو چکا ہوں، میرا جسم بھی بیمار رہنے لگا ہے اور مال بھی ختم ہو چکا ہے۔ تو رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا: اس جسم میں کوئی خیر و بھلائی نہیں ہوتی جس کی آزمائش نہ کی جائے اور نہ ہی اس مال میں خیر و بھلائی ہوتی ہے جس میں کمی نہ ہو۔ یقینا جب اللہ تعالی کسی بندے سے محبت فرماتا ہے تو اسے آزماتا ہے اور جب وہ اسے آزماتا ہے تو اسے صبر کی توفیق بھی دیتا ہے۔","ضعیف",{"k":"الصبر والثواب علیہ لابن أبی الدنیا (۱۸۵)۔"}],[236,"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ نبی  صلی اللہ علیہ وسلم  نے فرمایا:\nجس بھی مسلمان کو کانٹا چبھ جائے یا اس سے بھی چھوٹی تکلیف ہو، تو وہ اس کے گناہوں کا کفارہ بن جاتی ہے۔","",{"k":"صحیح بخاری (۵۶۴۰)، صحیح مسلم (۲۵۷۲)۔"}],[237,"حجاج بن فرافصہ بیان کرتے ہیں کہ رسول اللہ  صلی اللہ علیہ وسلم  نے فرمایا:\nجو بھی مریض (یہ دعا) پڑھے گا، اللہ تعالی اسے شفا عطا فرما دے گا:\nسُبْحَانَ الْمَلِکِ الْقُدُّوسِ الرَّحْمٰنِ الْمَلِکِ الدَّیَّانِ، لَا إِلٰہَ إِلَّا أَنْتَ، مُسَکِّنَ الْعُرُوقِ الضَّارِیَۃِ، وَمُنِیمَ الْعُیُونِ السَّاہِرَۃِ سَکِّنْ عُرُوقِی الضَّارِیَۃَ، وَنَوِّمْ عَیْنِی السَّاہِرَۃَ.\n‘‘پاک ہے وہ ذات جو بادشاہ ہے، بہت پاک ہے، نہایت رحم والا ہے، بادشاہ ہے اور جزا دینے والا ہے۔ تیرے سوا کوئی معبود نہیں۔ اے تکلیف میں مبتلا رَگوں کو سکون دینے والے اور بے خواب آنکھوں کو نیند دینے والے! میری تکلیف کی ماری رَگوں کو سکون دے دے اور میری نیند سے محروم آنکھ کو سُلا دے۔’’\nآخِرُ کِتَابِ الْمَرَضِ وَالْکَفَّارَاتِ لِابْنِ أَبِی الدُّنْیَا","",{}]]);
